import { catchError, Observable } from 'rxjs';
import { AxiosError } from 'axios';
import { CustomHttpResponseHelper } from '@common/helpers/custom-http-response-helper.helper';
import { Logger } from '@nestjs/common';

interface ApiErrorResponse {
  message: string;
}

export function handleHttpErrors(contextMessage: string) {
  const originError = new Error();
  return <T>(source: Observable<T>): Observable<T> => {
    return source.pipe(
      catchError((error: AxiosError) => {
        const serverError = error as AxiosError<ApiErrorResponse>;
        const { serviceName, locationContext } = parseOriginStack(
          originError.stack,
        );
        const message = getMessageError(serverError?.response?.data);
        const logger = new Logger(serviceName);

        logger.error(
          `${contextMessage} [${locationContext}] | Status: ${error.response?.status} | URL: ${error.config?.url} | Message: ${message}`,
          originError.stack,
        );
        if (error.response) {
          CustomHttpResponseHelper.handleResponse(error.response);
        }

        CustomHttpResponseHelper.handleAxiosError(error);
      }),
    );
  };

  /**
   * Extrae de forma segura y ultra-defensiva el mensaje de error de una API externa.
   * Se usa 'unknown' para permitir validar tanto JSONs estructurados como strings/HTMLs crudos.
   */
  function getMessageError(responseData: unknown): string {
    let apiMessage = 'No Message';
    if (responseData !== undefined && responseData !== null) {
      if (typeof responseData === 'string') {
        // Caso A: El servidor devolvió texto plano (ej: HTML de Nginx o string crudo)
        apiMessage = responseData.trim();
      } else if (typeof responseData === 'object' && responseData !== null) {
        // Caso B: El servidor devolvió un objeto JSON
        const rawMessage =
          (responseData as any).message ?? (responseData as any).error;

        if (Array.isArray(rawMessage)) {
          // Si NestJS/Class-Validator devuelve un array de errores, tomamos el primero o los unimos
          apiMessage = rawMessage[0] || 'Empty error array';
        } else if (typeof rawMessage === 'string') {
          // Si es un string directo de toda la vida
          apiMessage = rawMessage;
        } else if (typeof rawMessage === 'object' && rawMessage !== null) {
          // Si viene un objeto anidado extraño, lo serializamos de forma segura
          apiMessage = JSON.stringify(rawMessage);
        }
      }
    }

    // 2. Limpieza de strings largos o saltos de línea (por si vino un HTML de Nginx/Cloudflare)
    return apiMessage.replace(/\n/g, ' ').substring(0, 500);
  }

  /**
   * Parsea el stack trace para aislar de forma precisa el nombre de la clase (Servicio)
   * y la ubicación exacta (archivo, línea y columna).
   */
  function parseOriginStack(stack?: string): {
    serviceName: string;
    locationContext: string;
  } {
    const fallback = {
      serviceName: 'HttpServiceBackend',
      locationContext: 'HttpOperation',
    };
    if (!stack) return fallback;

    const lines = stack.split('\n');
    // La línea [2] representa al Pipe/Service que ejecutó el helper
    const callerLine = lines[2] || '';

    // Expresión regular para capturar "at Clase.metodo (ruta/archivo.ts:linea:columna)"
    const match = callerLine.match(/at\s+([\w.]+)\s+\((.*)\)/);

    if (match && match[1]) {
      const fullMethod = match[1];
      const pathParts = match[2].split(/[\\/]/);
      const fileAndLine = pathParts[pathParts.length - 1];

      // Extraemos únicamente el nombre de la clase antes del punto
      const serviceName = fullMethod.split('.')[0] || fallback.serviceName;
      const methodName = fullMethod.split('.')[1] || 'method';

      return {
        serviceName,
        locationContext: `${methodName} -> ${fileAndLine}`,
      };
    }

    return fallback;
  }
}

import { HttpException } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import type { AxiosRequestConfig, Method } from 'axios';
import { firstValueFrom } from 'rxjs';
import { AsyncManager } from '@common/helpers/async-manager';
import { RequestContext } from '@common/context/request-context';
import { TRACE_ID_HEADER } from '@core/middlewares/trace-id.middleware';
import { handleHttpErrors } from '@common/utils/rxjs-error-handler.util';
import { HttpAuthStrategy } from './auth/http-auth-strategy';

export interface BaseHttpClientOptions {
  /** Nombre lógico del upstream (contexto de logs). */
  name: string;
  baseURL: string;
  timeoutMs: number;
  auth: HttpAuthStrategy;
  retry?: { attempts: number; delayMs: number };
  /** Tope de requests simultáneos hacia este upstream (default 10). */
  maxConcurrency?: number;
}

export interface RequestOptions {
  headers?: Record<string, string>;
  params?: Record<string, unknown>;
  /** Fuerza (true) o desactiva (false) el retry; por defecto solo métodos idempotentes. */
  retry?: boolean;
}

const IDEMPOTENT_METHODS: ReadonlySet<string> = new Set([
  'GET',
  'HEAD',
  'OPTIONS',
  'PUT',
  'DELETE',
]);
const RETRYABLE_STATUSES: ReadonlySet<number> = new Set([502, 503, 504]);

/**
 * Patrón: Adapter/BFF sobre @nestjs/axios. Centraliza baseURL, timeout, autenticación
 * (Strategy), propagación de X-Trace-Id, mapeo de errores (`handleHttpErrors`) y retry de
 * errores transitorios con `AsyncManager`. Los retries SOLO se aplican a métodos
 * idempotentes: reintentar un POST podría duplicar el efecto en el upstream.
 */
export abstract class BaseHttpClient {
  private readonly manager: AsyncManager;

  protected constructor(
    protected readonly http: HttpService,
    protected readonly options: BaseHttpClientOptions,
  ) {
    this.manager = new AsyncManager(options.maxConcurrency ?? 10);
  }

  protected get<T>(path: string, opts?: RequestOptions): Promise<T> {
    return this.send<T>('GET', path, undefined, opts);
  }

  protected post<T>(
    path: string,
    body?: unknown,
    opts?: RequestOptions,
  ): Promise<T> {
    return this.send<T>('POST', path, body, opts);
  }

  protected put<T>(
    path: string,
    body?: unknown,
    opts?: RequestOptions,
  ): Promise<T> {
    return this.send<T>('PUT', path, body, opts);
  }

  protected delete<T>(path: string, opts?: RequestOptions): Promise<T> {
    return this.send<T>('DELETE', path, undefined, opts);
  }

  protected async send<T>(
    method: Method,
    path: string,
    body?: unknown,
    opts: RequestOptions = {},
  ): Promise<T> {
    const traceId = RequestContext.getTraceId();
    const base: AxiosRequestConfig = {
      method,
      url: path,
      baseURL: this.options.baseURL,
      timeout: this.options.timeoutMs,
      data: body,
      params: opts.params,
      headers: {
        ...(traceId ? { [TRACE_ID_HEADER]: traceId } : {}),
        ...(opts.headers ?? {}),
      },
    };
    const config = await this.options.auth.apply(base);

    const retryAllowed =
      opts.retry ?? IDEMPOTENT_METHODS.has(method.toUpperCase());
    const retry = retryAllowed ? this.options.retry : undefined;

    const task = async (): Promise<T> => {
      const response = await firstValueFrom(
        this.http
          .request<T>(config)
          .pipe(handleHttpErrors(`${this.options.name} ${method} ${path}`)),
      );
      return response.data;
    };

    return await this.manager.enqueue(
      task,
      retry && retry.attempts > 0
        ? {
            attempts: retry.attempts,
            delayMs: retry.delayMs,
            shouldRetry: (error: unknown) => BaseHttpClient.isRetryable(error),
          }
        : undefined,
    );
  }

  /** Transitorio = el mapeo de `handleHttpErrors` dejó un 502/503/504. */
  static isRetryable(error: unknown): boolean {
    return (
      error instanceof HttpException &&
      RETRYABLE_STATUSES.has(error.getStatus())
    );
  }
}

