import {
  ValidatorConstraint,
  ValidatorConstraintInterface,
  ValidationArguments,
} from 'class-validator';
import { t } from '@common/i18n/i18n.helper';

export interface DateRangeDTO {
  startDate?: Date;
  endDate?: Date;
}

@ValidatorConstraint({ name: 'IsEndDateAfterStartDate', async: false })
export class IsEndDateAfterStartDate implements ValidatorConstraintInterface {
  private message: string = '';
  validate(endDate: unknown, args: ValidationArguments) {
    const obj = args.object as DateRangeDTO;
    if (!obj.startDate) {
      this.message = t('validation.START_DATE_REQUIRED');
      return false;
    }

    if (new Date(endDate as Date) < new Date(obj.startDate)) {
      this.message = t('validation.END_DATE_AFTER_START');
      return false;
    }

    return true;
  }

  defaultMessage(): string {
    return this.message || t('validation.END_DATE_INVALID');
  }
}

@ValidatorConstraint({ name: 'IsDateRangeWithinSixMonths', async: false })
export class IsDateRangeWithinSixMonths
  implements ValidatorConstraintInterface
{
  validate(endDate: unknown, args: ValidationArguments): boolean {
    const obj = args.object as DateRangeDTO;
    if (!obj.startDate || endDate == null) return true;
    const start = new Date(obj.startDate);
    const end = new Date(endDate as Date);
    if (isNaN(start.getTime()) || isNaN(end.getTime())) return true;
    const maxEnd = new Date(start);
    maxEnd.setMonth(maxEnd.getMonth() + 6);
    return end <= maxEnd;
  }

  defaultMessage(): string {
    return t('validation.DATE_RANGE_MAX_SIX_MONTHS');
  }
}

const EMPTY_DATE_FILL = '00000000';

/** `'00000000'`, `0`, vacío o null → null; si no, el valor recortado (YYYYMMDD). */
export function normalizeDb2Date(
  value: string | number | null | undefined,
): string | null {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  if (text === '' || text === EMPTY_DATE_FILL || text === '0') return null;
  return text;
}

/** `'20260131'` → `'2026-01-31'`; null si el valor es "sin fecha" o no tiene 8 dígitos. */
export function db2DateToIso(
  value: string | number | null | undefined,
): string | null {
  const normalized = normalizeDb2Date(value);
  if (normalized === null || !/^\d{8}$/.test(normalized)) return null;
  return `${normalized.slice(0, 4)}-${normalized.slice(4, 6)}-${normalized.slice(6, 8)}`;
}

/** Date → YYYYMMDD numérico (componentes UTC; convertir antes si se necesita otra zona). */
export function dateToDb2Number(date: Date): number {
  return (
    date.getUTCFullYear() * 10000 +
    (date.getUTCMonth() + 1) * 100 +
    date.getUTCDate()
  );
}

/** YYYYMMDD numérico o string → Date (UTC, 00:00); null si es "sin fecha" o inválida. */
export function db2NumberToDate(
  value: string | number | null | undefined,
): Date | null {
  const iso = db2DateToIso(value);
  if (iso === null) return null;
  const date = new Date(`${iso}T00:00:00.000Z`);
  return Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== iso
    ? null
    : date;
}

export interface Db2TimestampRange {
  start: string;
  end: string;
}

/**
 * Rango de un día para columnas TIMESTAMP: `'YYYY-MM-DD 00:00:00.000'` a `'YYYY-MM-DD 23:59:59.999'`.
 * Nunca filtrar un TIMESTAMP con solo `YYYYMMDD`: el BETWEEN sin hora excluye el último segundo del día.
 */
export function toDb2DayRange(day: string | Date): Db2TimestampRange {
  const iso =
    typeof day === 'string' ? day.slice(0, 10) : day.toISOString().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
    throw new RangeError(`Fecha inválida: ${String(day)}`);
  }
  return { start: `${iso} 00:00:00.000`, end: `${iso} 23:59:59.999` };
}

/** Rango [from, to] (ambos inclusive) con la franja horaria completa en cada extremo. */
export function toDb2Range(
  from: string | Date,
  to: string | Date,
): Db2TimestampRange {
  return { start: toDb2DayRange(from).start, end: toDb2DayRange(to).end };
}

interface OdbcErrorLike {
  code?: number | string;
  state?: string;
  message?: string;
}

interface DbErrorLike {
  name?: string;
  message?: string;
  sql?: unknown;
  cause?: OdbcErrorLike;
  parent?: OdbcErrorLike;
  odbcErrors?: OdbcErrorLike[];
}

export interface DescribedDbError {
  name?: string;
  message?: string;
  sqlCode?: number | string;
  sqlState?: string;
  dbMessage?: string;
  sql?: unknown;
}

export function describeDbError(error: unknown): DescribedDbError {
  const err = (
    typeof error === 'object' && error !== null ? error : {}
  ) as DbErrorLike;
  const odbc = err.cause ?? err.parent ?? err.odbcErrors?.[0];

  return {
    name: err.name,
    message: err.message,
    sqlCode: odbc?.code,
    sqlState: odbc?.state,
    dbMessage: odbc?.message,
    sql: err.sql,
  };
}

/**
 * Normaliza el SQLCODE a formato mensaje `SQLnnnn` (`-204`, `'-204'`, `204`, `'SQL0204'` → `'SQL0204'`).
 * Los códigos de 5 dígitos (`SQL7008`) se respetan.
 */
export function normalizeSqlCode(
  code: number | string | undefined,
): string | undefined {
  if (code === undefined || code === null || code === '') return undefined;
  const match = /^(?:SQL)?-?(\d{1,5})$/i.exec(String(code).trim());
  if (!match) return undefined;
  return `SQL${match[1].padStart(4, '0')}`;
}

/** SQLCODE normalizado de un error de base de datos (o `undefined` si no trae uno reconocible). */
export function extractSqlCode(error: unknown): string | undefined {
  return normalizeSqlCode(describeDbError(error).sqlCode);
}

