export interface ExecutionOptions {
  maxConcurrency?: number;
  retryAttempts?: number;
  retryDelayMs?: number;
}

export interface LockoutOptions {
  maxAttempts: number;
  lockoutMinutes: number;
}

export interface FailedAttemptDecision {
  attempts: number;
  lockedUntil: Date | null;
  permanentBlock: boolean;
}

export function evaluateFailedAttempt(
  currentAttempts: number,
  options: LockoutOptions,
  now: Date = new Date(),
): FailedAttemptDecision {
  const attempts = currentAttempts + 1;

  if (attempts < options.maxAttempts) {
    return { attempts, lockedUntil: null, permanentBlock: false };
  }
  if (options.lockoutMinutes <= 0) {
    return { attempts, lockedUntil: null, permanentBlock: true };
  }
  return {
    // Al bloquear se reinician los intentos: tras el desbloqueo hay una ventana nueva.
    attempts: 0,
    lockedUntil: new Date(now.getTime() + options.lockoutMinutes * 60_000),
    permanentBlock: false,
  };
}

export function isLockedOut(
  lockedUntil: Date | null | undefined,
  now: Date = new Date(),
): boolean {
  return !!lockedUntil && lockedUntil.getTime() > now.getTime();
}

export function remainingLockoutMinutes(
  lockedUntil: Date,
  now: Date = new Date(),
): number {
  return Math.max(
    1,
    Math.ceil((lockedUntil.getTime() - now.getTime()) / 60_000),
  );
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Prisma } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { DecimalInput, normalizeDecimal } from '@common/helpers/decimal.helper';

export interface FeeConfig {
  /** Porcentaje sobre el monto (2.5 = 2.5%). */
  percentage: number;
  /** Comisión mínima: nunca se cobra menos que esto. */
  minimum: number;
}

/**
 * Función pura: fee = max(monto * porcentaje / 100, mínimo), redondeado a 2 decimales.
 * Sin I/O ni config global, por eso es trivial de testear.
 */
export function calculateFee(
  amount: DecimalInput,
  config: FeeConfig,
): Prisma.Decimal {
  const percentageFee = normalizeDecimal(amount)
    .mul(new Prisma.Decimal(config.percentage))
    .div(100);
  const minimum = new Prisma.Decimal(config.minimum);
  return normalizeDecimal(Prisma.Decimal.max(percentageFee, minimum));
}

/** Adapter inyectable que alimenta `calculateFee` con la configuración de la app. */
@Injectable()
export class FeeCalculator {
  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  calculate(amount: DecimalInput): Prisma.Decimal {
    return calculateFee(amount, {
      percentage: this.config.orders.feePercentage,
      minimum: this.config.orders.feeMinimum,
    });
  }
}

