export interface CatalogItemFilterParams {
  /** Búsqueda parcial (LIKE). */
  code?: string;
  /** Coincidencia exacta (detalle por PK). */
  exactCode?: string;
  description?: string;
  status?: CatalogItemUiStatus;
  categoryCodes?: string[];
}

