import { NestFactory } from '@nestjs/core';
import { NestExpressApplication } from '@nestjs/platform-express';
import { IoAdapter } from '@nestjs/platform-socket.io';
import { Logger as NestLogger, ValidationPipe } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { Logger } from 'nestjs-pino';
import * as path from 'path';
import * as fs from 'fs';
import cookieParser from 'cookie-parser';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { AppModule } from './app.module';
import { ObservabilityInterceptor } from '@core/observability/observability.interceptor';
import { AllExceptionsFilter } from '@core/global-filters/http-exception.filter';
import { SentryReporterService } from '@core/observability/sentry-reporter.service';
import { TransientConnectionExceptionFilter } from '@common/filters/transient-connection-exception.filter';
import { PrismaClientExceptionFilter } from '@common/filters/prisma-client-exception.filter';
import { SequelizeExceptionFilter } from '@common/filters/sequelize-exception.filter';
import * as express from 'express';
import { RedisIoAdapter } from '@modules/realtime/redis-io.adapter';
import { join } from 'path';

interface PackageJson {
  version: string;
  [key: string]: unknown;
}

const packageJson = JSON.parse(
  fs.readFileSync(path.resolve(process.cwd(), 'package.json'), 'utf8'),
) as PackageJson;

async function bootstrap() {
  const logger = new NestLogger('Bootstrap');
  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    // rawBody: bytes originales del request, necesarios para validar firmas HMAC.
    rawBody: true,
  });
  // Express 5 usa 'simple' por defecto; 'extended' (qs) soporta arrays y objetos anidados en query.
  app.set('query parser', 'extended');
  app.use(cookieParser());
  app.useLogger(app.get(Logger));

  app.useGlobalInterceptors(app.get(ObservabilityInterceptor));
  app.useGlobalFilters(
    // Orden de la cadena: transient (503 + Retry-After) -> prisma (P2xxx -> HTTP)
    // -> sequelize (409/503/500 sin detalle DB2) -> all (fallback)
    new TransientConnectionExceptionFilter(
      new PrismaClientExceptionFilter(
        new SequelizeExceptionFilter(
          new AllExceptionsFilter(app.get(SentryReporterService)),
        ),
      ),
    ),
  );

  app.useGlobalPipes(
    new ValidationPipe({
      transform: true,
      validationError: { target: false },
      whitelist: true,
      forbidNonWhitelisted: true,
    }),
  );
  app.enableCors({ origin: true, credentials: true });

  // Realtime: adapter Redis solo si REDIS_URL (varias instancias); si no, in-memory.
  const wsAdapter = new RedisIoAdapter(app);
  const redisUrl = app.get<ConfigType<AppConfigType>>(APP_CONFIG.KEY).redis.url;
  if (redisUrl && (await wsAdapter.connect(redisUrl))) {
    app.useWebSocketAdapter(wsAdapter);
    logger.log('Socket.io usa el adapter Redis');
  } else {
    app.useWebSocketAdapter(new IoAdapter(app));
  }

  app.enableVersioning();
  app.setGlobalPrefix('/node-starter-backend/api');

  const config: ConfigType<AppConfigType> = app.get(APP_CONFIG.KEY);

  const swaggerConfig = new DocumentBuilder()
    .setTitle(config.project.name)
    .setDescription(config.project.description)
    .setVersion(packageJson.version)
    .addBearerAuth()
    .addBasicAuth()
    .build();

  const document = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup(`/node-starter-backend/api/swagger`, app, document, {
    swaggerOptions: {
      persistAuthorization: true,
    },
  });

  // 1. Definir la ruta donde se espera la carpeta 'docs'
  // En producción (dist/main.js), esta ruta apunta a 'dist/docs'
  const docsPath = join(__dirname, '..', 'docs');

  // 2. Verificar si la carpeta de documentación existe
  if (fs.existsSync(docsPath)) {
    // Si existe, configuramos el middleware para servirla
    app.use('/node-starter-backend/api/docs', express.static(docsPath));
    logger.log(
      'Documentación de Compodoc servida en /node-starter-backend/api/docs',
    );
  } else {
    // Si no existe, solo mostramos un aviso y continuamos
    logger.warn(
      `Directorio de docs no encontrado en ${docsPath}. La documentación de Compodoc no se servirá.`,
    );
  }

  await app.listen(config.apiconfig.port);
}

void bootstrap();

import { Controller, Get, Inject, Optional, Version } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { ApiTags } from '@nestjs/swagger';
import {
  HealthCheck,
  HealthCheckService,
  MemoryHealthIndicator,
  PrismaHealthIndicator,
} from '@nestjs/terminus';
import { toZonedTime } from 'date-fns-tz';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { Db2HealthIndicator } from '@core/database/health/db2.health-indicator';
import { RedisHealthIndicator } from '@core/redis/redis.health-indicator';
import { SmtpHealthIndicator } from '@modules/email/health/smtp.health-indicator';
import * as path from 'path';
import * as fs from 'fs';

interface PackageJson {
  version: string;
  [key: string]: unknown;
}

const packageJson = JSON.parse(
  fs.readFileSync(path.resolve(process.cwd(), 'package.json'), 'utf8'),
) as PackageJson;

@ApiTags('Healthcheck')
@Controller('healthcheck')
export class HealthController {
  constructor(
    private health: HealthCheckService,
    private memory: MemoryHealthIndicator,
    private prismaDataSource: PrismaDatasource,
    private db: PrismaHealthIndicator,
    private smtp: SmtpHealthIndicator,
    private redis: RedisHealthIndicator,
    @Inject(APP_CONFIG.KEY)
    private config: ConfigType<AppConfigType>,
    // Solo existe si DB2/Sequelize está activo (DATABASE_CONNECTION_STRING)
    @Optional() private db2?: Db2HealthIndicator,
  ) {}

  @Get()
  @HealthCheck()
  @Version('1')
  async check() {
    const healthCheck = await this.health.check([
      () => this.db.pingCheck('database', this.prismaDataSource),
      ...(this.db2 ? [() => this.db2!.check('db2')] : []),
      () => this.memory.checkHeap('memory_heap', 150 * 1024 * 1024), // verifica que el proceso no utiliza mas de 150mb de memoria
    ]);

    return {
      date: toZonedTime(new Date(), this.config.timezone),
      info: healthCheck,
      // Informativo: no participa del chequeo agregado (un SMTP caído no baja el estado general)
      smtp: this.smtp.check(),
      redis: await this.redis.check(),
      version: packageJson.version,
    };
  }
}

