import { AsyncLocalStorage } from 'async_hooks';

/**
 * Patrón: contexto ambiental por request (AsyncLocalStorage). Permite leer traceId desde
 * cualquier capa (logs, clientes HTTP salientes, repositorios) sin pasarlo por parámetros.
 * Convive con `auditStorage` (core/database): ese se arma tras la autenticación y tiene
 * forma propia consumida por la extensión de Prisma; unificarlos acoplaría el contexto
 * (que nace en el middleware) con datos que aún no existen en ese punto.
 */
export interface RequestContextStore {
  traceId: string;
  [key: string]: unknown;
}

const storage = new AsyncLocalStorage<RequestContextStore>();

export class RequestContext {
  static run<T>(store: RequestContextStore, fn: () => T): T {
    return storage.run(store, fn);
  }

  static get(): RequestContextStore | undefined {
    return storage.getStore();
  }

  static getTraceId(): string | undefined {
    return storage.getStore()?.traceId;
  }

  /** Agrega/pisa un valor en el contexto activo (no-op si no hay contexto). */
  static set(key: string, value: unknown): void {
    const store = storage.getStore();
    if (store) store[key] = value;
  }
}

import { HttpException } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import type { AxiosRequestConfig, Method } from 'axios';
import { firstValueFrom } from 'rxjs';
import { AsyncManager } from '@common/helpers/async-manager';
import { RequestContext } from '@common/context/request-context';
import { TRACE_ID_HEADER } from '@core/middlewares/trace-id.middleware';
import { handleHttpErrors } from '@common/utils/rxjs-error-handler.util';
import { HttpAuthStrategy } from './auth/http-auth-strategy';

export interface BaseHttpClientOptions {
  /** Nombre lógico del upstream (contexto de logs). */
  name: string;
  baseURL: string;
  timeoutMs: number;
  auth: HttpAuthStrategy;
  retry?: { attempts: number; delayMs: number };
  /** Tope de requests simultáneos hacia este upstream (default 10). */
  maxConcurrency?: number;
}

export interface RequestOptions {
  headers?: Record<string, string>;
  params?: Record<string, unknown>;
  /** Fuerza (true) o desactiva (false) el retry; por defecto solo métodos idempotentes. */
  retry?: boolean;
}

const IDEMPOTENT_METHODS: ReadonlySet<string> = new Set([
  'GET',
  'HEAD',
  'OPTIONS',
  'PUT',
  'DELETE',
]);
const RETRYABLE_STATUSES: ReadonlySet<number> = new Set([502, 503, 504]);

/**
 * Patrón: Adapter/BFF sobre @nestjs/axios. Centraliza baseURL, timeout, autenticación
 * (Strategy), propagación de X-Trace-Id, mapeo de errores (`handleHttpErrors`) y retry de
 * errores transitorios con `AsyncManager`. Los retries SOLO se aplican a métodos
 * idempotentes: reintentar un POST podría duplicar el efecto en el upstream.
 */
export abstract class BaseHttpClient {
  private readonly manager: AsyncManager;

  protected constructor(
    protected readonly http: HttpService,
    protected readonly options: BaseHttpClientOptions,
  ) {
    this.manager = new AsyncManager(options.maxConcurrency ?? 10);
  }

  protected get<T>(path: string, opts?: RequestOptions): Promise<T> {
    return this.send<T>('GET', path, undefined, opts);
  }

  protected post<T>(
    path: string,
    body?: unknown,
    opts?: RequestOptions,
  ): Promise<T> {
    return this.send<T>('POST', path, body, opts);
  }

  protected put<T>(
    path: string,
    body?: unknown,
    opts?: RequestOptions,
  ): Promise<T> {
    return this.send<T>('PUT', path, body, opts);
  }

  protected delete<T>(path: string, opts?: RequestOptions): Promise<T> {
    return this.send<T>('DELETE', path, undefined, opts);
  }

  protected async send<T>(
    method: Method,
    path: string,
    body?: unknown,
    opts: RequestOptions = {},
  ): Promise<T> {
    const traceId = RequestContext.getTraceId();
    const base: AxiosRequestConfig = {
      method,
      url: path,
      baseURL: this.options.baseURL,
      timeout: this.options.timeoutMs,
      data: body,
      params: opts.params,
      headers: {
        ...(traceId ? { [TRACE_ID_HEADER]: traceId } : {}),
        ...(opts.headers ?? {}),
      },
    };
    const config = await this.options.auth.apply(base);

    const retryAllowed =
      opts.retry ?? IDEMPOTENT_METHODS.has(method.toUpperCase());
    const retry = retryAllowed ? this.options.retry : undefined;

    const task = async (): Promise<T> => {
      const response = await firstValueFrom(
        this.http
          .request<T>(config)
          .pipe(handleHttpErrors(`${this.options.name} ${method} ${path}`)),
      );
      return response.data;
    };

    return await this.manager.enqueue(
      task,
      retry && retry.attempts > 0
        ? {
            attempts: retry.attempts,
            delayMs: retry.delayMs,
            shouldRetry: (error: unknown) => BaseHttpClient.isRetryable(error),
          }
        : undefined,
    );
  }

  /** Transitorio = el mapeo de `handleHttpErrors` dejó un 502/503/504. */
  static isRetryable(error: unknown): boolean {
    return (
      error instanceof HttpException &&
      RETRYABLE_STATUSES.has(error.getStatus())
    );
  }
}

import { ConflictException, Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { IdempotencyStatus, Prisma } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PrismaErrorCodes } from '@common/enum/prisma-error-codes.enum';
import { safeEqual } from '@common/helpers/crypto/hmac.helper';

export type IdempotencyResolution =
  | { action: 'NEW'; recordId: number }
  | { action: 'REPLAY'; responseCode: number; responseBody: unknown }
  | { action: 'CONFLICT' } // misma key, otro payload -> 409
  | { action: 'IN_PROGRESS' }; // misma key en curso -> 409

export interface ResolveInput {
  key: string;
  scope: string;
  requestHash: string;
}

// Un IN_PROGRESS más viejo que esto se considera huérfano (el proceso murió) y se retoma.
const STALE_IN_PROGRESS_MS = 5 * 60_000;

/**
 * Patrón: Idempotency Key respaldada en DB. La unicidad (scope, key) es el árbitro de la
 * carrera entre requests concurrentes (INSERT atómico), no un "check then insert".
 * Usa el cliente Prisma sin extensión de auditoría: son datos técnicos, no de negocio.
 */
@Injectable()
export class IdempotencyService {
  constructor(
    private readonly prisma: PrismaDatasource,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async resolve(input: ResolveInput): Promise<IdempotencyResolution> {
    for (let attempt = 0; attempt < 3; attempt++) {
      const now = new Date();
      try {
        const created = await this.prisma.idempotencyRecord.create({
          data: {
            key: input.key,
            scope: input.scope,
            requestHash: input.requestHash,
            expiresAt: new Date(
              now.getTime() + this.config.idempotency.ttlHours * 3_600_000,
            ),
          },
        });
        return { action: 'NEW', recordId: created.id };
      } catch (error) {
        if (!this.isUniqueViolation(error)) throw error;
      }

      const existing = await this.prisma.idempotencyRecord.findUnique({
        where: { scope_key: { scope: input.scope, key: input.key } },
      });
      if (!existing) continue; // se purgó entre medio: reintentar el INSERT

      if (existing.expiresAt <= now) {
        await this.prisma.idempotencyRecord.deleteMany({
          where: { id: existing.id, expiresAt: { lte: now } },
        });
        continue;
      }

      if (!safeEqual(existing.requestHash, input.requestHash)) {
        return { action: 'CONFLICT' };
      }

      if (existing.status === IdempotencyStatus.COMPLETED) {
        return {
          action: 'REPLAY',
          responseCode: existing.responseCode ?? 200,
          responseBody: existing.responseBody,
        };
      }

      // IN_PROGRESS: ¿vigente o huérfano? El updateMany condicional garantiza un único ganador.
      const takeover = await this.prisma.idempotencyRecord.updateMany({
        where: {
          id: existing.id,
          status: IdempotencyStatus.IN_PROGRESS,
          updatedAt: { lt: new Date(now.getTime() - STALE_IN_PROGRESS_MS) },
        },
        data: { updatedAt: now },
      });
      return takeover.count === 1
        ? { action: 'NEW', recordId: existing.id }
        : { action: 'IN_PROGRESS' };
    }

    throw new ConflictException(
      'No se pudo resolver la Idempotency-Key, reintente.',
    );
  }

  async complete(
    recordId: number,
    responseCode: number,
    responseBody: unknown,
  ): Promise<void> {
    // Round-trip JSON: guarda exactamente lo que el cliente recibió (Decimal/Date serializados).
    const body =
      responseBody === undefined
        ? Prisma.DbNull
        : (JSON.parse(JSON.stringify(responseBody)) as Prisma.InputJsonValue);

    await this.prisma.idempotencyRecord.update({
      where: { id: recordId },
      data: {
        status: IdempotencyStatus.COMPLETED,
        responseCode,
        responseBody: body,
      },
    });
  }

  /** Libera la clave tras un error para permitir reintento (los errores no se cachean). */
  async release(recordId: number): Promise<void> {
    await this.prisma.idempotencyRecord.deleteMany({
      where: { id: recordId, status: IdempotencyStatus.IN_PROGRESS },
    });
  }

  /** Limpieza de registros vencidos (invocar desde un job/cron externo). */
  async purgeExpired(now: Date = new Date()): Promise<number> {
    const { count } = await this.prisma.idempotencyRecord.deleteMany({
      where: { expiresAt: { lte: now } },
    });
    return count;
  }

  private isUniqueViolation(error: unknown): boolean {
    return (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === (PrismaErrorCodes.UniqueConstraintFailed as string)
    );
  }
}

