import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { AdvisoryLockId } from '@core/scheduler/advisory-lock-id.enum';
import { ScheduledJob, SchedulerCronKey } from '@core/scheduler/scheduled-job';
import {
  AccountAnonymizedEvent,
  DOMAIN_EVENTS,
} from '@common/events/domain-events';
import { AccountDeletionDBService } from '../services/account-deletion-db.service';
import { DataRetentionExecutorService } from '../services/data-retention-executor.service';

/** Tope de lotes por tick: un backlog grande se drena en varios ticks sin monopolizar el job. */
const MAX_BATCHES_PER_RUN = 20;

/**
 * Barrido diario: (1) anonimiza usuarios con la gracia de baja vencida, por lotes; (2) aplica las
 * políticas de retención sobre los datos de usuarios ya anonimizados. Una réplica por tick
 * (advisory lock). Un usuario que falla se loguea y no frena al resto.
 */
@Injectable()
export class AccountAnonymizationJob extends ScheduledJob {
  readonly name = 'account-anonymization';
  readonly cronConfigKey: SchedulerCronKey = 'accountAnonymization';
  readonly lockId = AdvisoryLockId.AccountAnonymization;

  constructor(
    private readonly deletion: AccountDeletionDBService,
    private readonly retention: DataRetentionExecutorService,
    private readonly events: EventEmitter2,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {
    super();
  }

  async run(): Promise<void> {
    const batchSize = this.config.compliance.anonymizationBatchSize;
    let anonymized = 0;

    for (let i = 0; i < MAX_BATCHES_PER_RUN; i++) {
      const due = await this.deletion.findDue(batchSize);
      let processed = 0;
      for (const user of due) {
        try {
          if (await this.deletion.anonymize(user)) {
            anonymized++;
            const event: AccountAnonymizedEvent = { userId: user.id };
            this.events.emit(DOMAIN_EVENTS.ACCOUNT_ANONYMIZED, event);
            processed++;
          }
        } catch (error) {
          const message =
            error instanceof Error ? error.message : String(error);
          this.logger.error(
            `No se pudo anonimizar user=${user.id} | ${message}`,
          );
        }
      }
      // Sin progreso (todo falló o se canceló): cortar para no repetir el mismo lote.
      if (due.length < batchSize || processed === 0) break;
    }

    const retained = await this.retention.run();
    this.logger.log(
      `Anonimización: usuarios=${anonymized}, retención=${JSON.stringify(retained)}`,
    );
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  AccountDeletionCancelledEvent,
  AccountDeletionRequestedEvent,
  DOMAIN_EVENTS,
} from '@common/events/domain-events';
import { t } from '@common/i18n/i18n.helper';
import { AccountDeletionDBService } from '@modules/account-db/services/account-deletion-db.service';
import { NotificationsService } from '@modules/notifications/services/notifications.service';
import { DeletionStatusResponseDTO } from '../dtos/account.dto';

/** Capa API: solicitar/cancelar/consultar la baja de la cuenta propia y avisar al usuario. */
@Injectable()
export class AccountApiService {
  private readonly logger = new Logger(AccountApiService.name);

  constructor(
    private readonly deletion: AccountDeletionDBService,
    private readonly notifications: NotificationsService,
    private readonly events: EventEmitter2,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async requestDeletion(userId: number): Promise<DeletionStatusResponseDTO> {
    const { requestedAt, scheduledAt } = await this.deletion.request(
      userId,
      this.config.compliance.accountDeletionGraceDays,
    );
    const requested: AccountDeletionRequestedEvent = { userId, scheduledAt };
    this.events.emit(DOMAIN_EVENTS.ACCOUNT_DELETION_REQUESTED, requested);
    await this.notify(userId, 'REQUESTED', { scheduledAt });
    return { requestedAt, scheduledAt, anonymizedAt: null };
  }

  async cancelDeletion(userId: number): Promise<void> {
    await this.deletion.cancel(userId);
    const cancelled: AccountDeletionCancelledEvent = { userId };
    this.events.emit(DOMAIN_EVENTS.ACCOUNT_DELETION_CANCELLED, cancelled);
    await this.notify(userId, 'CANCELLED');
  }

  async status(userId: number): Promise<DeletionStatusResponseDTO> {
    return await this.deletion.status(userId);
  }

  /** Aviso best-effort: un fallo de notificación nunca revierte la baja ya registrada. */
  private async notify(
    userId: number,
    kind: 'REQUESTED' | 'CANCELLED',
    args?: { scheduledAt: Date },
  ): Promise<void> {
    try {
      const params = args && { scheduledAt: args.scheduledAt.toISOString() };
      await this.notifications.notify(userId, {
        title: t(`account.NOTIFICATION_${kind}_TITLE`, params),
        body: t(`account.NOTIFICATION_${kind}_BODY`, params),
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.warn(`Notificación de baja no enviada | ${message}`);
    }
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { Users, UserStatus } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { t } from '@common/i18n/i18n.helper';

const DAY_MS = 86_400_000;
export const ANONYMIZATION_ACTOR = 'account-anonymization';
export const ANONYMIZED_NAME = 'Anonymized';

export interface IDeletionStatus {
  requestedAt: Date | null;
  scheduledAt: Date | null;
  anonymizedAt: Date | null;
}

/**
 * Derecho al olvido en dos fases. (1) Baja SOFT: solo se marcan fechas en `users`; la cuenta
 * sigue operando y se puede cancelar durante el período de gracia. (2) Vencida la gracia, el job
 * anonimiza: la fila de `users` se CONSERVA (integridad referencial de órdenes, auditoría, etc.)
 * pero sin PII, y se revocan credenciales/accesos. Las transiciones son updates condicionales
 * (`updateMany` + conteo): atómicas, sin carrera entre solicitar/cancelar/anonimizar.
 */
@Injectable()
export class AccountDeletionDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  async request(userId: number, graceDays: number, now = new Date()) {
    const scheduledAt = new Date(now.getTime() + graceDays * DAY_MS);
    const { count } = await this.prisma.extended.users.updateMany({
      where: { id: userId, deletionRequestedAt: null, anonymizedAt: null },
      data: {
        deletionRequestedAt: now,
        deletionScheduledAt: scheduledAt,
        lastChangedBy: String(userId),
      },
    });
    if (count === 0) {
      throw new ConflictException(t('account.DELETION_ALREADY_REQUESTED'));
    }
    return { requestedAt: now, scheduledAt };
  }

  async cancel(userId: number): Promise<void> {
    const { count } = await this.prisma.extended.users.updateMany({
      where: {
        id: userId,
        deletionRequestedAt: { not: null },
        anonymizedAt: null,
      },
      data: {
        deletionRequestedAt: null,
        deletionScheduledAt: null,
        lastChangedBy: String(userId),
      },
    });
    if (count === 0) {
      throw new NotFoundException(t('account.DELETION_NOT_REQUESTED'));
    }
  }

  async status(userId: number): Promise<IDeletionStatus> {
    const user = await this.prisma.users.findUnique({
      where: { id: userId },
      select: {
        deletionRequestedAt: true,
        deletionScheduledAt: true,
        anonymizedAt: true,
      },
    });
    return {
      requestedAt: user?.deletionRequestedAt ?? null,
      scheduledAt: user?.deletionScheduledAt ?? null,
      anonymizedAt: user?.anonymizedAt ?? null,
    };
  }

  findDue(
    limit: number,
    now = new Date(),
  ): Promise<Pick<Users, 'id' | 'referenceId'>[]> {
    return this.prisma.users.findMany({
      where: {
        anonymizedAt: null,
        deletionScheduledAt: { not: null, lte: now },
      },
      select: { id: true, referenceId: true },
      orderBy: { deletionScheduledAt: 'asc' },
      take: limit,
    });
  }

  /**
   * Anonimiza un usuario vencido: PII -> placeholder determinista, acceso revocado.
   * @returns `false` si ya no correspondía (se canceló o ya estaba anonimizado)
   */
  async anonymize(
    user: Pick<Users, 'id' | 'referenceId'>,
    now = new Date(),
  ): Promise<boolean> {
    return await this.prisma.extended.$transaction(async (tx) => {
      const { count } = await tx.users.updateMany({
        where: {
          id: user.id,
          anonymizedAt: null,
          deletionScheduledAt: { not: null, lte: now },
        },
        data: {
          email: `anonymized+${user.referenceId}@anonymized.invalid`,
          firstName: ANONYMIZED_NAME,
          lastName: ANONYMIZED_NAME,
          documentType: null,
          documentNumber: null,
          phoneNumber: null,
          legacyUserId: null,
          unverifiedEmail: null,
          status: UserStatus.DELETED,
          anonymizedAt: now,
          lastChangedBy: ANONYMIZATION_ACTOR,
          changedReason: 'account deletion',
        },
      });
      if (count === 0) return false;

      await tx.userCredentials.deleteMany({ where: { userId: user.id } });
      await tx.pushSubscription.deleteMany({ where: { userId: user.id } });
      await tx.userRoles.deleteMany({ where: { userId: user.id } });
      await tx.userPermissions.deleteMany({ where: { userId: user.id } });
      return true;
    });
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { RequestContext } from '@common/context/request-context';
import { redactDeep } from '@core/observability/redaction';
import {
  ACTIVITY_LOG_STORE,
  IActivityLogEntry,
  IActivityLogQuery,
  IActivityLogRecord,
  IActivityLogStore,
} from '../interfaces/activity-log-store.interface';

/**
 * Fachada del registro de actividad. `record` es best-effort: completa el traceId desde el
 * contexto de la request, redacta la metadata (misma política que los logs) y NUNCA lanza, así un
 * Mongo caído no rompe la operación de negocio que solo quería dejar rastro.
 */
@Injectable()
export class ActivityLogService {
  private readonly logger = new Logger(ActivityLogService.name);

  constructor(
    @Inject(ACTIVITY_LOG_STORE) private readonly store: IActivityLogStore,
  ) {}

  get storage(): IActivityLogStore['kind'] {
    return this.store.kind;
  }

  async record(entry: IActivityLogEntry): Promise<void> {
    try {
      await this.store.append({
        ...entry,
        traceId: entry.traceId ?? RequestContext.getTraceId(),
        metadata: entry.metadata
          ? (redactDeep(entry.metadata) as Record<string, unknown>)
          : undefined,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.warn(`No se pudo registrar ${entry.action} | ${message}`);
    }
  }

  find(query: IActivityLogQuery): Promise<IActivityLogRecord[]> {
    return this.store.find(query);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { AiContentDisclosure } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { t } from '@common/i18n/i18n.helper';

export interface IMarkAiContent {
  entityType: string;
  entityId: string;
  model: string;
  notes?: string;
}

/**
 * Transparencia de contenido generado por IA, genérica: cualquier entidad se identifica por
 * (entityType, entityId). Marcar es idempotente (upsert por esa clave: re-generar con otro modelo
 * actualiza el registro y reinicia la revisión humana).
 */
@Injectable()
export class AiDisclosureDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  mark(input: IMarkAiContent): Promise<AiContentDisclosure> {
    const data = { model: input.model, notes: input.notes };
    return this.prisma.aiContentDisclosure.upsert({
      where: {
        entityType_entityId: {
          entityType: input.entityType,
          entityId: input.entityId,
        },
      },
      create: {
        entityType: input.entityType,
        entityId: input.entityId,
        ...data,
      },
      update: {
        ...data,
        generatedAt: new Date(),
        reviewedBy: null,
        reviewedAt: null,
      },
    });
  }

  async find(
    entityType: string,
    entityId: string,
  ): Promise<AiContentDisclosure> {
    const found = await this.prisma.aiContentDisclosure.findUnique({
      where: { entityType_entityId: { entityType, entityId } },
    });
    if (!found) throw new NotFoundException(t('common.NOT_FOUND'));
    return found;
  }

  async markReviewed(
    entityType: string,
    entityId: string,
    reviewerId: number,
  ): Promise<AiContentDisclosure> {
    await this.find(entityType, entityId);
    return await this.prisma.aiContentDisclosure.update({
      where: { entityType_entityId: { entityType, entityId } },
      data: { reviewedBy: reviewerId, reviewedAt: new Date() },
    });
  }
}

import { Injectable } from '@nestjs/common';
import { ApiClientsDBService } from '@modules/api-clients-db/services/api-clients-db.service';
import type { IApiClientSecrets } from '@modules/api-clients-db/interfaces/api-client.interface';
import type { IApiClientDetail } from '@modules/api-clients-db/interfaces/api-client.interface';
import {
  CreateApiClientRequestDTO,
  ListApiClientsRequestDTO,
  UpdateApiClientSettingsRequestDTO,
  UpdateApiClientStatusRequestDTO,
} from '../dtos/api-clients.request.dto';
import {
  ApiClientResponseDTO,
  ApiClientsListResponseDTO,
  ApiClientWithSecretsResponseDTO,
} from '../dtos/api-clients.response.dto';

/**
 * Capa API: orquesta DTO <-> dominio y agrega el operador (auditoría). Las reglas (hash, rotación,
 * HMAC) viven en `modules/api-clients-db`.
 */
@Injectable()
export class ApiClientsApiService {
  constructor(private readonly apiClientsDB: ApiClientsDBService) {}

  async create(
    dto: CreateApiClientRequestDTO,
    operator: string,
  ): Promise<ApiClientWithSecretsResponseDTO> {
    return this.withSecrets(
      await this.apiClientsDB.create({ ...dto, createdBy: operator }),
    );
  }

  async list(
    query: ListApiClientsRequestDTO,
  ): Promise<ApiClientsListResponseDTO> {
    const { items, total } = await this.apiClientsDB.findAllPaged(query);
    return {
      data: items.map((item) => this.toResponse(item)),
      pagination: {
        total,
        page: query.page,
        pageSize: query.pageSize,
        totalPages: Math.ceil(total / query.pageSize),
      },
    };
  }

  async findOne(referenceId: string): Promise<ApiClientResponseDTO> {
    return this.toResponse(await this.apiClientsDB.findOne(referenceId));
  }

  async toggleStatus(
    referenceId: string,
    dto: UpdateApiClientStatusRequestDTO,
    operator: string,
  ): Promise<ApiClientResponseDTO> {
    return this.toResponse(
      await this.apiClientsDB.toggleStatus(
        referenceId,
        dto.status,
        dto.changedReason,
        operator,
      ),
    );
  }

  async regenerateSecret(
    referenceId: string,
    operator: string,
  ): Promise<ApiClientWithSecretsResponseDTO> {
    return this.withSecrets(
      await this.apiClientsDB.regenerateSecret(referenceId, operator),
    );
  }

  async updateSettings(
    referenceId: string,
    dto: UpdateApiClientSettingsRequestDTO,
    operator: string,
  ): Promise<ApiClientWithSecretsResponseDTO> {
    return this.withSecrets(
      await this.apiClientsDB.updateSettings(referenceId, {
        ...dto,
        operator,
      }),
    );
  }

  private toResponse(detail: IApiClientDetail): ApiClientResponseDTO {
    return { ...detail };
  }

  private withSecrets(
    result: { client: IApiClientDetail } & IApiClientSecrets,
  ): ApiClientWithSecretsResponseDTO {
    return {
      client: this.toResponse(result.client),
      clientSecret: result.clientSecret,
      signingSecret: result.signingSecret,
    };
  }
}

import {
  BadRequestException,
  ConflictException,
  Inject,
  Injectable,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { ApiClientCredential, ApiClientStatus, Prisma } from '@prisma/client';
import * as bcrypt from 'bcrypt';
import { randomBytes } from 'crypto';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { ApiClientsDBHelper } from '../helpers/api-clients-db.helper';
import { ApiClientSigningSecretService } from './api-client-signing-secret.service';
import type {
  ApiClientVerification,
  IApiClientDetail,
  IApiClientSecrets,
  ICreateApiClientData,
  IListApiClientsQuery,
  IUpdateApiClientSettingsData,
} from '../interfaces/api-client.interface';

const CLIENT_ID_BYTES = 9;
const SECRET_BYTES = 32;
/** `lastUsedAt` se refresca como máximo una vez por ventana para no escribir en cada request. */
const LAST_USED_REFRESH_MS = 60_000;

/**
 * Capa de dominio de credenciales M2M. Reglas: el secret solo existe en claro al crearlo/rotarlo
 * (en DB queda su hash bcrypt); rotar sobrescribe el hash, así que el secret anterior deja de
 * valer de inmediato; el HMAC por cliente exige keyring de cifrado para guardar su signing secret.
 */
@Injectable()
export class ApiClientsDBService {
  private readonly logger = new Logger(ApiClientsDBService.name);
  /** Hash descartable para igualar el costo de bcrypt cuando el clientId no existe (anti-timing). */
  private dummyHash?: Promise<string>;

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly signingSecrets: ApiClientSigningSecretService,
    @Inject(APP_CONFIG.KEY) private readonly config: ConfigType<AppConfigType>,
  ) {}

  // ─── Admin ───────────────────────────────────────────────────────────────

  async create(
    data: ICreateApiClientData,
  ): Promise<{ client: IApiClientDetail } & IApiClientSecrets> {
    if (data.hmacEnabled) this.assertHmacAvailable();

    const clientId = `cli_${randomBytes(CLIENT_ID_BYTES).toString('hex')}`;
    const clientSecret = this.generateSecret();
    const signingSecret = data.hmacEnabled ? this.generateSecret() : undefined;

    const row = await this.prisma.extended.apiClientCredential.create({
      data: {
        clientId,
        clientName: data.clientName,
        secretHash: await this.hash(clientSecret),
        scopes: data.scopes,
        rateLimitPerMinute: data.rateLimitPerMinute,
        allowedIps: data.allowedIps ?? [],
        hmacEnabled: !!data.hmacEnabled,
        signingSecretEnc: signingSecret
          ? this.signingSecrets.encrypt(signingSecret)
          : null,
        createdBy: data.createdBy,
        secretRotatedAt: new Date(),
      },
    });

    this.logger.log(`Credencial API creada: ${clientId}`);
    return {
      client: ApiClientsDBHelper.toDetail(row),
      clientSecret,
      signingSecret,
    };
  }

  async findAllPaged(
    query: IListApiClientsQuery,
  ): Promise<{ items: IApiClientDetail[]; total: number }> {
    const where: Prisma.ApiClientCredentialWhereInput = {
      ...(query.status ? { status: query.status } : {}),
      ...(query.search
        ? {
            OR: [
              { clientId: { contains: query.search, mode: 'insensitive' } },
              { clientName: { contains: query.search, mode: 'insensitive' } },
            ],
          }
        : {}),
    };
    const [rows, total] = await this.prisma.extended.$transaction([
      this.prisma.extended.apiClientCredential.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (query.page - 1) * query.pageSize,
        take: query.pageSize,
      }),
      this.prisma.extended.apiClientCredential.count({ where }),
    ]);
    return {
      items: rows.map((row) => ApiClientsDBHelper.toDetail(row)),
      total,
    };
  }

  async findOne(referenceId: string): Promise<IApiClientDetail> {
    return ApiClientsDBHelper.toDetail(await this.getRow(referenceId));
  }

  async toggleStatus(
    referenceId: string,
    status: ApiClientStatus,
    changedReason: string,
    operator?: string,
  ): Promise<IApiClientDetail> {
    if (!changedReason?.trim()) {
      throw new BadRequestException('changedReason es obligatorio.');
    }
    await this.getRow(referenceId);
    const row = await this.prisma.extended.apiClientCredential.update({
      where: { referenceId },
      data: {
        status,
        changedReason,
        lastChangedBy: operator,
        lastChangedAt: new Date(),
      },
    });
    return ApiClientsDBHelper.toDetail(row);
  }

  /** Rota client secret (y signing secret si HMAC está activo). Solo para credenciales ACTIVE. */
  async regenerateSecret(
    referenceId: string,
    operator?: string,
  ): Promise<{ client: IApiClientDetail } & IApiClientSecrets> {
    const current = await this.getRow(referenceId);
    if (current.status !== ApiClientStatus.ACTIVE) {
      throw new ConflictException(
        'La credencial está inactiva. Reactivala antes de regenerar el secret.',
      );
    }
    if (current.hmacEnabled) this.assertHmacAvailable();

    const clientSecret = this.generateSecret();
    const signingSecret = current.hmacEnabled
      ? this.generateSecret()
      : undefined;

    const now = new Date();
    const row = await this.prisma.extended.apiClientCredential.update({
      where: { referenceId },
      data: {
        secretHash: await this.hash(clientSecret),
        ...(signingSecret
          ? { signingSecretEnc: this.signingSecrets.encrypt(signingSecret) }
          : {}),
        secretRotatedAt: now,
        lastChangedBy: operator,
        lastChangedAt: now,
        changedReason: 'Rotación de secret',
      },
    });
    return {
      client: ApiClientsDBHelper.toDetail(row),
      clientSecret,
      signingSecret,
    };
  }

  /** Actualiza settings. Si activa HMAC devuelve el signing secret generado (única vez). */
  async updateSettings(
    referenceId: string,
    data: IUpdateApiClientSettingsData,
  ): Promise<{ client: IApiClientDetail } & IApiClientSecrets> {
    const current = await this.getRow(referenceId);

    let signingSecret: string | undefined;
    let signingSecretEnc: string | null | undefined;
    if (data.hmacEnabled === true && !current.hmacEnabled) {
      this.assertHmacAvailable();
      signingSecret = this.generateSecret();
      signingSecretEnc = this.signingSecrets.encrypt(signingSecret);
    } else if (data.hmacEnabled === false && current.hmacEnabled) {
      signingSecretEnc = null;
    }

    const row = await this.prisma.extended.apiClientCredential.update({
      where: { referenceId },
      data: {
        clientName: data.clientName,
        scopes: data.scopes,
        rateLimitPerMinute: data.rateLimitPerMinute,
        allowedIps: data.allowedIps,
        hmacEnabled: data.hmacEnabled,
        signingSecretEnc,
        changedReason: data.changedReason ?? 'Actualización de settings',
        lastChangedBy: data.operator,
        lastChangedAt: new Date(),
      },
    });
    return { client: ApiClientsDBHelper.toDetail(row), signingSecret };
  }

  // ─── Runtime (guards) ────────────────────────────────────────────────────

  /**
   * Verifica clientId + secret. Siempre ejecuta un `bcrypt.compare` (contra un hash descartable
   * si el cliente no existe) para no revelar por timing qué clientIds existen. El estado se
   * evalúa DESPUÉS de validar el secret: un tercero sin secreto no puede saber si está inactivo.
   */
  async verifyCredentials(
    clientId: string,
    secret: string,
  ): Promise<ApiClientVerification> {
    const row = await this.prisma.extended.apiClientCredential.findUnique({
      where: { clientId },
    });
    const valid = await bcrypt.compare(
      secret,
      row?.secretHash ?? (await this.getDummyHash()),
    );
    if (!row || !valid) return { result: 'invalid' };
    if (row.status !== ApiClientStatus.ACTIVE) {
      return { result: 'inactive', clientId };
    }
    this.touchLastUsed(row);
    return { result: 'ok', principal: ApiClientsDBHelper.toPrincipal(row) };
  }

  /** Signing secret en claro de un cliente con HMAC habilitado; `null` si no aplica. */
  async getSigningSecret(clientId: string): Promise<string | null> {
    const row = await this.prisma.extended.apiClientCredential.findUnique({
      where: { clientId },
      select: { hmacEnabled: true, signingSecretEnc: true },
    });
    if (!row?.hmacEnabled || !row.signingSecretEnc) return null;
    return this.signingSecrets.decrypt(row.signingSecretEnc);
  }

  // ─── Internos ────────────────────────────────────────────────────────────

  private touchLastUsed(row: ApiClientCredential): void {
    const now = Date.now();
    if (
      row.lastUsedAt &&
      now - row.lastUsedAt.getTime() < LAST_USED_REFRESH_MS
    ) {
      return;
    }
    // Fire-and-forget: telemetría de uso, no debe demorar ni romper la autenticación.
    void this.prisma.extended.apiClientCredential
      .update({ where: { id: row.id }, data: { lastUsedAt: new Date(now) } })
      .catch((error: unknown) =>
        this.logger.warn(
          `No se pudo actualizar lastUsedAt de ${row.clientId}: ${error instanceof Error ? error.message : String(error)}`,
        ),
      );
  }

  private async getRow(referenceId: string): Promise<ApiClientCredential> {
    const row = await this.prisma.extended.apiClientCredential.findUnique({
      where: { referenceId },
    });
    if (!row) throw new NotFoundException('Credencial de API no encontrada.');
    return row;
  }

  private assertHmacAvailable(): void {
    if (!this.signingSecrets.available) {
      throw new ConflictException(
        'El HMAC por cliente requiere ENCRYPTION_KEYS y ENCRYPTION_ACTIVE_KEY_ID configurados.',
      );
    }
  }

  private generateSecret(): string {
    return randomBytes(SECRET_BYTES).toString('base64url');
  }

  private async hash(secret: string): Promise<string> {
    return await bcrypt.hash(secret, this.config.apiClients.bcryptRounds);
  }

  private getDummyHash(): Promise<string> {
    const hash: Promise<string> =
      this.dummyHash ?? this.hash(randomBytes(SECRET_BYTES).toString('hex'));
    this.dummyHash = hash;
    return hash;
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  decryptAesGcm,
  encryptAesGcm,
  Keyring,
  parseKeyring,
} from '@common/helpers/crypto/aes-gcm.helper';

/**
 * Patrón: SRP. El signing secret HMAC debe poder leerse del lado servidor (a diferencia del
 * client secret, que solo se verifica con bcrypt), así que se guarda cifrado con AES-256-GCM
 * usando el keyring existente. Sin ENCRYPTION_KEYS el HMAC por cliente no puede habilitarse.
 */
@Injectable()
export class ApiClientSigningSecretService {
  private readonly logger = new Logger(ApiClientSigningSecretService.name);
  private readonly keyring: Keyring;
  private readonly activeKeyId: string;

  constructor(@Inject(APP_CONFIG.KEY) config: ConfigType<AppConfigType>) {
    let keyring: Keyring = new Map();
    try {
      keyring = parseKeyring(config.security.encryptionKeys);
    } catch (error) {
      this.logger.warn(
        `ENCRYPTION_KEYS inválido, el HMAC por cliente queda deshabilitado: ${error instanceof Error ? error.message : 'error'}`,
      );
    }
    this.keyring = keyring;
    this.activeKeyId = config.security.encryptionActiveKeyId;
  }

  get available(): boolean {
    return this.keyring.has(this.activeKeyId);
  }

  encrypt(secret: string): string {
    return encryptAesGcm(secret, this.keyring, this.activeKeyId);
  }

  decrypt(payload: string): string {
    return decryptAesGcm(payload, this.keyring);
  }
}

import { Injectable } from '@nestjs/common';
import { ThrottlerRequest } from '@nestjs/throttler';
import {
  BaseThrottlerGuard,
  isClientLimiter,
} from '@core/rate-limit/base-throttler.guard';
import type { ApiClientRequest } from '../interfaces/api-client-request.interface';

/**
 * Rate limiting por credencial (no global): se aplica con `@UseGuards(...)` DESPUÉS de
 * `BasicAuthGuard`. Evalúa solo el limiter `client` y lo adapta por request:
 * - tracker = `clientId` (varias integraciones pueden compartir IP/NAT; el límite es por credencial);
 * - límite = `rateLimitPerMinute` de la credencial (ya cargada por BasicAuthGuard, sin otra
 *   query) o, si no tiene, el default del limiter (`RATE_LIMIT_CLIENT_DEFAULT_PER_MINUTE`).
 */
@Injectable()
export class ApiClientThrottlerGuard extends BaseThrottlerGuard {
  protected handlesLimiter(name: string): boolean {
    return isClientLimiter(name);
  }

  protected getTracker(req: Record<string, unknown>): Promise<string> {
    const apiClient = (req as unknown as ApiClientRequest).apiClient;
    return Promise.resolve(apiClient?.id ?? (req.ip as string));
  }

  protected handleRequest(requestProps: ThrottlerRequest): Promise<boolean> {
    const request = requestProps.context
      .switchToHttp()
      .getRequest<ApiClientRequest>();
    const limit = request.apiClient?.rateLimitPerMinute ?? requestProps.limit;
    return super.handleRequest({ ...requestProps, limit });
  }
}

import { Injectable } from '@nestjs/common';
import { BaseThrottlerGuard, isClientLimiter } from './base-throttler.guard';

/** Guard GLOBAL (APP_GUARD): limiters por IP (default/auth/upload/search); ignora el `client`. */
@Injectable()
export class AppThrottlerGuard extends BaseThrottlerGuard {
  protected handlesLimiter(name: string): boolean {
    return !isClientLimiter(name);
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { auditStorage } from '../database/services/prisma.service';
import { APPLICATION_NAME_KEY } from '@common/decorators/application-name.decorator';
import { Observable } from 'rxjs';

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(private readonly reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest();

    const applicationName =
      this.reflector.getAllAndOverride<string>(APPLICATION_NAME_KEY, [
        context.getHandler(),
        context.getClass(),
      ]) ?? 'node-starter-backend';

    const store = {
      userId:
        request?.user?.email ??
        request?.body?.userEmail ??
        request?.query?.userEmail ??
        request?.params?.userEmail ??
        'system',
      ip: request.ip || request.headers['x-forwarded-for'] || 'unknown',
      userAgent: request.headers['user-agent'] || 'unknown',
      applicationName,
    };

    return auditStorage.run(store, () => next.handle());
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { AuditLogs, Prisma } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { redactDeep } from '@core/observability/redaction';
import { t } from '@common/i18n/i18n.helper';
import type {
  IAuditLogFilters,
  IAuditLogPage,
  IAuditLogRow,
  IRecentAccess,
} from '../interfaces/audit-log.interface';

/**
 * Lectura de la bitácora (`audit_logs`, escrita por el trigger genérico; esta capa NUNCA escribe).
 * `old_data`/`new_data` pasan por `redactDeep` (misma política que los logs) como defensa en
 * profundidad: si una tabla auditada guardara un campo sensible, no sale por la API.
 */
@Injectable()
export class AuditLogDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  async list(
    filters: IAuditLogFilters,
    page: number,
    pageSize: number,
  ): Promise<IAuditLogPage> {
    const where = this.buildWhere(filters);
    const [rows, total] = await this.prisma.$transaction([
      this.prisma.auditLogs.findMany({
        where,
        orderBy: { changedAt: 'desc' },
        skip: (page - 1) * pageSize,
        take: pageSize,
      }),
      this.prisma.auditLogs.count({ where }),
    ]);
    return { items: rows.map((r) => this.toRow(r)), total };
  }

  async findById(id: bigint): Promise<IAuditLogRow> {
    const row = await this.prisma.auditLogs.findUnique({ where: { id } });
    if (!row) throw new NotFoundException(t('common.NOT_FOUND'));
    return this.toRow(row);
  }

  /**
   * Recorre la bitácora por lotes con cursor (keyset por `id`): memoria constante y sin el costo
   * creciente de `skip` en tablas grandes. Pensado para alimentar `@JsonStream()`.
   */
  async *iterate(
    filters: IAuditLogFilters,
    batchSize: number,
  ): AsyncGenerator<IAuditLogRow, void, void> {
    const where = this.buildWhere(filters);
    let cursor: bigint | undefined;

    for (;;) {
      const batch = await this.prisma.auditLogs.findMany({
        where,
        orderBy: { id: 'asc' },
        take: batchSize,
        ...(cursor === undefined ? {} : { cursor: { id: cursor }, skip: 1 }),
      });
      for (const row of batch) yield this.toRow(row);
      if (batch.length < batchSize) return;
      cursor = batch[batch.length - 1].id;
    }
  }

  /**
   * Últimos accesos (inicios de sesión) del usuario: cambios de `last_login` en `users` que
   * capturó el trigger. Se compara la columna JSON entre old_data y new_data, algo que el query
   * builder de Prisma no expresa; es una consulta parametrizada (tagged template, sin
   * concatenación) sobre el índice `idx_audit_table_record`.
   */
  async getRecentAccess(userId: number, limit = 5): Promise<IRecentAccess[]> {
    return await this.prisma.$queryRaw<IRecentAccess[]>`
      SELECT "ip_address" AS "ipAddress", "changed_at" AS "changedAt"
      FROM "audit_logs"
      WHERE "table_name" = 'users'
        AND "record_id" = ${String(userId)}
        AND ("new_data" ->> 'last_login') IS DISTINCT FROM ("old_data" ->> 'last_login')
      ORDER BY "changed_at" DESC
      LIMIT ${limit}
    `;
  }

  private buildWhere(f: IAuditLogFilters): Prisma.AuditLogsWhereInput {
    return {
      tableName: f.tableName,
      operationType: f.operationType,
      changedBy: f.changedBy,
      changedAt: f.from || f.to ? { gte: f.from, lte: f.to } : undefined,
      // El trigger guarda el traceId dentro de extra_data (JSON como texto).
      extraData: f.traceId ? { contains: f.traceId } : undefined,
    };
  }

  private toRow(row: AuditLogs): IAuditLogRow {
    return {
      id: row.id.toString(),
      tableName: row.tableName,
      recordId: row.recordId,
      operationType: row.operationType,
      oldData: redactDeep(row.oldData),
      newData: redactDeep(row.newData),
      changedAt: row.changedAt,
      changedBy: row.changedBy,
      reason: row.reason,
      ipAddress: row.ipAddress,
      userAgent: row.userAgent,
      extraData: row.extraData,
      audVersion: row.audVersion,
    };
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PaginationHelper } from '@common/helpers/pagination.helper';
import type { IJsonStreamDocument } from '@common/helpers/json-stream.helper';
import { AuditLogDBService } from '@modules/audit-log-db/services/audit-log-db.service';
import type { IAuditLogRow } from '@modules/audit-log-db/interfaces/audit-log.interface';
import {
  AuditLogFiltersDTO,
  AuditLogResponseDTO,
  AuditLogsListResponseDTO,
  ListAuditLogsRequestDTO,
  RecentAccessResponseDTO,
} from '../dtos/audit-log.dto';

/** Capa API de la bitácora: filtros HTTP -> consultas de solo lectura. */
@Injectable()
export class AuditLogsApiService {
  constructor(
    private readonly auditLogs: AuditLogDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async list(
    query: ListAuditLogsRequestDTO,
  ): Promise<AuditLogsListResponseDTO> {
    const { page, pageSize, ...filters } = query;
    const { items, total } = await this.auditLogs.list(filters, page, pageSize);
    return PaginationHelper.create(
      items,
      total,
      page,
      pageSize,
    ) as AuditLogsListResponseDTO;
  }

  async findOne(id: bigint): Promise<AuditLogResponseDTO> {
    return await this.auditLogs.findById(id);
  }

  async recentAccess(
    userId: number,
    limit: number,
  ): Promise<RecentAccessResponseDTO[]> {
    return await this.auditLogs.getRecentAccess(userId, limit);
  }

  /** Documento para `@JsonStream()`: metadatos antes del array, `total` calculado al terminar. */
  buildExport(
    filters: AuditLogFiltersDTO,
  ): IJsonStreamDocument<IAuditLogRow, number> {
    return {
      pre: { generatedAt: new Date().toISOString() },
      arrayKey: 'items',
      items: this.auditLogs.iterate(filters, this.config.audit.exportBatchSize),
      accumulate: {
        initial: 0,
        reduce: (count) => count + 1,
        finalize: (count) => ({ total: count }),
      },
    };
  }
}

import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Users } from '@prisma/client';

import * as DTO from '@api/auth/dtos';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { NonceService } from '@modules/nonce/nonce.service';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { AuthService } from '@modules/auth/services/auth.service';
import { EmailService } from '@modules/email/services/email.service';
import { EmailTypeEnum } from '@modules/email/enum/email-type.enum';
import { IUserDataOnJwt } from '@modules/auth/interfaces/user-data-on-jwt.interface';
import { AuthMigrationService } from './auth-migration.service';

@Injectable()
export class AuthApiService {
  constructor(
    private readonly userService: UsersDBService,
    private readonly authService: AuthService,
    private readonly emailService: EmailService,
    private readonly authMigrationService: AuthMigrationService,
    private readonly nonceService: NonceService,
    @Inject(APP_CONFIG.KEY) private readonly config: ConfigType<AppConfigType>,
  ) {}

  /** Emite un nonce de un solo uso para el próximo login (anti-replay). */
  async issueLoginNonce(): Promise<DTO.LoginNonceResponseDTO> {
    return {
      nonce: await this.nonceService.issue(),
      expiresInSeconds: this.nonceService.ttlSeconds,
    };
  }

  /**
   * Opt-in (LOGIN_NONCE_REQUIRED): con la flag activa el nonce es obligatorio; con la flag
   * apagada (default, no rompe clientes existentes) solo se valida si el cliente lo envía.
   */
  private async assertLoginNonce(nonce: string | undefined): Promise<void> {
    if (nonce === undefined && !this.config.nonce.loginRequired) return;
    if (!(await this.nonceService.consume(nonce))) {
      throw new UnauthorizedException(
        'Nonce inválido, expirado o ya utilizado.',
      );
    }
  }

  async handleLogin(
    dto: DTO.LoginUserDTO,
    userAgent?: string,
  ): Promise<DTO.LoginUserResponseDTO> {
    await this.assertLoginNonce(dto.nonce);
    const loginResult = await this.authService.login({
      email: dto.email,
      encryptedPassword: dto.encryptedPassword,
      userAgent,
      rembemberMe: dto.rememberMe!,
    });

    if (loginResult.success) {
      return {
        login: true,
        accessToken: loginResult.accessToken,
        refreshToken: loginResult.refreshToken,
        requiredNewPassword: false,
      };
    }

    if (loginResult.requiresPasswordCreation) {
      return { login: false, requiredNewPassword: true };
    }

    return { login: false, requiredNewPassword: false };
  }

  async createPasswordWithToken(dto: DTO.CreatePasswordDTO): Promise<{
    success: boolean;
    message: string;
  }> {
    this.authMigrationService.verifyTempToken(dto.token, dto.email);
    return await this.authService.createPassword({
      email: dto.email,
      encryptedPassword: dto.encryptedPassword,
    });
  }

  async updatePassword(
    dto: DTO.UpdateUserPasswordDTO,
  ): Promise<{ success: boolean; message: string }> {
    return await this.authService.changePassword(dto);
  }

  async forgotPassword(
    dto: DTO.ForgotUserPasswordDTO,
  ): Promise<{ success: boolean; message: string }> {
    const email = this.authMigrationService.verifyForgotPasswordToken(
      dto.token,
    );
    return await this.authService.resetPassword({
      email,
      encryptedNewPassword: dto.encryptedNewPassword,
      encryptedConfirmPassword: dto.encryptedConfirmPassword,
    });
  }

  async refreshAccessToken(refreshToken: string): Promise<{
    accessToken: string;
  }> {
    return await this.authService.refreshAccessToken(refreshToken);
  }

  async scope(user: IUserDataOnJwt): Promise<DTO.UserScopeResponseDTO> {
    const [fullUser, { roles, permissions }] = await Promise.all([
      this.userService.findUserById(user.id),
      this.authService.getUserScope(user.id),
    ]);

    return {
      user: {
        id: fullUser.referenceId,
        email: fullUser.email,
        phoneNumber: fullUser.phoneNumber,
        firstName: fullUser.firstName,
        lastName: fullUser.lastName,
        status: fullUser.status,
        profileStatus: fullUser.profileStatus,
        currentAccessLevel: fullUser.currentAccessLevel,
        isEmployee: fullUser.isEmployee,
      },
      roles,
      permissions,
    };
  }

  async userVerify(user: Users): Promise<void> {
    await this.authService.verifyUser(user.id);
  }

  async userVerificationStatus(
    user: Users,
  ): Promise<{ verified: boolean; email: string }> {
    return await this.authService.checkVerificationStatus(user);
  }

  async sendVerificationEmail(to: string, user: Users): Promise<void> {
    await this.emailService.sendEmailByType(
      to,
      EmailTypeEnum.VERIFICATION,
      user,
    );
  }

  async sendPasswordResetEmail(to: string, user: Users): Promise<void> {
    await this.emailService.sendEmailByType(
      to,
      EmailTypeEnum.FORGOT_PASSWORD,
      user,
      '24h',
    );
  }

  async sendPasswordCreationEmail(to: string, user: Users): Promise<void> {
    await this.emailService.sendEmailByType(
      to,
      EmailTypeEnum.CREATE_PASSWORD,
      user,
    );
  }
}

import { Injectable, Inject } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Response } from 'express';

import { APP_CONFIG } from '@core/config/config-loader';
import { parseTime } from '@common/helpers/date.helper';

@Injectable()
export class AuthCookieService {
  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<typeof APP_CONFIG>,
  ) {}

  setAccessToken(res: Response, token: string): void {
    res.cookie('accessToken', token, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      path: '/',
      maxAge: parseTime(this.config.authentication.accessTokenExpires),
    });
  }

  setRefreshToken(res: Response, token: string, rememberMe: boolean): void {
    const expiry = rememberMe
      ? this.config.authentication.refreshTokenExpires
      : this.config.authentication.shortRefreshTokenExpires;

    res.cookie('refreshToken', token, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      path: '/',
      maxAge: parseTime(expiry),
    });
  }
}

import { Injectable, Logger, UnauthorizedException } from '@nestjs/common';

import { CryptoHelper } from '@common/helpers/crypto-helpers';

@Injectable()
export class AuthMigrationService {
  private readonly logger = new Logger(AuthMigrationService.name);

  constructor() {}

  verifyTempToken(token: string, expectedEmail: string): void {
    try {
      const payload = CryptoHelper.verifyJwt<{
        sub: string;
        email: string;
        tokenType: string;
      }>(token);

      if (
        payload.tokenType !== 'tempToken' ||
        payload.email !== expectedEmail
      ) {
        throw new UnauthorizedException('Token inválido o expirado.');
      }
    } catch {
      throw new UnauthorizedException('Token inválido o expirado.');
    }
  }

  verifyForgotPasswordToken(token: string): string {
    try {
      const payload = CryptoHelper.verifyJwt<{
        sub: string;
        email: string;
        tokenType: string;
        action?: string;
      }>(token);

      if (
        payload.tokenType !== 'tempToken' ||
        payload.action !== 'forgotPassword'
      ) {
        throw new UnauthorizedException('Token inválido o expirado.');
      }

      return payload.email;
    } catch {
      throw new UnauthorizedException('Token inválido o expirado.');
    }
  }
}

import { UserStatus } from '@prisma/client';
import {
  BadRequestException,
  ForbiddenException,
  HttpException,
  HttpStatus,
  Inject,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { validatePasswordPolicy } from '@common/helpers/password-policy.helper';
import {
  computePasswordExpiration,
  isPasswordExpired,
} from '@modules/auth/helpers/password-expiration.helper';
import {
  evaluateFailedAttempt,
  isLockedOut,
  remainingLockoutMinutes,
} from '@modules/auth/helpers/login-lockout.helper';
import { CryptoHelper } from '@common/helpers/crypto-helpers';
import { UserCredentialsWithUser } from '@modules/auth/types';
import { CredentialsRepository } from '@modules/auth/repositories';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { t } from '@common/i18n/i18n.helper';

@Injectable()
export class AuthPasswordService {
  constructor(
    private readonly credentialsRepository: CredentialsRepository,
    private readonly userRepository: UsersDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  // ==================== POLICY / LOCKOUT ====================

  /**
   * Rechaza contraseñas que no cumplen la política configurada (se invoca con la clave ya descifrada)
   */
  assertPasswordCompliant(plainPassword: string): void {
    const { valid, violations } = validatePasswordPolicy(
      plainPassword,
      this.config.security.passwordPolicy,
    );
    if (!valid) {
      throw new BadRequestException({
        statusCode: 400,
        message: t('auth.PASSWORD_POLICY_VIOLATION', {
          violations: violations.join('; '),
        }),
        code: 'PASSWORD_POLICY_VIOLATION',
      });
    }
  }

  /**
   * Lanza 423 mientras el bloqueo temporal siga vigente (se evalúa antes de validar la clave)
   */
  assertNotLocked(userCredential: UserCredentialsWithUser): void {
    if (isLockedOut(userCredential.lockedUntil)) {
      throw new HttpException(
        {
          statusCode: HttpStatus.LOCKED,
          message: t('auth.ACCOUNT_LOCKED', {
            minutes: remainingLockoutMinutes(
              userCredential.lockedUntil as Date,
            ),
          }),
          code: 'ACCOUNT_LOCKED',
        },
        HttpStatus.LOCKED,
      );
    }
  }

  /**
   * Exige renovar la contraseña si superó su vigencia (PASSWORD_EXPIRATION_DAYS)
   */
  assertPasswordNotExpired(userCredential: UserCredentialsWithUser): void {
    if (isPasswordExpired(userCredential.expiredAt)) {
      throw new ForbiddenException({
        statusCode: 403,
        message: t('auth.PASSWORD_EXPIRED'),
        code: 'PASSWORD_EXPIRED',
      });
    }
  }

  // ==================== CRYPTO OPERATIONS ====================

  /**
   * Desencripta una contraseña encriptada con RSA
   */
  decryptPassword(encryptedPassword: string): string {
    try {
      const decryptedBuffer = CryptoHelper.decrypt(encryptedPassword, 'sha256');
      return decryptedBuffer.toString('utf-8');
    } catch {
      throw new UnauthorizedException('Error al procesar las credenciales.');
    }
  }

  /**
   * Valida una contraseña contra su hash
   */
  validatePassword(plainPassword: string, hashedPassword: string): boolean {
    return CryptoHelper.compareHashes(plainPassword, hashedPassword);
  }

  /**
   * Valida una contraseña encriptada contra su hash
   * (desencripta primero, luego valida)
   */

  validateEncryptedPassword(
    encryptedPassword: string,
    hashedPassword: string,
  ): boolean {
    const plainPassword = this.decryptPassword(encryptedPassword);
    return this.validatePassword(plainPassword, hashedPassword);
  }

  /**
   * Genera un hash de una contraseña
   */

  hashPassword(password: string): string {
    return CryptoHelper.hashValue(password);
  }

  // ==================== BUSINESS LOGIC ====================

  /**
   * Maneja un intento fallido de login: al llegar a MAX_LOGIN_ATTEMPTS aplica bloqueo
   * temporal (LOCKOUT_MINUTES) o, con 0, bloqueo permanente por estado de usuario.
   */
  async handleFailedAttempt(
    userCredential: UserCredentialsWithUser,
  ): Promise<{ shouldBlock: boolean; lockedUntil: Date | null }> {
    const decision = evaluateFailedAttempt(userCredential.attempts, {
      maxAttempts: this.config.security.maxLoginAttempts,
      lockoutMinutes: this.config.security.lockoutMinutes,
    });
    userCredential.attempts = decision.attempts;
    userCredential.lockedUntil = decision.lockedUntil;

    await this.credentialsRepository.updateLockState(userCredential.id, {
      attempts: decision.attempts,
      lockedUntil: decision.lockedUntil,
    });

    if (decision.permanentBlock) {
      await this.userRepository.updateStatus(
        userCredential.userId,
        UserStatus.BLOCKED,
      );
    }

    return {
      shouldBlock: decision.permanentBlock || decision.lockedUntil !== null,
      lockedUntil: decision.lockedUntil,
    };
  }

  /**
   * Resetea intentos y bloqueo temporal después de un login exitoso
   */

  async resetFailedAttempts(
    userCredential: UserCredentialsWithUser,
  ): Promise<void> {
    if (userCredential.attempts > 0 || userCredential.lockedUntil) {
      await this.credentialsRepository.updateLockState(userCredential.id, {
        attempts: 0,
        lockedUntil: null,
      });
    }
  }

  /**
   * Crea o actualiza la contraseña de un usuario
   */
  async createOrUpdatePassword(
    userId: number,
    password: string,
  ): Promise<void> {
    this.assertPasswordCompliant(password);
    const hash = this.hashPassword(password);
    const expiredAt = computePasswordExpiration(
      this.config.security.passwordExpirationDays,
    );

    const existingCredential =
      await this.credentialsRepository.findByUserId(userId);

    if (existingCredential) {
      await this.credentialsRepository.update(existingCredential.id, {
        passwordHash: hash,
        attempts: 0,
        isActive: true,
        expiredAt,
        lockedUntil: null,
      });
    } else {
      await this.credentialsRepository.create({
        userId,
        passwordHash: hash,
        attempts: 0,
        isActive: true,
        expiredAt,
      });
    }
  }

  /**
   * Crea o actualiza la contraseña de un usuario (con password encriptada)
   */
  async createOrUpdateEncryptedPassword(
    userId: number,
    encryptedPassword: string,
  ): Promise<void> {
    const plainPassword = this.decryptPassword(encryptedPassword);
    await this.createOrUpdatePassword(userId, plainPassword);
  }

  /**
   * Cambia la contraseña de un usuario validando la anterior
   */
  async changePassword(
    userCredentials: UserCredentialsWithUser,
    oldPassword: string,
    newPassword: string,
  ): Promise<void> {
    const passwordValid = this.validatePassword(
      oldPassword,
      userCredentials.passwordHash,
    );

    if (!passwordValid) {
      throw new UnauthorizedException('Credenciales inválidas.');
    }

    this.assertPasswordCompliant(newPassword);
    const hash = this.hashPassword(newPassword);

    await this.credentialsRepository.update(userCredentials.id, {
      passwordHash: hash,
      attempts: 0,
      lockedUntil: null,
      expiredAt: computePasswordExpiration(
        this.config.security.passwordExpirationDays,
      ),
    });
  }

  /**
   * Cambia la contraseña de un usuario validando la anterior (con passwords encriptadas)
   */
  async changeEncryptedPassword(
    userCredentials: UserCredentialsWithUser,
    encryptedOldPassword: string,
    encryptedNewPassword: string,
  ): Promise<void> {
    const oldPassword = this.decryptPassword(encryptedOldPassword);
    const newPassword = this.decryptPassword(encryptedNewPassword);
    await this.changePassword(userCredentials, oldPassword, newPassword);
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  UnauthorizedException,
} from '@nestjs/common';
import { Users, UserStatus } from '@prisma/client';

import { AuthTokenService } from '@modules/auth/services/auth-token.service';
import { AuthPasswordService } from '@modules/auth/services/auth-password.service';
import { UsersDBService } from '@modules/users-db/services/users-db.service';

/**
 * Servicio principal de autenticación - Lógica de Negocio
 * Usa helpers especializados para mantener el código organizado
 */
@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    private readonly userRepository: UsersDBService,
    private readonly authTokenService: AuthTokenService,
    private readonly authPasswordService: AuthPasswordService,
  ) {}

  /**
   * Procesa el login completo de un usuario
   */
  async login(payload: {
    email: string;
    encryptedPassword: string;
    userAgent?: string;
    rembemberMe: boolean;
  }): Promise<{
    success: boolean;
    accessToken?: string;
    refreshToken?: string;
    requiresPasswordCreation: boolean;
  }> {
    // Buscar credenciales
    const userCredentials = await this.userRepository.findCredentialsByEmail(
      payload.email,
    );

    // Si no tiene credenciales, verificar si existe
    if (!userCredentials) {
      const userExists = await this.userRepository.findActiveUserByEmail(
        payload.email,
      );

      if (userExists) {
        return { success: false, requiresPasswordCreation: true };
      }
      this.logger.log(
        'No se encontraron datos para los parámetros proporcionados.',
      );
      return { success: false, requiresPasswordCreation: false };
    }

    // Validar estado
    this.validateUserStatus(userCredentials.user.status);

    // Bloqueo temporal vigente: no se evalúa la contraseña
    this.authPasswordService.assertNotLocked(userCredentials);

    // Validar contraseña encriptada
    const isPasswordValid = this.authPasswordService.validateEncryptedPassword(
      payload.encryptedPassword,
      userCredentials.passwordHash,
    );

    if (!isPasswordValid) {
      await this.authPasswordService.handleFailedAttempt(userCredentials);
      throw new UnauthorizedException('Credenciales inválidas.');
    }

    // Resetear intentos fallidos
    await this.authPasswordService.resetFailedAttempts(userCredentials);

    // Contraseña vencida (solo se revela tras validar la clave)
    this.authPasswordService.assertPasswordNotExpired(userCredentials);

    // Actualizar último login
    await this.userRepository.updateLastLogin(userCredentials.userId);

    // Generar tokens
    const tokens = this.authTokenService.generateTokens({
      user: userCredentials.user,
      rememberMe: payload.rembemberMe,
    });

    return {
      success: true,
      accessToken: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      requiresPasswordCreation: false,
    };
  }

  /**
   * Crea una contraseña para un usuario
   */
  async createPassword(payload: {
    email: string;
    encryptedPassword: string;
  }): Promise<{ success: boolean; message: string }> {
    const user = await this.userRepository.findActiveUserByEmail(payload.email);

    if (!user) {
      throw new NotFoundException('Usuario no encontrado.');
    }

    await this.authPasswordService.createOrUpdateEncryptedPassword(
      user.id,
      payload.encryptedPassword,
    );

    return {
      success: true,
      message: 'Contraseña creada correctamente.',
    };
  }

  /**
   * Cambia la contraseña de un usuario
   */
  async changePassword(payload: {
    email: string;
    encryptedOldPassword: string;
    encryptedNewPassword: string;
  }): Promise<{ success: boolean; message: string }> {
    const user = await this.userRepository.findActiveUserByEmail(payload.email);

    if (!user) {
      throw new NotFoundException('Usuario no encontrado.');
    }

    const userCredentials = await this.userRepository.findCredentialsByEmail(
      payload.email,
    );

    if (!userCredentials) {
      throw new NotFoundException(
        'No se encontraron credenciales para el usuario, favor crear contraseña.',
      );
    }

    await this.authPasswordService.changeEncryptedPassword(
      userCredentials,
      payload.encryptedOldPassword,
      payload.encryptedNewPassword,
    );

    return {
      success: true,
      message: 'Contraseña actualizada correctamente.',
    };
  }

  /**
   * Resetea la contraseña (forgot password)
   */
  async resetPassword(payload: {
    email: string;
    encryptedNewPassword: string;
    encryptedConfirmPassword: string;
  }): Promise<{ success: boolean; message: string }> {
    // Desencriptar y validar que coincidan
    const newPassword = this.authPasswordService.decryptPassword(
      payload.encryptedNewPassword,
    );
    const confirmPassword = this.authPasswordService.decryptPassword(
      payload.encryptedConfirmPassword,
    );

    if (newPassword !== confirmPassword) {
      throw new UnauthorizedException('Las contraseñas no coinciden.');
    }

    const user = await this.userRepository.findActiveUserByEmail(payload.email);

    if (!user) {
      throw new NotFoundException('Usuario no encontrado.');
    }

    const userCredentials = await this.userRepository.findCredentialsByEmail(
      payload.email,
    );

    if (!userCredentials) {
      throw new NotFoundException(
        'No se encontraron credenciales para el usuario, favor crear contraseña.',
      );
    }

    await this.authPasswordService.createOrUpdatePassword(user.id, newPassword);

    return {
      success: true,
      message: 'Contraseña actualizada correctamente.',
    };
  }

  /**
   * Refresca el access token
   */
  async refreshAccessToken(
    refreshToken: string,
  ): Promise<{ accessToken: string }> {
    const newAccessToken =
      await this.authTokenService.generateAccessTokenFromRefresh(refreshToken);

    return { accessToken: newAccessToken };
  }

  /**
   * Obtiene el scope del usuario (roles y permisos)
   */
  async getUserScope(userId: number): Promise<{
    roles: Array<{ name: string; description: string | null }>;
    permissions: Array<{ name: string }>;
  }> {
    const roles = await this.userRepository.getUserRoles(userId);

    const userPermissions =
      await this.userRepository.getUserPermissions(userId);

    //  Obtener permisos de los roles
    const roleIds = roles.map((role) => role.id);
    const rolePermissions =
      await this.userRepository.getRolePermissions(roleIds);

    // Combinar permisos (roles + directos)
    const allPermissions = [...rolePermissions, ...userPermissions];

    // Deduplicar por 'name' (movements:read, customers:update, etc)
    const uniquePermissions = allPermissions.filter(
      (perm, index, self) =>
        index === self.findIndex((p) => p.name === perm.name),
    );

    return {
      roles: roles.map((role) => ({
        name: role.name,
        description: role.description,
      })),
      permissions: uniquePermissions,
    };
  }

  /**
   * Verifica un usuario
   */
  async verifyUser(userId: number): Promise<void> {
    await this.userRepository.verifyUser(userId);
  }

  /**
   * Verifica el estado de verificación
   */
  async checkVerificationStatus(
    user: Users,
  ): Promise<{ verified: boolean; email: string }> {
    const verifiedUser = await this.userRepository.findById(user.id);
    return {
      verified: verifiedUser?.status === UserStatus.ACTIVE,
      email: user.email,
    };
  }

  /**
   * Valida el estado de un usuario
   */
  private validateUserStatus(status: UserStatus): void {
    switch (status) {
      case UserStatus.BLOCKED:
        throw new UnauthorizedException('El usuario está bloqueado.');
      case UserStatus.INACTIVE:
        throw new UnauthorizedException('El usuario no está activo.');
      case UserStatus.DELETED:
        throw new UnauthorizedException('El usuario está eliminado.');
      case UserStatus.PENDING_VERIFICATION:
        this.logger.warn('El usuario no ha verificado su cuenta.');
        return;
      case UserStatus.ACTIVE:
        return;
    }
  }
}

import {
  Inject,
  Injectable,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Users, UserStatus } from '@prisma/client';

import { PrismaDatasource } from '@core/database/services/prisma.service';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { CryptoHelper } from '@common/helpers/crypto-helpers';

/**
 * Servicio especializado en gestión de tokens de autenticación JWT (stateless)
 */
@Injectable()
export class AuthTokenService {
  private readonly logger = new Logger(AuthTokenService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    @Inject(APP_CONFIG.KEY)
    private configService: ConfigType<AppConfigType>,
  ) {
    CryptoHelper.initConfigService(configService);
  }

  /**
   * Genera access token y refresh token (stateless)
   */
  generateTokens(payload: { user: Users; rememberMe: boolean }): {
    accessToken: string;
    refreshToken: string;
  } {
    const refreshTokenExpiry = payload.rememberMe
      ? this.configService.authentication.refreshTokenExpires
      : this.configService.authentication.shortRefreshTokenExpires;

    const [accessToken, refreshToken] = [
      CryptoHelper.generateToken(
        'accessToken',
        {
          sub: payload.user.referenceId,
          email: payload.user.email,
          status: payload.user.status,
          isEmployee: payload.user.isEmployee,
          firstName: payload.user.firstName,
          lastName: payload.user.lastName,
          currentAccessLevel: payload.user.currentAccessLevel,
          userStatus: payload.user.status,
          profileStatus: payload.user.profileStatus,
        },
        'RS256',
        this.configService.authentication.accessTokenExpires,
      ),
      CryptoHelper.generateToken(
        'refreshToken',
        {
          sub: payload.user.referenceId,
          type: 'refresh',
        },
        'RS256',
        refreshTokenExpiry,
      ),
    ];

    return { accessToken, refreshToken };
  }

  /**
   * Genera un nuevo access token desde un refresh token (stateless)
   * Valida: firma, expiración y estado del usuario
   */
  async generateAccessTokenFromRefresh(refreshToken: string): Promise<string> {
    // Verificar firma y expiración del refresh token
    const payload = CryptoHelper.verifyRefreshToken(refreshToken);

    // Validar que sea un refresh token
    if (payload.tokenType !== 'refreshToken') {
      throw new UnauthorizedException('Token de refresco inválido.');
    }

    // Buscar usuario por referenceId (del payload)
    const user = await this.prisma.extended.users.findUnique({
      where: { referenceId: payload.sub },
      select: {
        id: true,
        referenceId: true,
        email: true,
        status: true,
        isEmployee: true,
        firstName: true,
        lastName: true,
      },
    });

    // Validar que el usuario existe y está activo
    if (!user) {
      throw new UnauthorizedException('Usuario inexistente.');
    }

    if (user.status !== UserStatus.ACTIVE) {
      throw new UnauthorizedException(
        'Usuario inactivo. Por favor, contacta a soporte.',
      );
    }

    // Generar nuevo access token
    const newAccessToken = CryptoHelper.generateToken(
      'accessToken',
      {
        sub: user.referenceId,
        email: user.email,
        status: user.status,
        isEmployee: user.isEmployee,
        firstName: user.firstName,
        lastName: user.lastName,
      },
      'RS256',
      this.configService.authentication.accessTokenExpires,
    );

    return newAccessToken;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { BackgroundJob, Prisma } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { BackgroundJobsRepository } from '../repositories/background-jobs.repository';
import { computeBackoffMs } from '../helpers/backoff.helper';

export interface IEnqueueJobInput {
  type: string;
  payload?: Prisma.InputJsonValue;
  maxAttempts?: number;
  runAt?: Date;
  createdBy?: number;
}

const MAX_ERROR_LENGTH = 1000;

/**
 * Cola de jobs sobre Postgres. Estados: PENDING -> RUNNING -> COMPLETED | (PENDING con backoff) |
 * FAILED. Cada transición usa update condicional por estado, así un job lo mueve un solo worker.
 */
@Injectable()
export class BackgroundJobsDBService {
  constructor(
    private readonly repository: BackgroundJobsRepository,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  enqueue(input: IEnqueueJobInput): Promise<BackgroundJob> {
    return this.repository.create({
      type: input.type,
      payload: input.payload ?? {},
      maxAttempts: input.maxAttempts ?? this.config.jobs.maxAttempts,
      nextRunAt: input.runAt ?? new Date(),
      createdBy: input.createdBy,
    });
  }

  findByReference(referenceId: string): Promise<BackgroundJob | null> {
    return this.repository.findByReference(referenceId);
  }

  /** Toma un lote de jobs de los `types` dados (los que este proceso sabe manejar). */
  async takePendingBatch(
    types: string[],
    limit: number = this.config.jobs.batchSize,
    now: Date = new Date(),
  ): Promise<BackgroundJob[]> {
    const staleBefore = new Date(
      now.getTime() - this.config.jobs.visibilityTimeoutMinutes * 60_000,
    );
    await this.repository.failExhaustedStale(
      staleBefore,
      now,
      'Tiempo de ejecución excedido sin completar',
    );
    return this.repository.claimBatch(types, limit, now, staleBefore);
  }

  async markCompleted(
    job: BackgroundJob,
    result?: Prisma.InputJsonValue,
  ): Promise<boolean> {
    return this.repository.updateWhereStatus(job.id, 'RUNNING', {
      status: 'COMPLETED',
      result: result ?? Prisma.DbNull,
      lastError: null,
      finishedAt: new Date(),
    });
  }

  /**
   * Registra un fallo. Si es reintentable y quedan intentos vuelve a PENDING con backoff
   * exponencial; si no, queda FAILED (requeue manual).
   * @returns el estado resultante
   */
  async markFailed(
    job: BackgroundJob,
    error: unknown,
    retryable = true,
    now: Date = new Date(),
  ): Promise<'PENDING' | 'FAILED'> {
    const lastError = (
      error instanceof Error ? error.message : String(error)
    ).slice(0, MAX_ERROR_LENGTH);
    const exhausted = !retryable || job.attempts >= job.maxAttempts;

    if (exhausted) {
      await this.repository.updateWhereStatus(job.id, 'RUNNING', {
        status: 'FAILED',
        lastError,
        finishedAt: now,
      });
      return 'FAILED';
    }

    const delayMs = computeBackoffMs(
      job.attempts,
      this.config.jobs.backoffBaseSeconds * 1000,
      this.config.jobs.backoffMaxSeconds * 1000,
    );
    await this.repository.updateWhereStatus(job.id, 'RUNNING', {
      status: 'PENDING',
      lastError,
      nextRunAt: new Date(now.getTime() + delayMs),
    });
    return 'PENDING';
  }

  /** Reencola manualmente un job FAILED (reinicia intentos). @returns false si no estaba FAILED */
  requeue(referenceId: string): Promise<boolean> {
    return this.repository.requeueFailed(referenceId, new Date());
  }
}

import { Injectable } from '@nestjs/common';
import { BackgroundJob, Prisma } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';

/**
 * Único punto de la cola con SQL crudo: el "claim" multi-pod necesita `FOR UPDATE SKIP LOCKED`,
 * que Prisma no expresa. Todo va parametrizado (tagged template + Prisma.join), sin concatenar.
 * Usa el cliente sin extensión de auditoría: son datos técnicos, no de negocio.
 * Los `Date` se pasan como `timestamptz` y las columnas son `timestamp` (UTC): sin
 * `AT TIME ZONE 'UTC'` Postgres los compara/asigna en la zona de la sesión y el claim se corre.
 */
@Injectable()
export class BackgroundJobsRepository {
  constructor(private readonly prisma: PrismaDatasource) {}

  create(
    data: Prisma.BackgroundJobUncheckedCreateInput,
  ): Promise<BackgroundJob> {
    return this.prisma.backgroundJob.create({ data });
  }

  findByReference(referenceId: string): Promise<BackgroundJob | null> {
    return this.prisma.backgroundJob.findUnique({ where: { referenceId } });
  }

  /**
   * Toma atómicamente hasta `limit` jobs listos y los pasa a RUNNING (attempts + 1). Dos pods
   * concurrentes nunca reciben el mismo job: `SKIP LOCKED` hace que el segundo se salte las filas
   * que el primero ya bloqueó en vez de esperarlas. También retoma jobs RUNNING huérfanos (el pod
   * murió) cuyo `started_at` superó `staleBefore`, mientras les queden intentos.
   */
  async claimBatch(
    types: string[],
    limit: number,
    now: Date,
    staleBefore: Date,
  ): Promise<BackgroundJob[]> {
    if (types.length === 0 || limit <= 0) return [];

    const claimed = await this.prisma.$queryRaw<{ id: number }[]>`
      UPDATE background_jobs
      SET status = 'RUNNING'::"BackgroundJobStatus",
          attempts = attempts + 1,
          started_at = (${now}::timestamptz AT TIME ZONE 'UTC'),
          updated_at = (${now}::timestamptz AT TIME ZONE 'UTC')
      WHERE id IN (
        SELECT id FROM background_jobs
        WHERE type IN (${Prisma.join(types)})
          AND (
            (status = 'PENDING'::"BackgroundJobStatus" AND next_run_at <= (${now}::timestamptz AT TIME ZONE 'UTC'))
            OR (
              status = 'RUNNING'::"BackgroundJobStatus"
              AND started_at < (${staleBefore}::timestamptz AT TIME ZONE 'UTC')
              AND attempts < max_attempts
            )
          )
        ORDER BY next_run_at ASC
        LIMIT ${limit}
        FOR UPDATE SKIP LOCKED
      )
      RETURNING id`;

    if (claimed.length === 0) return [];

    return this.prisma.backgroundJob.findMany({
      where: { id: { in: claimed.map((row) => row.id) } },
      orderBy: { nextRunAt: 'asc' },
    });
  }

  /** Cierra como FAILED los RUNNING huérfanos que ya agotaron sus intentos. */
  async failExhaustedStale(
    staleBefore: Date,
    now: Date,
    reason: string,
  ): Promise<number> {
    return this.prisma.$executeRaw`
      UPDATE background_jobs
      SET status = 'FAILED'::"BackgroundJobStatus",
          last_error = ${reason},
          finished_at = (${now}::timestamptz AT TIME ZONE 'UTC'),
          updated_at = (${now}::timestamptz AT TIME ZONE 'UTC')
      WHERE status = 'RUNNING'::"BackgroundJobStatus"
        AND started_at < (${staleBefore}::timestamptz AT TIME ZONE 'UTC')
        AND attempts >= max_attempts`;
  }

  /** Update condicional: solo aplica si el job sigue en el estado esperado (anti carrera). */
  async updateWhereStatus(
    id: number,
    status: BackgroundJob['status'],
    data: Prisma.BackgroundJobUncheckedUpdateManyInput,
  ): Promise<boolean> {
    const { count } = await this.prisma.backgroundJob.updateMany({
      where: { id, status },
      data,
    });
    return count === 1;
  }

  async requeueFailed(referenceId: string, now: Date): Promise<boolean> {
    const { count } = await this.prisma.backgroundJob.updateMany({
      where: { referenceId, status: 'FAILED' },
      data: {
        status: 'PENDING',
        attempts: 0,
        nextRunAt: now,
        finishedAt: null,
        startedAt: null,
      },
    });
    return count === 1;
  }
}

import { Injectable } from '@nestjs/common';
import { BackgroundJob } from '@prisma/client';
import { ScheduledJob, SchedulerCronKey } from '@core/scheduler/scheduled-job';
import { BackgroundJobsDBService } from '@modules/jobs-db/services/background-jobs-db.service';
import { JobHandlerRegistry } from '../services/job-handler.registry';
import { NonRetryableJobError } from '../errors/non-retryable-job.error';

/**
 * Worker de la cola: un `ScheduledJob` más. No usa advisory lock (`lockId = null`) porque el
 * claim con `FOR UPDATE SKIP LOCKED` ya reparte jobs distintos entre pods; un lock global
 * serializaría a todos los workers y anularía el escalado horizontal.
 */
@Injectable()
export class BackgroundJobWorkerJob extends ScheduledJob {
  readonly name = 'background-job-worker';
  readonly cronConfigKey: SchedulerCronKey = 'jobsWorker';
  readonly lockId = null;

  constructor(
    private readonly jobs: BackgroundJobsDBService,
    private readonly registry: JobHandlerRegistry,
  ) {
    super();
  }

  async run(): Promise<void> {
    const batch = await this.jobs.takePendingBatch(this.registry.getTypes());

    for (const job of batch) {
      await this.process(job);
    }
  }

  private async process(job: BackgroundJob): Promise<void> {
    const handler = this.registry.find(job.type);
    if (!handler) {
      await this.jobs.markFailed(
        job,
        new Error(`Sin handler para "${job.type}"`),
        false,
      );
      return;
    }

    try {
      const result = await handler.handle({
        id: job.id,
        referenceId: job.referenceId,
        type: job.type,
        attempt: job.attempts,
        payload: job.payload,
        createdBy: job.createdBy,
      });
      await this.jobs.markCompleted(job, result ?? undefined);
    } catch (error) {
      const outcome = await this.jobs.markFailed(
        job,
        error,
        !(error instanceof NonRetryableJobError),
      );
      this.logger.warn(
        `Job ${job.referenceId} (${job.type}) falló en el intento ${job.attempts}/${job.maxAttempts} -> ${outcome}`,
      );
    }
  }
}

import { ExecutionContext, Injectable } from '@nestjs/common';
import {
  ThrottlerException,
  ThrottlerGuard,
  ThrottlerLimitDetail,
} from '@nestjs/throttler';
import { RequestContext } from '@common/context/request-context';
import { CLIENT_LIMITER } from './rate-limit.constants';
import { t } from '@common/i18n/i18n.helper';

/**
 * Patrón: Template Method sobre `ThrottlerGuard`. Centraliza lo común a los guards de rate
 * limiting: loguear cada 429 con traceId (correlación con el cliente) y la selección de qué
 * limiters evalúa cada subclase (global vs. por credencial).
 */
@Injectable()
export abstract class BaseThrottlerGuard extends ThrottlerGuard {
  /** `true` si esta subclase evalúa el limiter con ese nombre. */
  protected abstract handlesLimiter(name: string): boolean;

  async onModuleInit(): Promise<void> {
    await super.onModuleInit();
    this.throttlers = this.throttlers.filter((throttler) =>
      this.handlesLimiter(throttler.name ?? 'default'),
    );
  }

  protected throwThrottlingException(
    context: ExecutionContext,
    detail: ThrottlerLimitDetail,
  ): Promise<void> {
    const request = context.switchToHttp().getRequest<{
      method?: string;
      originalUrl?: string;
    }>();
    const traceId = RequestContext.getTraceId() ?? 'n/a';
    this.logger.warn(
      `429 ${request.method ?? ''} ${request.originalUrl ?? ''} traceId=${traceId} tracker=${detail.tracker} limit=${detail.limit} retryAfter=${detail.timeToBlockExpire}s`,
    );
    return Promise.reject(
      new ThrottlerException(t('errors.TOO_MANY_REQUESTS')),
    );
  }
}

export const isClientLimiter = (name: string): boolean =>
  name === CLIENT_LIMITER;

import {
  Global,
  Inject,
  Injectable,
  Logger,
  Module,
  OnModuleDestroy,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import {
  CACHE_MANAGER,
  CacheModule as NestCacheModule,
} from '@nestjs/cache-manager';
import type { Cache } from 'cache-manager';
import KeyvRedis from '@keyv/redis';
import Keyv from 'keyv';
import { createKeyv } from 'cacheable';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PermissionsCacheService } from './permissions-cache.service';

const logger = new Logger('CacheModule');

/** Cierra la conexión del store (Redis) al apagar la app, para no dejar sockets abiertos. */
@Injectable()
class CacheShutdown implements OnModuleDestroy {
  constructor(@Inject(CACHE_MANAGER) private readonly cache: Cache) {}

  async onModuleDestroy(): Promise<void> {
    await this.cache.disconnect().catch(() => undefined);
  }
}

/**
 * Patrón: Factory por configuración sobre `@nestjs/cache-manager`. Con REDIS_URL el store es
 * Redis (compartido entre instancias, vía Keyv); sin él, un LRU en memoria acotado por
 * CACHE_MAX_ITEMS. Un fallo de Redis en cache degrada a "miss" (Keyv emite 'error', no lanza),
 * nunca rompe el request. TTL en ms (convención de cache-manager v7).
 */
@Global()
@Module({
  imports: [
    NestCacheModule.registerAsync({
      inject: [APP_CONFIG.KEY],
      useFactory: (config: ConfigType<AppConfigType>) => {
        const { defaultTtlSeconds, maxItems } = config.cache;
        const ttl = defaultTtlSeconds * 1000;
        if (!config.redis.url) {
          return { stores: [createKeyv({ ttl, lruSize: maxItems })], ttl };
        }
        const redisStore = new KeyvRedis(config.redis.url, {
          keyPrefixSeparator: ':',
        });
        redisStore.on('error', (error: Error) =>
          logger.warn(`Redis (cache): ${error.message}`),
        );
        const keyv = new Keyv({
          store: redisStore,
          namespace: `${config.redis.keyPrefix}cache`,
          ttl,
        });
        keyv.on('error', (error: Error) =>
          logger.warn(`Cache degradado a miss: ${error.message}`),
        );
        return { stores: [keyv], ttl };
      },
    }),
  ],
  providers: [PermissionsCacheService, CacheShutdown],
  exports: [NestCacheModule, PermissionsCacheService],
})
export class AppCacheModule {}

