import { Injectable, NotFoundException } from '@nestjs/common';
import { Op, WhereOptions } from '@sequelize/core';
import { SequelizeBaseService } from '@core/database/base/sequelize/sequelize-base.service';
import { dateToDb2Number } from '@core/database/helpers/db2-date.helper';
import { ItemEntity } from '../entities/item.entity';
import { CatalogOrmHelper } from '../helpers/catalog-orm.helper';
import {
  ICatalogOrmCreate,
  ICatalogOrmItemView,
  ICatalogOrmListParams,
  ICatalogOrmStockView,
  ICatalogOrmUpdate,
  ItemAttributes,
} from '../interfaces/catalog-orm.interface';
import {
  CatalogCategoryRepository,
  CatalogItemRepository,
  CatalogItemStockRepository,
} from '../repositories/catalog-orm.repositories';

/**
 * Patrón: Template/base service (DRY). Hereda el CRUD genérico de `SequelizeBaseService` y agrega
 * lo propio del dominio (filtros, mapeo a vista, 404). Estrategia "ORM tipado": CRUD plano por ORM;
 * lo que el ORM no expresa bien (SP, TVF, JSON_TABLE) va por SQL crudo (ver `catalog-raw`).
 */
@Injectable()
export class CatalogOrmService extends SequelizeBaseService<
  ItemEntity,
  ItemAttributes,
  CatalogItemRepository
> {
  constructor(
    repository: CatalogItemRepository,
    private readonly categories: CatalogCategoryRepository,
    private readonly stocks: CatalogItemStockRepository,
  ) {
    super(repository);
  }

  async list(
    params: ICatalogOrmListParams,
  ): Promise<{ items: ICatalogOrmItemView[]; total: number }> {
    const where: Record<string, unknown> = {};
    if (params.categoryCode)
      where.categoryCode = params.categoryCode.toUpperCase();
    if (params.status) {
      where.statusCode = {
        [Op.in]: CatalogOrmHelper.resolveStatusValues(params.status),
      };
    }
    if (params.description) {
      where.description = {
        [Op.like]: `%${params.description.toUpperCase().trim()}%`,
      };
    }

    const { rows, count } = await this.repository.findAll(
      where as WhereOptions<ItemAttributes>,
      {
        limit: params.pageSize,
        offset: (params.page - 1) * params.pageSize,
        // ORDER BY obligatorio: sin él las páginas no son determinísticas.
        order: [['itemCode', 'ASC']],
        include: [{ association: 'category' }],
      },
    );
    return {
      items: rows.map((row) => CatalogOrmHelper.toItemView(row)),
      total: count,
    };
  }

  async getByCode(code: string): Promise<ICatalogOrmItemView> {
    const item = await this.repository.findOne(
      { itemCode: code.toUpperCase().trim() },
      {},
    );
    if (!item) throw new NotFoundException(`Ítem ${code} no encontrado`);
    return CatalogOrmHelper.toItemView(item);
  }

  async createItem(dto: ICatalogOrmCreate): Promise<ICatalogOrmItemView> {
    const created = await this.repository.createOne({
      ...dto,
      statusCode: 'A',
      createdOn: String(dateToDb2Number(new Date())),
    });
    return CatalogOrmHelper.toItemView(created);
  }

  async updateItem(
    code: string,
    patch: ICatalogOrmUpdate,
  ): Promise<ICatalogOrmItemView> {
    const values: Partial<ItemAttributes> = {};
    if (patch.description !== undefined) values.description = patch.description;
    if (patch.price !== undefined) values.price = patch.price;
    if (patch.status !== undefined) {
      values.statusCode = CatalogOrmHelper.resolveStatusValues(patch.status)[0];
    }

    // UPDATE sobre una clave inexistente no falla (afecta 0 filas): el 404 sale de releer.
    const updated = await this.repository.updateOne(
      { itemCode: code.toUpperCase().trim() },
      values,
    );
    if (!updated) throw new NotFoundException(`Ítem ${code} no encontrado`);
    return CatalogOrmHelper.toItemView(updated);
  }

  async removeItem(code: string): Promise<void> {
    const affected = await this.repository.delete({
      itemCode: code.toUpperCase().trim(),
    });
    if (affected === 0)
      throw new NotFoundException(`Ítem ${code} no encontrado`);
  }

  async listStocks(code: string): Promise<ICatalogOrmStockView[]> {
    const { rows } = await this.stocks.findAll(
      { itemCode: code.toUpperCase().trim() },
      { order: [['warehouseCode', 'ASC']] },
    );
    return rows.map((row) => CatalogOrmHelper.toStockView(row));
  }

  async listCategories(): Promise<
    Array<{ code: string; description: string }>
  > {
    const { rows } = await this.categories.findAll(
      { statusCode: 'A' },
      { order: [['categoryCode', 'ASC']] },
    );
    return rows.map((row) => ({
      code: row.categoryCode.trimEnd(),
      description: row.description.trimEnd(),
    }));
  }
}

import { BadRequestException, Injectable, Optional } from '@nestjs/common';
import { PaginationHelper } from '@common/helpers/pagination.helper';
import { requireDatabase } from '@core/database/helpers/require-database.helper';
import { CatalogRawService } from '@modules/catalog-raw/services/catalog-raw.service';
import {
  AffectedRowsResponseDTO,
  CatalogItemResponseDTO,
  CatalogItemsListResponseDTO,
  ProcedureResultResponseDTO,
} from '../dtos/response';
import {
  ChangeCatalogItemsStatusRequestDTO,
  CreateCatalogItemRequestDTO,
  ListCatalogItemsRequestDTO,
  UpdateCatalogPricesRequestDTO,
} from '../dtos/request';

/**
 * Patrón: API Service = orquestador sin SQL (capas: controller -> api service -> db service ->
 * repository). El servicio de datos es `@Optional()`: sin `DATABASE_CONNECTION_STRING` el módulo de
 * datos no se registra y cada operación responde 503 claro (ver `requireDatabase`).
 */
@Injectable()
export class CatalogRawApiService {
  constructor(@Optional() private readonly catalog?: CatalogRawService) {}

  async list(
    query: ListCatalogItemsRequestDTO,
  ): Promise<CatalogItemsListResponseDTO> {
    const { items, total } = await requireDatabase(this.catalog).list(query);
    return PaginationHelper.create(items, total, query.page, query.pageSize);
  }

  async findOne(code: string): Promise<CatalogItemResponseDTO> {
    return requireDatabase(this.catalog).getByCode(code);
  }

  async create(
    dto: CreateCatalogItemRequestDTO,
  ): Promise<CatalogItemResponseDTO> {
    return requireDatabase(this.catalog).create(dto);
  }

  async changeStatus(
    dto: ChangeCatalogItemsStatusRequestDTO,
  ): Promise<AffectedRowsResponseDTO> {
    const affectedRows = await requireDatabase(this.catalog).changeStatus(
      dto.codes,
      dto.status,
    );
    return { affectedRows };
  }

  async updatePrices(
    dto: UpdateCatalogPricesRequestDTO,
  ): Promise<AffectedRowsResponseDTO> {
    const codes = dto.items.map((item) => item.code.toUpperCase());
    if (new Set(codes).size !== codes.length) {
      throw new BadRequestException('El lote tiene códigos repetidos.');
    }
    const affectedRows = await requireDatabase(this.catalog).updatePrices(
      dto.items,
    );
    return { affectedRows };
  }

  async listByCategory(
    categoryCode: string,
  ): Promise<CatalogItemResponseDTO[]> {
    return requireDatabase(this.catalog).listByCategoryFunction(categoryCode);
  }

  async recalculate(
    categoryCode: string,
    actor: string,
  ): Promise<ProcedureResultResponseDTO[]> {
    const rows = await requireDatabase(this.catalog).recalculate(
      categoryCode,
      actor,
    );
    return rows.map((row) => ({
      code: String(row.code).trim(),
      message: String(row.message ?? '').trim(),
    }));
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { QueryTypes, Transaction } from '@sequelize/core';
import { SqlQueryHelper } from '@common/helpers/sql-query.helper';
import { DatabaseConnections } from '@core/database/enum/database.enum';
import { SequelizeService } from '@core/database/services/sequelize.service';
import { CatalogItemHelper } from '../helpers/catalog-item.helper';
import {
  CatalogItemFilterParams,
  CatalogItemQueryParams,
  ICatalogItemCreate,
  ICatalogItemRaw,
  ICatalogPriceUpdate,
  IProcedureResultRaw,
} from '../interfaces/catalog-item.interface';

/**
 * Patrón: Repository de SQL crudo (estrategia "solo raw query"). Todo el SQL se arma en el helper
 * y se ejecuta aquí con `QueryTypes` explícito. Los errores de Sequelize NO se capturan: suben al
 * `SequelizeExceptionFilter` (409/503/500 sin detalle DB2). Un spec con mocks no prueba el SQL real:
 * verificarlo contra la base antes de darlo por cerrado.
 */
@Injectable()
export class CatalogRawRepository {
  constructor(
    @Inject(DatabaseConnections.DEFAULT)
    private readonly db: SequelizeService,
  ) {}

  /**
   * Página de datos + total con los MISMOS filtros, en paralelo (2 queries; el límite sano por
   * request en IBM i es ~5-7 en `Promise.all`, si hace falta más consolidar con CTEs).
   */
  async findPage(
    params: CatalogItemQueryParams,
  ): Promise<{ rows: ICatalogItemRaw[]; total: number }> {
    const { query, replacements } = CatalogItemHelper.buildItemsQuery(params);
    const { query: countQuery, replacements: countReplacements } =
      CatalogItemHelper.buildCountQuery(this.toFilters(params));
    const sequelize = this.db.getInstance();

    const [rows, countRow] = await Promise.all([
      sequelize.query<ICatalogItemRaw>(query, {
        replacements,
        type: QueryTypes.SELECT,
      }),
      sequelize.query<{ total: string | number }>(countQuery, {
        replacements: countReplacements,
        type: QueryTypes.SELECT,
        plain: true,
      }),
    ]);

    return { rows, total: Number(countRow?.total ?? 0) };
  }

  /** `plain: true` devuelve `T | null` (no `T`): el tipo de retorno lo declara explícito. */
  async findByCode(code: string): Promise<ICatalogItemRaw | null> {
    const { query, replacements } = CatalogItemHelper.buildItemsQuery({
      exactCode: code,
      page: 1,
      pageSize: 1,
    });
    return this.db.getInstance().query<ICatalogItemRaw>(query, {
      replacements,
      type: QueryTypes.SELECT,
      plain: true,
    });
  }

  /** INSERT parametrizado. Una clave duplicada sube como SQL0803 y el filtro la traduce a 409. */
  async insertItem(
    item: ICatalogItemCreate & { createdAt: number },
    transaction?: Transaction,
  ): Promise<void> {
    await this.db.getInstance().query(
      `INSERT INTO APPLIB.ITEMS (ITMCOD, ITMDSC, ITMCAT, ITMSTS, ITMPRC, ITMFEC)
       VALUES (:code, :description, :categoryCode, 'A', :price, :createdAt)`,
      {
        replacements: { ...item },
        type: QueryTypes.INSERT,
        transaction,
      },
    );
  }

  /**
   * UPDATE masivo por códigos. `QueryTypes.BULKUPDATE` es el único tipo que en este dialecto
   * devuelve las filas afectadas como número (sin `type`, el driver devuelve `[[], []]` y
   * `Number(resultado)` da siempre 0). Un UPDATE sobre códigos inexistentes no falla: afecta 0.
   */
  async updateStatusByCodes(
    codes: string[],
    statusCode: string,
    transaction?: Transaction,
  ): Promise<number> {
    const { placeholders, replacements } = SqlQueryHelper.buildInPlaceholders(
      'codes',
      codes,
    );
    const affected = await this.db
      .getInstance()
      .query(
        `UPDATE APPLIB.ITEMS SET ITMSTS = :statusCode WHERE ITMCOD IN (${placeholders})`,
        {
          replacements: { ...replacements, statusCode },
          type: QueryTypes.BULKUPDATE,
          transaction,
        },
      );
    return Number(affected ?? 0);
  }

  /**
   * Lote vía JSON: UN parámetro JSON por `bind` + `JSON_TABLE` en el servidor, en vez de N round-trips.
   * Por qué `bind` y no `replacements`: `replacements` INTERPOLA el valor en el texto SQL y DB2 for i
   * corta con SQL0101 (sentencia demasiado larga) al pasar ~32 KB de literal; `bind` manda el valor
   * como parámetro real (CLOB) y el SQL queda chico. Se serializa solo lo que el SQL lee.
   */
  async updatePricesBatch(
    items: ICatalogPriceUpdate[],
    transaction?: Transaction,
  ): Promise<number> {
    const payload = JSON.stringify({
      items: items.map(({ code, price }) => ({ code, price })),
    });
    const affected = await this.db.getInstance().query(
      `MERGE INTO APPLIB.ITEMS T
       USING (
         SELECT J.ITMCOD, J.PRICE
         FROM JSON_TABLE($1, 'lax $.items[*]' COLUMNS (
           ITMCOD CHAR(10)      PATH '$.code',
           PRICE  DECIMAL(11,2) PATH '$.price')) AS J
       ) S ON T.ITMCOD = S.ITMCOD
       WHEN MATCHED THEN UPDATE SET T.ITMPRC = S.PRICE`,
      { bind: [payload], type: QueryTypes.BULKUPDATE, transaction },
    );
    return Number(affected ?? 0);
  }

  /**
   * Función tabular: `SELECT ... FROM TABLE(schema.FN(?))`, con `QueryTypes.SELECT` y parámetros
   * posicionales. `FN_EXAMPLE` es ficticia: ajustar al objeto real del proyecto.
   */
  async findByTableFunction(categoryCode: string): Promise<ICatalogItemRaw[]> {
    return this.db.getInstance().query<ICatalogItemRaw>(
      `SELECT
         TRIM(T.ITMCOD) AS "code",
         TRIM(T.ITMDSC) AS "description",
         TRIM(T.ITMCAT) AS "categoryCode",
         '' AS "categoryDescription",
         T.ITMSTS AS "status",
         T.ITMPRC AS "price",
         T.ITMFEC AS "createdAt"
       FROM TABLE(APPLIB.FN_EXAMPLE(?)) AS T
       ORDER BY T.ITMCOD`,
      { replacements: [categoryCode], type: QueryTypes.SELECT },
    );
  }

  /**
   * Stored procedure: `CALL schema.SP(?, ?)` con `QueryTypes.SELECT` (así el dialecto devuelve el
   * result set). Los SP NO llevan parámetros OUT: el driver ODBC no puede bindear literales en un
   * OUT y falla con SQL0469; lo que deba devolver, lo devuelve como result set `(CODE, MESSAGE)`.
   * Un SP que falla lo hace con SIGNAL (llega como excepción). `SP_EXAMPLE` es ficticio.
   *
   * COMMITMENT CONTROL: un SP `*CHG` participa de `transaction` (su COMMIT/ROLLBACK arrastra todo);
   * uno `*NONE` escribe fuera de ella y no se revierte: llamarlo post-commit y SIN `transaction`.
   */
  async callExampleProcedure(
    categoryCode: string,
    actor: string,
    transaction?: Transaction,
  ): Promise<IProcedureResultRaw[]> {
    return this.db
      .getInstance()
      .query<IProcedureResultRaw>('CALL APPLIB.SP_EXAMPLE(?, ?)', {
        replacements: [categoryCode, actor],
        type: QueryTypes.SELECT,
        transaction,
      });
  }

  private toFilters(params: CatalogItemQueryParams): CatalogItemFilterParams {
    const { code, exactCode, description, status, categoryCodes } = params;
    return { code, exactCode, description, status, categoryCodes };
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { dateToDb2Number } from '@core/database/helpers/db2-date.helper';
import {
  CatalogItemHelper,
  ICatalogItemView,
} from '../helpers/catalog-item.helper';
import {
  CatalogItemQueryParams,
  CatalogItemUiStatus,
  ICatalogItemCreate,
  ICatalogPriceUpdate,
  IProcedureResultRaw,
} from '../interfaces/catalog-item.interface';
import { CatalogRawRepository } from '../repositories/catalog-raw.repository';

/**
 * Patrón: DB Service (capa de dominio de datos): arma los parámetros, llama al repositorio y mapea
 * filas crudas a vistas. Sin HTTP ni SQL. Las validaciones de negocio (BadRequest) van en el API
 * service; aquí solo se lanza NotFound cuando un lookup por PK no devuelve fila.
 */
@Injectable()
export class CatalogRawService {
  constructor(private readonly repository: CatalogRawRepository) {}

  async list(
    params: CatalogItemQueryParams,
  ): Promise<{ items: ICatalogItemView[]; total: number }> {
    const { rows, total } = await this.repository.findPage(params);
    return {
      items: rows.map((row) => CatalogItemHelper.mapToView(row)),
      total,
    };
  }

  async getByCode(code: string): Promise<ICatalogItemView> {
    const raw = await this.repository.findByCode(code);
    if (!raw) throw new NotFoundException(`Ítem ${code} no encontrado`);
    return CatalogItemHelper.mapToView(raw);
  }

  async create(item: ICatalogItemCreate): Promise<ICatalogItemView> {
    await this.repository.insertItem({
      ...item,
      createdAt: dateToDb2Number(new Date()),
    });
    return this.getByCode(item.code);
  }

  /** Cambia el estado de varios ítems y devuelve cuántas filas afectó realmente. */
  async changeStatus(
    codes: string[],
    status: CatalogItemUiStatus,
  ): Promise<number> {
    const [statusCode] = CatalogItemHelper.resolveStatusValues(status);
    return this.repository.updateStatusByCodes(codes, statusCode);
  }

  async updatePrices(items: ICatalogPriceUpdate[]): Promise<number> {
    return this.repository.updatePricesBatch(items);
  }

  async listByCategoryFunction(
    categoryCode: string,
  ): Promise<ICatalogItemView[]> {
    const rows = await this.repository.findByTableFunction(categoryCode);
    return rows.map((row) => CatalogItemHelper.mapToView(row));
  }

  async recalculate(
    categoryCode: string,
    actor: string,
  ): Promise<IProcedureResultRaw[]> {
    return this.repository.callExampleProcedure(categoryCode, actor);
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { UserCredentials } from '@prisma/client';

@Injectable()
export class CredentialsRepository {
  constructor(private readonly prisma: PrismaDatasource) {}

  /**
   * Busca credenciales por userId
   */
  async findByUserId(userId: number): Promise<UserCredentials | null> {
    return await this.prisma.extended.userCredentials.findFirst({
      where: { userId },
    });
  }

  /**
   * Crea nuevas credenciales
   */
  async create(data: {
    userId: number;
    passwordHash: string;
    attempts?: number;
    isActive?: boolean;
    expiredAt?: Date | null;
  }): Promise<UserCredentials> {
    return await this.prisma.extended.userCredentials.create({
      data: {
        userId: data.userId,
        passwordHash: data.passwordHash,
        attempts: data.attempts ?? 0,
        isActive: data.isActive ?? true,
        expiredAt: data.expiredAt ?? null,
      },
    });
  }

  /**
   * Actualiza credenciales
   */
  async update(
    id: number,
    data: {
      passwordHash?: string;
      attempts?: number;
      isActive?: boolean;
      expiredAt?: Date | null;
      lockedUntil?: Date | null;
    },
  ): Promise<UserCredentials> {
    return await this.prisma.extended.userCredentials.update({
      where: { id },
      data,
    });
  }

  /**
   * Actualiza intentos fallidos y bloqueo temporal en una sola escritura
   */
  async updateLockState(
    id: number,
    state: { attempts: number; lockedUntil: Date | null },
  ): Promise<void> {
    await this.prisma.extended.userCredentials.update({
      where: { id },
      data: state,
    });
  }

  /**
   * Actualiza solo los intentos
   */
  async updateAttempts(id: number, attempts: number): Promise<void> {
    await this.prisma.extended.userCredentials.update({
      where: { id },
      data: { attempts },
    });
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Model, ModelStatic } from '@sequelize/core';
import fg from 'fast-glob';

/** Patrón de entities: `*.entity.js` (build) o `*.entity.ts` (ts-node/tsx); nunca `.d.ts`. */
const ENTITY_GLOB = [
  '**/*.entity.{js,ts}',
  '!**/*.d.ts',
  '!**/node_modules/**',
];

function isModelClass(candidate: unknown): candidate is ModelStatic<Model> {
  return (
    typeof candidate === 'function' &&
    (Object.prototype.isPrototypeOf.call(Model, candidate) as boolean)
  );
}

/**
 * Patrón: descubrimiento por convención (convention over configuration). Registra como modelo
 * TODA clase exportada que extienda `Model` desde cualquier `*.entity.{js,ts}`; un archivo
 * `.entity` sin modelos se avisa en el log y uno que no carga se reporta sin tumbar el resto.
 * El resultado se deduplica por referencia (un mismo archivo puede existir como .ts y .js).
 */
@Injectable()
export class DatabaseHelper {
  private readonly logger = new Logger(DatabaseHelper.name);

  /**
   * Carga los modelos desde el directorio especificado.
   * @param directory Directorio base para buscar modelos
   * @returns Lista de modelos cargados (sin duplicados, orden estable por ruta)
   */
  async loadModels(directory: string): Promise<ModelStatic<Model>[]> {
    const files = (
      await fg(ENTITY_GLOB, { cwd: directory, absolute: true, onlyFiles: true })
    ).sort();

    const models = new Set<ModelStatic<Model>>();
    for (const file of files) {
      let exported: Record<string, unknown>;
      try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        exported = require(file) as Record<string, unknown>;
      } catch (error) {
        this.logger.error(
          `No se pudo cargar la entity ${file}: ${error instanceof Error ? error.message : String(error)}`,
        );
        continue;
      }

      const found = Object.values(exported).filter(isModelClass);
      if (found.length === 0) {
        this.logger.warn(
          `Archivo ignorado: no exporta un modelo válido (${file})`,
        );
      }
      found.forEach((model) => models.add(model));
    }

    this.logger.log(
      `Modelos cargados: ${[...models].map((model) => model.name).join(', ') || '(ninguno)'}`,
    );
    return [...models];
  }
}

import { Injectable } from '@nestjs/common';
import { DataRetentionPolicy, RetentionAction } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';

export interface IUpsertRetentionPolicy {
  entity: string;
  retentionDays: number;
  action: RetentionAction;
  isActive: boolean;
  actor: string;
}

/** Políticas de retención por entidad (una fila por `entity`). Las aplica el job de anonimización. */
@Injectable()
export class DataRetentionDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  list(): Promise<DataRetentionPolicy[]> {
    return this.prisma.dataRetentionPolicy.findMany({
      orderBy: { entity: 'asc' },
    });
  }

  listActive(): Promise<DataRetentionPolicy[]> {
    return this.prisma.dataRetentionPolicy.findMany({
      where: { isActive: true },
    });
  }

  upsert(input: IUpsertRetentionPolicy): Promise<DataRetentionPolicy> {
    const data = {
      retentionDays: input.retentionDays,
      action: input.action,
      isActive: input.isActive,
    };
    return this.prisma.extended.dataRetentionPolicy.upsert({
      where: { entity: input.entity },
      create: { ...data, entity: input.entity, createdBy: input.actor },
      update: { ...data, lastChangedBy: input.actor },
    });
  }
}

