import { Inject, Injectable } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { BaseHttpClient } from '../base-http.client';
import { createAuthStrategy, HttpAuthType } from '../auth/http-auth-strategy';

export interface UpstreamEcho {
  args?: Record<string, string>;
  json?: unknown;
  headers?: Record<string, string>;
  url?: string;
}

/**
 * STUB de ejemplo: copiar como plantilla para un upstream real. Apunta por defecto a un
 * servicio público tipo httpbin (`UPSTREAM_EXAMPLE_BASE_URL`); no se invoca en tests.
 */
@Injectable()
export class ExampleUpstreamClient extends BaseHttpClient {
  constructor(
    http: HttpService,
    @Inject(APP_CONFIG.KEY) config: ConfigType<AppConfigType>,
  ) {
    const upstream = config.upstreamExample;
    super(http, {
      name: 'ExampleUpstream',
      baseURL: upstream.baseUrl,
      timeoutMs: upstream.timeoutMs,
      auth: createAuthStrategy({
        type: upstream.authType as HttpAuthType,
        user: upstream.authUser,
        secret: upstream.authSecret,
        signingSecret: upstream.signingSecret,
        headerName: upstream.authHeader,
      }),
      retry: {
        attempts: upstream.retryAttempts,
        delayMs: upstream.retryDelayMs,
      },
    });
  }

  /** GET idempotente: se reintenta ante 502/503/504. */
  async echo(params: Record<string, string> = {}): Promise<UpstreamEcho> {
    return await this.get<UpstreamEcho>('/anything', { params });
  }

  /** POST no idempotente: sin retry salvo que el caller lo fuerce con una Idempotency-Key. */
  async submit(payload: Record<string, unknown>): Promise<UpstreamEcho> {
    return await this.post<UpstreamEcho>('/anything', payload);
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { PushChannel } from '@prisma/client';
import { App, cert, getApps, initializeApp } from 'firebase-admin/app';
import { getMessaging } from 'firebase-admin/messaging';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  IPushPayload,
  IPushProvider,
  IPushSendResult,
  IPushTarget,
  PushSendOutcome,
} from '../interfaces/push-provider.interface';

const APP_NAME = 'starter-fcm';
const GONE_CODES: ReadonlySet<string> = new Set([
  'messaging/registration-token-not-registered',
  'messaging/invalid-registration-token',
]);

/**
 * Adapter FCM (`firebase-admin`). Credenciales opcionales: si faltan o son inválidas el provider
 * queda deshabilitado (`isEnabled() === false`) y NUNCA tumba el arranque.
 */
@Injectable()
export class FcmPushProvider implements IPushProvider {
  readonly channel = PushChannel.FCM;
  readonly name = 'FCM';
  private readonly logger = new Logger(FcmPushProvider.name);
  private app: App | null = null;

  constructor(@Inject(APP_CONFIG.KEY) config: ConfigType<AppConfigType>) {
    const { projectId, clientEmail, privateKey } = config.push.firebase;
    if (!projectId || !clientEmail || !privateKey) return;

    try {
      this.app =
        getApps().find((existing) => existing.name === APP_NAME) ??
        initializeApp(
          { credential: cert({ projectId, clientEmail, privateKey }) },
          APP_NAME,
        );
    } catch (error) {
      this.app = null;
      this.logger.warn(
        `Credenciales de Firebase inválidas, FCM deshabilitado: ${error instanceof Error ? error.message : 'error'}`,
      );
    }
  }

  isEnabled(): boolean {
    return this.app !== null;
  }

  async send(
    target: IPushTarget,
    payload: IPushPayload,
  ): Promise<IPushSendResult> {
    if (!this.app) {
      return { outcome: PushSendOutcome.FAILED, error: 'FCM no configurado' };
    }

    try {
      const providerMessageId = await getMessaging(this.app).send({
        token: target.token,
        notification: { title: payload.title, body: payload.body },
        data: payload.data,
      });
      return { outcome: PushSendOutcome.SENT, providerMessageId };
    } catch (error) {
      const code = (error as { code?: string } | undefined)?.code;
      if (code && GONE_CODES.has(code)) {
        return { outcome: PushSendOutcome.GONE, error: code };
      }
      const message = error instanceof Error ? error.message : 'unknown';
      this.logger.error(`Fallo al enviar FCM: ${message}`);
      return { outcome: PushSendOutcome.FAILED, error: code ?? message };
    }
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Prisma } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { DecimalInput, normalizeDecimal } from '@common/helpers/decimal.helper';

export interface FeeConfig {
  /** Porcentaje sobre el monto (2.5 = 2.5%). */
  percentage: number;
  /** Comisión mínima: nunca se cobra menos que esto. */
  minimum: number;
}

/**
 * Función pura: fee = max(monto * porcentaje / 100, mínimo), redondeado a 2 decimales.
 * Sin I/O ni config global, por eso es trivial de testear.
 */
export function calculateFee(
  amount: DecimalInput,
  config: FeeConfig,
): Prisma.Decimal {
  const percentageFee = normalizeDecimal(amount)
    .mul(new Prisma.Decimal(config.percentage))
    .div(100);
  const minimum = new Prisma.Decimal(config.minimum);
  return normalizeDecimal(Prisma.Decimal.max(percentageFee, minimum));
}

/** Adapter inyectable que alimenta `calculateFee` con la configuración de la app. */
@Injectable()
export class FeeCalculator {
  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  calculate(amount: DecimalInput): Prisma.Decimal {
    return calculateFee(amount, {
      percentage: this.config.orders.feePercentage,
      minimum: this.config.orders.feeMinimum,
    });
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  InternalServerErrorException,
  StreamableFile,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Response } from 'express';
import { Buffer } from 'buffer';
import { Readable } from 'stream';
import { DOWNLOAD_FILE_KEY } from '@common/decorators/file-download.decorator';

export type ExportFormat = 'xlsx' | 'pdf' | 'csv';

export interface IDownloadResponse {
  buffer: Buffer;
  filename: string;
  format: ExportFormat;
}

@Injectable()
export class FileDownloadInterceptor implements NestInterceptor {
  private readonly mimeTypes: Record<ExportFormat, string> = {
    pdf: 'application/pdf',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    csv: 'text/csv',
  };

  constructor(private readonly reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const isDownload = this.reflector.get<boolean>(
      DOWNLOAD_FILE_KEY,
      context.getHandler(),
    );

    if (!isDownload) {
      return next.handle();
    }

    const ctx = context.switchToHttp();
    const response = ctx.getResponse<Response>();

    return next.handle().pipe(
      map((data: IDownloadResponse) => {
        if (!data || !data.buffer || !data.filename || !data.format) {
          throw new InternalServerErrorException(
            'El servicio no retornó la estructura requerida para descargas (buffer, filename, format).',
          );
        }

        const contentType =
          this.mimeTypes[data.format] || 'application/octet-stream';

        response.set({
          'Content-Disposition': `attachment; filename="${data.filename}"`,
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          Pragma: 'no-cache',
          Expires: '0',
        });

        return new StreamableFile(Readable.from(data.buffer), {
          type: contentType,
          length: data.buffer.length,
        });
      }),
    );
  }
}

import {
  BadRequestException,
  CallHandler,
  ConflictException,
  ExecutionContext,
  Inject,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Reflector } from '@nestjs/core';
import type { Request, Response } from 'express';
import { catchError, from, mergeMap, Observable, of, throwError } from 'rxjs';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { IdempotencyService } from '../services/idempotency.service';
import {
  computeRequestHash,
  readIdempotencyKey,
} from '../helpers/idempotency.helper';
import { IDEMPOTENT_KEY, IdempotentOptions } from '../idempotency.types';
import { t } from '@common/i18n/i18n.helper';

export const IDEMPOTENT_REPLAYED_HEADER = 'Idempotent-Replayed';

/**
 * Patrón: interceptor opt-in (`@Idempotent()`). NEW ejecuta el handler y guarda la respuesta;
 * REPLAY devuelve la guardada sin ejecutar nada; CONFLICT / IN_PROGRESS responden 409.
 */
@Injectable()
export class IdempotencyInterceptor implements NestInterceptor {
  constructor(
    private readonly reflector: Reflector,
    private readonly idempotencyService: IdempotencyService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const options = this.reflector.get<IdempotentOptions | undefined>(
      IDEMPOTENT_KEY,
      context.getHandler(),
    );
    if (!options) return next.handle();

    const http = context.switchToHttp();
    const req = http.getRequest<
      Request & { user?: { id?: number | string } }
    >();
    const res = http.getResponse<Response>();

    const key = readIdempotencyKey(req.headers);
    if (!key) {
      if (options.required === false) return next.handle();
      throw new BadRequestException(t('errors.IDEMPOTENCY_KEY_REQUIRED'));
    }

    const routePath =
      (req.route as { path?: string } | undefined)?.path ?? req.path;
    const scope =
      options.scope ??
      `${req.method}:${routePath}:${req.user?.id ?? 'anonymous'}`;
    const requestHash = computeRequestHash(
      { body: req.body, query: req.query, params: req.params },
      this.config.security.hmacSecret || undefined,
    );

    return from(
      this.idempotencyService.resolve({ key, scope, requestHash }),
    ).pipe(
      mergeMap((resolution) => {
        switch (resolution.action) {
          case 'REPLAY':
            res.status(resolution.responseCode);
            res.setHeader(IDEMPOTENT_REPLAYED_HEADER, 'true');
            return of(resolution.responseBody);
          case 'CONFLICT':
            return throwError(
              () => new ConflictException(t('errors.IDEMPOTENCY_KEY_REUSED')),
            );
          case 'IN_PROGRESS':
            return throwError(
              () => new ConflictException(t('errors.IDEMPOTENCY_IN_PROGRESS')),
            );
          case 'NEW':
            return next.handle().pipe(
              mergeMap((body: unknown) =>
                from(
                  this.idempotencyService.complete(
                    resolution.recordId,
                    res.statusCode,
                    body,
                  ),
                ).pipe(mergeMap(() => of(body))),
              ),
              catchError((error: unknown) =>
                from(this.idempotencyService.release(resolution.recordId)).pipe(
                  mergeMap(() => throwError(() => error)),
                ),
              ),
            );
        }
      }),
    );
  }
}

import { Injectable } from '@nestjs/common';
import { AdvisoryLockId } from '@core/scheduler/advisory-lock-id.enum';
import { ScheduledJob, SchedulerCronKey } from '@core/scheduler/scheduled-job';
import { IdempotencyService } from '../services/idempotency.service';

/** Purga de `IdempotencyRecord` vencidos. Una sola réplica por tick (advisory lock). */
@Injectable()
export class IdempotencyPurgeJob extends ScheduledJob {
  readonly name = 'idempotency-purge';
  readonly cronConfigKey: SchedulerCronKey = 'idempotencyPurge';
  readonly lockId = AdvisoryLockId.IdempotencyPurge;

  constructor(private readonly idempotency: IdempotencyService) {
    super();
  }

  async run(): Promise<void> {
    const purged = await this.idempotency.purgeExpired();
    this.logger.log(`Registros de idempotencia vencidos purgados: ${purged}`);
  }
}

import { ConflictException, Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { IdempotencyStatus, Prisma } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PrismaErrorCodes } from '@common/enum/prisma-error-codes.enum';
import { safeEqual } from '@common/helpers/crypto/hmac.helper';

export type IdempotencyResolution =
  | { action: 'NEW'; recordId: number }
  | { action: 'REPLAY'; responseCode: number; responseBody: unknown }
  | { action: 'CONFLICT' } // misma key, otro payload -> 409
  | { action: 'IN_PROGRESS' }; // misma key en curso -> 409

export interface ResolveInput {
  key: string;
  scope: string;
  requestHash: string;
}

// Un IN_PROGRESS más viejo que esto se considera huérfano (el proceso murió) y se retoma.
const STALE_IN_PROGRESS_MS = 5 * 60_000;

/**
 * Patrón: Idempotency Key respaldada en DB. La unicidad (scope, key) es el árbitro de la
 * carrera entre requests concurrentes (INSERT atómico), no un "check then insert".
 * Usa el cliente Prisma sin extensión de auditoría: son datos técnicos, no de negocio.
 */
@Injectable()
export class IdempotencyService {
  constructor(
    private readonly prisma: PrismaDatasource,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async resolve(input: ResolveInput): Promise<IdempotencyResolution> {
    for (let attempt = 0; attempt < 3; attempt++) {
      const now = new Date();
      try {
        const created = await this.prisma.idempotencyRecord.create({
          data: {
            key: input.key,
            scope: input.scope,
            requestHash: input.requestHash,
            expiresAt: new Date(
              now.getTime() + this.config.idempotency.ttlHours * 3_600_000,
            ),
          },
        });
        return { action: 'NEW', recordId: created.id };
      } catch (error) {
        if (!this.isUniqueViolation(error)) throw error;
      }

      const existing = await this.prisma.idempotencyRecord.findUnique({
        where: { scope_key: { scope: input.scope, key: input.key } },
      });
      if (!existing) continue; // se purgó entre medio: reintentar el INSERT

      if (existing.expiresAt <= now) {
        await this.prisma.idempotencyRecord.deleteMany({
          where: { id: existing.id, expiresAt: { lte: now } },
        });
        continue;
      }

      if (!safeEqual(existing.requestHash, input.requestHash)) {
        return { action: 'CONFLICT' };
      }

      if (existing.status === IdempotencyStatus.COMPLETED) {
        return {
          action: 'REPLAY',
          responseCode: existing.responseCode ?? 200,
          responseBody: existing.responseBody,
        };
      }

      // IN_PROGRESS: ¿vigente o huérfano? El updateMany condicional garantiza un único ganador.
      const takeover = await this.prisma.idempotencyRecord.updateMany({
        where: {
          id: existing.id,
          status: IdempotencyStatus.IN_PROGRESS,
          updatedAt: { lt: new Date(now.getTime() - STALE_IN_PROGRESS_MS) },
        },
        data: { updatedAt: now },
      });
      return takeover.count === 1
        ? { action: 'NEW', recordId: existing.id }
        : { action: 'IN_PROGRESS' };
    }

    throw new ConflictException(
      'No se pudo resolver la Idempotency-Key, reintente.',
    );
  }

  async complete(
    recordId: number,
    responseCode: number,
    responseBody: unknown,
  ): Promise<void> {
    // Round-trip JSON: guarda exactamente lo que el cliente recibió (Decimal/Date serializados).
    const body =
      responseBody === undefined
        ? Prisma.DbNull
        : (JSON.parse(JSON.stringify(responseBody)) as Prisma.InputJsonValue);

    await this.prisma.idempotencyRecord.update({
      where: { id: recordId },
      data: {
        status: IdempotencyStatus.COMPLETED,
        responseCode,
        responseBody: body,
      },
    });
  }

  /** Libera la clave tras un error para permitir reintento (los errores no se cachean). */
  async release(recordId: number): Promise<void> {
    await this.prisma.idempotencyRecord.deleteMany({
      where: { id: recordId, status: IdempotencyStatus.IN_PROGRESS },
    });
  }

  /** Limpieza de registros vencidos (invocar desde un job/cron externo). */
  async purgeExpired(now: Date = new Date()): Promise<number> {
    const { count } = await this.prisma.idempotencyRecord.deleteMany({
      where: { expiresAt: { lte: now } },
    });
    return count;
  }

  private isUniqueViolation(error: unknown): boolean {
    return (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === (PrismaErrorCodes.UniqueConstraintFailed as string)
    );
  }
}

import { BadRequestException, Inject, Injectable } from '@nestjs/common';
import { IJobHandler, JOB_HANDLERS } from '../interfaces/job-handler.interface';

/** Resuelve el handler de cada `type` de job. Indexa una sola vez los handlers inyectados. */
@Injectable()
export class JobHandlerRegistry {
  private readonly handlers = new Map<string, IJobHandler>();

  constructor(@Inject(JOB_HANDLERS) handlers: IJobHandler[]) {
    for (const handler of handlers) {
      if (this.handlers.has(handler.type)) {
        throw new Error(
          `Handler de job duplicado para el type "${handler.type}"`,
        );
      }
      this.handlers.set(handler.type, handler);
    }
  }

  find(type: string): IJobHandler | undefined {
    return this.handlers.get(type);
  }

  /** Lanza BadRequest si no hay handler para `type`. */
  resolve(type: string): IJobHandler {
    const handler = this.handlers.get(type);
    if (!handler) {
      throw new BadRequestException(
        `Tipo de job desconocido "${type}". Disponibles: ${this.getTypes().join(', ')}`,
      );
    }
    return handler;
  }

  /** Types que este proceso sabe ejecutar: el worker solo toma jobs de estos types. */
  getTypes(): string[] {
    return [...this.handlers.keys()];
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { BackgroundJobsDBService } from '@modules/jobs-db/services/background-jobs-db.service';
import { JobHandlerRegistry } from '@modules/jobs/services/job-handler.registry';
import { EnqueueJobRequestDTO } from '../dtos/enqueue-job.request.dto';
import { JobResponseDTO } from '../dtos/job.response.dto';

/** Capa API: valida el type/payload contra el handler y delega la cola en `jobs-db`. */
@Injectable()
export class JobsApiService {
  constructor(
    private readonly jobs: BackgroundJobsDBService,
    private readonly registry: JobHandlerRegistry,
  ) {}

  listTypes(): { types: string[] } {
    return { types: this.registry.getTypes() };
  }

  async enqueue(
    dto: EnqueueJobRequestDTO,
    userId: number,
  ): Promise<JobResponseDTO> {
    const handler = this.registry.resolve(dto.type);
    handler.validatePayload?.(dto.payload ?? {});

    const job = await this.jobs.enqueue({
      type: dto.type,
      payload: (dto.payload ?? {}) as Prisma.InputJsonObject,
      maxAttempts: dto.maxAttempts,
      createdBy: userId,
    });
    return JobResponseDTO.fromEntity(job);
  }

  async findOne(referenceId: string): Promise<JobResponseDTO> {
    const job = await this.jobs.findByReference(referenceId);
    if (!job) throw new NotFoundException('Job no encontrado.');
    return JobResponseDTO.fromEntity(job);
  }

  async requeue(referenceId: string): Promise<JobResponseDTO> {
    const requeued = await this.jobs.requeue(referenceId);
    if (!requeued) {
      await this.findOne(referenceId); // 404 si no existe
      throw new ConflictException('Solo se pueden reencolar jobs en FAILED.');
    }
    return this.findOne(referenceId);
  }
}

import {
  Inject,
  Injectable,
  Logger,
  OnApplicationBootstrap,
  OnApplicationShutdown,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { DiscoveryService } from '@nestjs/core';
import { SchedulerRegistry } from '@nestjs/schedule';
import { CronJob } from 'cron';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { ScheduledJob } from './scheduled-job';

export const CRON_OFF = 'off';

/**
 * Patrón: registro dinámico (Registry + Discovery). El decorador `@Cron` evalúa su expresión al
 * cargar la clase, antes de que exista la config; acá se descubren todos los `ScheduledJob` ya
 * instanciados y se registran con `CronJob.from` leyendo el cron de la config (env por job).
 * Agregar un job = crear la clase y listarla como provider: no se toca este servicio (OCP).
 */
@Injectable()
export class JobSchedulerService
  implements OnApplicationBootstrap, OnApplicationShutdown
{
  private readonly logger = new Logger(JobSchedulerService.name);

  constructor(
    private readonly discovery: DiscoveryService,
    private readonly registry: SchedulerRegistry,
    private readonly prisma: PrismaDatasource,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  onApplicationBootstrap(): void {
    if (!this.config.scheduler.enabled) {
      this.logger.log('Scheduler deshabilitado (SCHEDULER_ENABLED=false)');
      return;
    }

    for (const wrapper of this.discovery.getProviders()) {
      const instance: unknown = wrapper.instance;
      if (instance instanceof ScheduledJob) {
        this.register(instance);
      }
    }
  }

  onApplicationShutdown(): void {
    for (const name of this.registry.getCronJobs().keys()) {
      this.registry.deleteCronJob(name);
    }
  }

  private register(job: ScheduledJob): void {
    if (!job.isEnabled()) {
      this.logger.log(`Job "${job.name}" deshabilitado por su feature`);
      return;
    }

    const expression = this.config.scheduler.crons[job.cronConfigKey];

    if (!expression || expression.toLowerCase() === CRON_OFF) {
      this.logger.log(`Job "${job.name}" deshabilitado por configuración`);
      return;
    }

    try {
      const cronJob = CronJob.from({
        cronTime: expression,
        onTick: () => void job.execute(this.prisma),
        start: true,
        timeZone: this.config.scheduler.timezone,
      });
      this.registry.addCronJob(job.name, cronJob);
      this.logger.log(`Job "${job.name}" registrado (${expression})`);
    } catch (error) {
      // Un cron inválido no debe impedir el arranque: se loguea y el job queda sin registrar.
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(
        `Job "${job.name}" no registrado, cron inválido "${expression}" | ${message}`,
      );
    }
  }
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
  StreamableFile,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Readable } from 'stream';
import { JSON_STREAM_KEY } from '@common/decorators/json-stream.constants';
import {
  IJsonStreamDocument,
  JsonStreamHelper,
} from '@common/helpers/json-stream.helper';

/**
 * Patrón: Decorator/Interceptor. Transmite como JSON chunked (`Transfer-Encoding: chunked`, sin
 * `Content-Length`) el valor de un handler marcado con `@JsonStream()` cuando tiene la forma de
 * un `IJsonStreamDocument`; cualquier otro valor pasa intacto (mismo criterio defensivo que
 * `FileDownloadInterceptor`), así un handler puede mezclar ramas en streaming y no streaming.
 */
@Injectable()
export class JsonStreamInterceptor implements NestInterceptor {
  constructor(private readonly reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const shouldStream = this.reflector.get<boolean | undefined>(
      JSON_STREAM_KEY,
      context.getHandler(),
    );

    if (!shouldStream) {
      return next.handle();
    }

    return next.handle().pipe(
      map((data: unknown) => {
        if (!JsonStreamInterceptor.isStreamDocument(data)) {
          return data;
        }

        return new StreamableFile(
          Readable.from(JsonStreamHelper.stream(data), { objectMode: false }),
          { type: 'application/json' },
        );
      }),
    );
  }

  /**
   * Determina si el valor resuelto por el handler es realmente un
   * `IJsonStreamDocument` (tiene `arrayKey`/`items`), en vez de asumirlo solo
   * por la presencia del metadata del decorador.
   * @param value Valor resuelto por el handler
   * @returns `true` si `value` tiene la forma de `IJsonStreamDocument`
   */
  private static isStreamDocument(
    value: unknown,
  ): value is IJsonStreamDocument<unknown, unknown> {
    return (
      !!value &&
      typeof value === 'object' &&
      'arrayKey' in value &&
      'items' in value
    );
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { TokenExpiredError } from 'jsonwebtoken';
import { UserWithSecurities } from '../types/user.types';
import { t } from '@common/i18n/i18n.helper';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  handleRequest<TUser = UserWithSecurities>(
    err: unknown,
    user: unknown,
    info: unknown,
  ): TUser {
    // Token expirado
    if (info instanceof TokenExpiredError) {
      throw new UnauthorizedException({
        statusCode: 401,
        message: t('auth.TOKEN_EXPIRED'),
        error: 'Unauthorized',
        code: 'TOKEN_EXPIRED',
      });
    }

    // Token inválido / usuario inexistente
    if (err || !user) {
      throw new UnauthorizedException({
        statusCode: 401,
        message: t('auth.INVALID_TOKEN'),
        error: 'Unauthorized',
        code: 'INVALID_TOKEN',
      });
    }

    return user as TUser;
  }
}

import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-jwt';
import { Request } from 'express';
import { ConfigType } from '@nestjs/config';

import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { IJwtPayload } from '@common/interfaces/jwt-payload.interface';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { UserWithSecurities } from '@modules/auth/types/user.types';

@Injectable()
export class JwtRefreshStrategy extends PassportStrategy(
  Strategy,
  'jwt-refresh',
) {
  constructor(
    private readonly usersService: UsersDBService,
    @Inject(APP_CONFIG.KEY)
    readonly configService: ConfigType<AppConfigType>,
  ) {
    super({
      jwtFromRequest: (req: Request): string | null => {
        const token = req.cookies?.['refreshToken'];
        return typeof token === 'string' ? token : null;
      },
      passReqToCallback: false,
      ignoreExpiration: false,
      secretOrKey: configService.authentication.publicKey,
    });
  }

  async validate(payload: IJwtPayload): Promise<UserWithSecurities> {
    const user = await this.usersService.findActiveUserByEmail(payload.email);

    if (!user) {
      throw new UnauthorizedException('Usuario no encontrado o inactivo.');
    }

    return user;
  }
}

import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { ConfigType } from '@nestjs/config';
import { IJwtPayload } from '@common/interfaces/jwt-payload.interface';
import { UserWithSecuritiesExtended } from '../types/user.types';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { IUserDataOnJwt } from '../interfaces/user-data-on-jwt.interface';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy, 'jwt') {
  constructor(
    private readonly usersService: UsersDBService,
    private readonly permissionsCache: PermissionsCacheService,
    @Inject(APP_CONFIG.KEY)
    private readonly configService: ConfigType<AppConfigType>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.authentication.publicKey,
    });
  }

  /**
   * Resuelve usuario + roles + permisos con cache-aside por `sub` (referenceId). Se invalida
   * entero ante cambios de roles/permisos/estado (ver PermissionsCacheService).
   */
  async validate(payload: IJwtPayload): Promise<IUserDataOnJwt> {
    return await this.permissionsCache.getOrLoad(payload.sub, () =>
      this.resolveUser(payload),
    );
  }

  private async resolveUser(payload: IJwtPayload): Promise<IUserDataOnJwt> {
    const user: UserWithSecuritiesExtended | null =
      await this.usersService.findActiveUserByEmailWithPermissions(
        payload.email,
      );

    if (!user) {
      throw new UnauthorizedException();
    }

    const directPermissions = user.permissions
      .map((p) => p.permission?.name)
      .filter(Boolean);

    const rolePermissions = user.roles
      .flatMap(
        (ur) =>
          ur.role?.rolePermissions?.map((rp) => rp.permission?.name) || [],
      )
      .filter(Boolean);

    const permissions = [
      ...new Set([...directPermissions, ...rolePermissions]),
    ];

    return {
      id: user.id,
      referenceId: user.referenceId,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      currentAccessLevel: user.currentAccessLevel,
      userStatus: user.status,
      profileStatus: user.profileStatus,
      permissions: permissions,
      roles: user.roles.map((ur) => ur.role?.name).filter(Boolean),
    };
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { LegalDocumentType } from '@prisma/client';
import { t } from '@common/i18n/i18n.helper';
import type { ICallerContext } from '@common/interfaces/caller-context.interface';
import { DataRetentionDBService } from '@modules/legal-db/services/data-retention-db.service';
import { LegalDocumentsDBService } from '@modules/legal-db/services/legal-documents-db.service';
import { UserConsentsDBService } from '@modules/legal-db/services/user-consents-db.service';
import {
  LegalDocumentResponseDTO,
  PublishLegalVersionRequestDTO,
  RetentionPolicyResponseDTO,
  UpsertRetentionPolicyRequestDTO,
  UserConsentResponseDTO,
} from '../dtos/legal.dto';

/** Capa API: orquesta DTO <-> dominio de cumplimiento (documentos, consentimientos, retención). */
@Injectable()
export class LegalApiService {
  constructor(
    private readonly documents: LegalDocumentsDBService,
    private readonly consents: UserConsentsDBService,
    private readonly retention: DataRetentionDBService,
  ) {}

  async listActive(): Promise<LegalDocumentResponseDTO[]> {
    return (await this.documents.listActive()).map((d) =>
      LegalDocumentResponseDTO.fromEntity(d),
    );
  }

  async listVersions(
    type?: LegalDocumentType,
  ): Promise<LegalDocumentResponseDTO[]> {
    return (await this.documents.listVersions(type)).map((d) =>
      LegalDocumentResponseDTO.fromEntity(d),
    );
  }

  async publish(
    dto: PublishLegalVersionRequestDTO,
    actor: string,
  ): Promise<LegalDocumentResponseDTO> {
    if (!dto.content && !dto.contentUrl) {
      throw new BadRequestException(t('legal.CONTENT_REQUIRED'));
    }
    return LegalDocumentResponseDTO.fromEntity(
      await this.documents.publish({ ...dto, actor }),
    );
  }

  async accept(
    userId: number,
    documentVersionId: string,
    caller: ICallerContext,
  ): Promise<UserConsentResponseDTO> {
    const version =
      await this.documents.findByReferenceOrFail(documentVersionId);
    return UserConsentResponseDTO.fromEntity(
      await this.consents.accept({
        userId,
        version,
        ipAddress: caller.ip,
        userAgent: caller.userAgent,
      }),
    );
  }

  async revoke(userId: number, type: LegalDocumentType): Promise<void> {
    await this.consents.revoke(userId, type);
  }

  async listMine(userId: number): Promise<UserConsentResponseDTO[]> {
    return (await this.consents.listByUser(userId)).map((c) =>
      UserConsentResponseDTO.fromEntity(c),
    );
  }

  async listPolicies(): Promise<RetentionPolicyResponseDTO[]> {
    return (await this.retention.list()).map((p) =>
      RetentionPolicyResponseDTO.fromEntity(p),
    );
  }

  async upsertPolicy(
    dto: UpsertRetentionPolicyRequestDTO,
    actor: string,
  ): Promise<RetentionPolicyResponseDTO> {
    return RetentionPolicyResponseDTO.fromEntity(
      await this.retention.upsert({ ...dto, actor }),
    );
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import {
  LegalDocumentType,
  LegalDocumentVersion,
  Prisma,
} from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { t } from '@common/i18n/i18n.helper';

export interface IPublishVersion {
  type: LegalDocumentType;
  version: string;
  title?: string;
  content?: string;
  contentUrl?: string;
  activate: boolean;
  actor: string;
}

/**
 * Repositorio de documentos legales versionados. Invariante: a lo sumo UNA versión activa por tipo
 * (índice único parcial en la migración); publicar = desactivar la anterior + crear la nueva en
 * una sola transacción, así nunca hay un instante sin versión vigente ni dos a la vez.
 */
@Injectable()
export class LegalDocumentsDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  listActive(): Promise<LegalDocumentVersion[]> {
    return this.prisma.legalDocumentVersion.findMany({
      where: { isActive: true },
      orderBy: { type: 'asc' },
    });
  }

  listVersions(type?: LegalDocumentType): Promise<LegalDocumentVersion[]> {
    return this.prisma.legalDocumentVersion.findMany({
      where: { type },
      orderBy: [{ type: 'asc' }, { publishedAt: 'desc' }],
    });
  }

  async findByReferenceOrFail(
    referenceId: string,
  ): Promise<LegalDocumentVersion> {
    const found = await this.prisma.legalDocumentVersion.findUnique({
      where: { referenceId },
    });
    if (!found) throw new NotFoundException(t('legal.VERSION_NOT_FOUND'));
    return found;
  }

  async publish(input: IPublishVersion): Promise<LegalDocumentVersion> {
    try {
      return await this.prisma.extended.$transaction(async (tx) => {
        if (input.activate) {
          await tx.legalDocumentVersion.updateMany({
            where: { type: input.type, isActive: true },
            data: { isActive: false, lastChangedBy: input.actor },
          });
        }
        return await tx.legalDocumentVersion.create({
          data: {
            type: input.type,
            version: input.version,
            title: input.title,
            content: input.content,
            contentUrl: input.contentUrl,
            isActive: input.activate,
            createdBy: input.actor,
          },
        });
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new ConflictException(t('legal.VERSION_DUPLICATED'));
      }
      throw error;
    }
  }
}

import {
  Inject,
  Injectable,
  Logger,
  ServiceUnavailableException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { MessageContentPolicy } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  decryptAesGcm,
  encryptAesGcm,
  Keyring,
  parseKeyring,
} from '@common/helpers/crypto/aes-gcm.helper';
import {
  hmacSha256Hex,
  verifyHmacSha256,
} from '@common/helpers/crypto/hmac.helper';
import type { IProtectedContent } from '../interfaces/message.interface';

const DAY_MS = 86_400_000;

/**
 * Patrón: política de contenido por mensaje. El ledger guarda SIEMPRE una huella HMAC del contenido
 * (permite verificar sin conservarlo) y, solo con política AUDIT, el contenido cifrado con
 * AES-256-GCM (keyring con rotación) y una fecha de expiración. Si AUDIT se pide pero no hay claves
 * de cifrado configuradas, se degrada a NONE con aviso: nunca se guarda contenido en claro.
 */
@Injectable()
export class MessageContentService {
  private readonly logger = new Logger(MessageContentService.name);
  private readonly keyring: Keyring;
  private readonly activeKeyId: string;
  private readonly hmacSecret: string;

  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {
    const { encryptionKeys, encryptionActiveKeyId, hmacSecret } =
      config.security;
    let keyring: Keyring = new Map();
    try {
      keyring = parseKeyring(encryptionKeys);
    } catch (error) {
      this.logger.warn(
        `ENCRYPTION_KEYS inválido, el cifrado de contenido queda deshabilitado: ${error instanceof Error ? error.message : 'error'}`,
      );
    }
    this.keyring = keyring;
    this.activeKeyId = encryptionActiveKeyId;
    this.hmacSecret = hmacSecret;
  }

  get canEncrypt(): boolean {
    return this.keyring.has(this.activeKeyId);
  }

  get canHmac(): boolean {
    return this.hmacSecret.length > 0;
  }

  resolvePolicy(requested?: MessageContentPolicy): MessageContentPolicy {
    const policy = requested ?? this.config.messages.contentPolicy;
    if (policy === MessageContentPolicy.AUDIT && !this.canEncrypt) {
      this.logger.warn(
        'Política AUDIT sin ENCRYPTION_KEYS/ENCRYPTION_ACTIVE_KEY_ID válidos: se guarda sin contenido (NONE)',
      );
      return MessageContentPolicy.NONE;
    }
    return policy;
  }

  protect(
    content: string | undefined,
    requested?: MessageContentPolicy,
  ): IProtectedContent {
    const contentPolicy = this.resolvePolicy(requested);
    const none: IProtectedContent = {
      contentPolicy,
      contentEncrypted: null,
      contentHmac: null,
      contentExpiresAt: null,
    };
    if (content === undefined) return none;

    const contentHmac = this.canHmac
      ? hmacSha256Hex(content, this.hmacSecret)
      : null;
    if (contentPolicy !== MessageContentPolicy.AUDIT) {
      return { ...none, contentHmac };
    }

    return {
      contentPolicy,
      contentEncrypted: encryptAesGcm(content, this.keyring, this.activeKeyId),
      contentHmac,
      contentExpiresAt: new Date(
        Date.now() + this.config.messages.contentRetentionDays * DAY_MS,
      ),
    };
  }

  reveal(encrypted: string): string {
    return decryptAesGcm(encrypted, this.keyring);
  }

  /** Compara el HMAC del contenido dado con el guardado, sin revelar el contenido original. */
  verify(content: string, expectedHmac: string): boolean {
    if (!this.canHmac) {
      throw new ServiceUnavailableException(
        'HMAC_SECRET no configurado: no se puede verificar contenido.',
      );
    }
    return verifyHmacSha256(content, this.hmacSecret, expectedHmac);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { Message, MessageStatus, Prisma } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { MessageContentService } from './message-content.service';
import type {
  ICreatePendingMessage,
  IMessageListFilters,
} from '../interfaces/message.interface';

/** Los SMS aceptados se siguen consultando hasta esta antigüedad; después se consideran perdidos. */
const DELIVERY_WINDOW_MS = 72 * 3_600_000;

/**
 * Ledger de mensajes. Regla clave: se inserta PENDING ANTES de llamar al proveedor, así un crash
 * entre ambos pasos deja evidencia del intento en vez de un envío sin rastro.
 * Estados: PENDING -> ACCEPTED -> DELIVERED | UNDELIVERED | EXPIRED, o PENDING -> REJECTED |
 * UNAVAILABLE. Los estados de entrega solo se aplican sobre ACCEPTED (nunca pisan uno final).
 */
@Injectable()
export class MessageDBService {
  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly content: MessageContentService,
  ) {}

  createPending(input: ICreatePendingMessage): Promise<Message> {
    const protectedContent = this.content.protect(
      input.content,
      input.contentPolicy,
    );
    return this.prisma.message.create({
      data: {
        channel: input.channel,
        provider: input.provider,
        recipient: input.recipient,
        status: MessageStatus.PENDING,
        traceId: input.caller?.traceId,
        callerIp: input.caller?.ip,
        callerUserAgent: input.caller?.userAgent,
        sourceService: input.caller?.sourceService,
        createdBy: input.createdBy,
        idempotencyKey: input.idempotencyKey,
        resentFromId: input.resentFromId,
        ...protectedContent,
      },
    });
  }

  markAccepted(
    id: number,
    result: { providerMessageId?: string; providerStatus?: string },
  ): Promise<Message> {
    return this.prisma.message.update({
      where: { id },
      data: {
        status: MessageStatus.ACCEPTED,
        providerMessageId: result.providerMessageId,
        providerStatus: result.providerStatus,
        attempts: { increment: 1 },
        nextAttemptAt: null,
      },
    });
  }

  markFailed(
    id: number,
    status: 'REJECTED' | 'UNAVAILABLE',
    detail: { errorCode?: string; nextAttemptAt?: Date } = {},
  ): Promise<Message> {
    return this.prisma.message.update({
      where: { id },
      data: {
        status,
        providerErrorCode: detail.errorCode?.slice(0, 128),
        attempts: { increment: 1 },
        nextAttemptAt: detail.nextAttemptAt ?? null,
      },
    });
  }

  /**
   * Aplica un estado de entrega por `providerMessageId`. Update condicional: solo si el mensaje
   * sigue ACCEPTED, así un reporte tardío o repetido no pisa un estado final.
   * @returns cantidad de filas actualizadas (0 = sin fila o ya final)
   */
  async applyDeliveryStatus(
    providerMessageId: string,
    status: MessageStatus,
    providerStatus: string,
    errorCode?: string,
  ): Promise<number> {
    const { count } = await this.prisma.message.updateMany({
      where: { providerMessageId, status: MessageStatus.ACCEPTED },
      data: {
        status,
        providerStatus: providerStatus.slice(0, 64),
        providerErrorCode: errorCode?.slice(0, 128),
      },
    });
    return count;
  }

  findSmsAwaitingDelivery(limit: number, now = new Date()): Promise<Message[]> {
    return this.prisma.message.findMany({
      where: {
        channel: 'SMS',
        status: MessageStatus.ACCEPTED,
        providerMessageId: { not: null },
        createdAt: { gte: new Date(now.getTime() - DELIVERY_WINDOW_MS) },
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });
  }

  findByReference(referenceId: string): Promise<Message | null> {
    return this.prisma.message.findUnique({ where: { referenceId } });
  }

  async findByReferenceOrFail(referenceId: string): Promise<Message> {
    const message = await this.findByReference(referenceId);
    if (!message) throw new NotFoundException('Mensaje no encontrado.');
    return message;
  }

  async list(
    filters: IMessageListFilters,
  ): Promise<{ items: Message[]; total: number }> {
    const where: Prisma.MessageWhereInput = {
      channel: filters.channel,
      status: filters.status,
      provider: filters.provider,
      createdAt:
        filters.from || filters.to
          ? { gte: filters.from, lte: filters.to }
          : undefined,
    };
    const [items, total] = await this.prisma.$transaction([
      this.prisma.message.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (filters.page - 1) * filters.pageSize,
        take: filters.pageSize,
      }),
      this.prisma.message.count({ where }),
    ]);
    return { items, total };
  }

  /** Descifra el contenido AUDIT. 404 si no hay contenido (política NONE o ya purgado). */
  revealContent(message: Message): string {
    if (!message.contentEncrypted) {
      throw new NotFoundException(
        'El contenido no está disponible (política NONE o vencido).',
      );
    }
    return this.content.reveal(message.contentEncrypted);
  }

  /** Verifica `content` contra la huella guardada sin revelar el original. */
  verifyContent(message: Message, content: string): boolean {
    if (!message.contentHmac) {
      throw new NotFoundException('El mensaje no tiene huella de contenido.');
    }
    return this.content.verify(content, message.contentHmac);
  }

  /** Anula el contenido cifrado AUDIT vencido (un lote). La fila y su huella HMAC se conservan. */
  async purgeExpiredContent(
    batchSize: number,
    now = new Date(),
  ): Promise<number> {
    const rows = await this.prisma.message.findMany({
      where: {
        contentEncrypted: { not: null },
        contentExpiresAt: { lt: now },
      },
      select: { id: true },
      take: batchSize,
    });
    if (rows.length === 0) return 0;

    const { count } = await this.prisma.message.updateMany({
      where: { id: { in: rows.map((row) => row.id) } },
      data: { contentEncrypted: null },
    });
    return count;
  }

  /** Borra filas más viejas que `olderThan` (un lote). `resentFromId` queda en NULL por la FK. */
  async deleteOlderThan(olderThan: Date, batchSize: number): Promise<number> {
    const rows = await this.prisma.message.findMany({
      where: { createdAt: { lt: olderThan } },
      select: { id: true },
      take: batchSize,
    });
    if (rows.length === 0) return 0;

    const { count } = await this.prisma.message.deleteMany({
      where: { id: { in: rows.map((row) => row.id) } },
    });
    return count;
  }
}

import {
  BadRequestException,
  Inject,
  Injectable,
  Logger,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Message } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  ProviderRejectedError,
  ProviderUnavailableError,
} from '@common/errors/provider.errors';
import { PhoneHelper } from '@common/helpers/phone.helper';
import type { ICallerContext } from '@common/interfaces/caller-context.interface';
import {
  EMAIL_SENDER,
  IEmailSender,
} from '@modules/email/interfaces/email-sender.interface';
import { RecipientHelper } from '@modules/email/helpers/recipient.helper';
import { MessageDBService } from '@modules/message-db/services/message-db.service';
import {
  ISmsSender,
  SMS_SENDER,
} from '@modules/sms/interfaces/sms-sender.interface';

export interface IDispatchContext {
  caller?: ICallerContext;
  userId?: number;
  idempotencyKey?: string;
}

export interface IEmailDispatch {
  to: string[];
  cc?: string[];
  bcc?: string[];
  subject: string;
  html: string;
  text?: string;
}

/** Espera sugerida antes de reintentar un envío con falla transitoria (columna `nextAttemptAt`). */
const RETRY_HINT_MS = 60_000;

/**
 * Patrón: Template de envío con ledger. Cada envío sigue los mismos pasos, sin importar canal ni
 * proveedor: (1) escribir PENDING, (2) llamar al sender, (3) registrar el resultado. Los errores
 * tipados del proveedor NO se relanzan: quedan reflejados en el estado del mensaje devuelto
 * (REJECTED / UNAVAILABLE) para que la capa API los traduzca a 502/503 con la referencia del ledger.
 * Un error propio (p. ej. la DB al escribir PENDING) sí se propaga y el proveedor ni se llama.
 */
@Injectable()
export class MessageDispatcherService {
  private readonly logger = new Logger(MessageDispatcherService.name);

  constructor(
    private readonly messages: MessageDBService,
    @Inject(SMS_SENDER) private readonly smsSender: ISmsSender,
    @Inject(EMAIL_SENDER) private readonly emailSender: IEmailSender,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async sendSms(
    input: { to: string; text: string },
    context: IDispatchContext = {},
  ): Promise<Message> {
    let phone: string;
    try {
      phone = PhoneHelper.normalize(
        input.to,
        this.config.sms.phoneDefaultCountryCode || undefined,
      );
    } catch {
      throw new BadRequestException('Teléfono inválido.');
    }

    const ledger = await this.messages.createPending({
      channel: 'SMS',
      provider: this.smsSender.provider,
      recipient: PhoneHelper.mask(phone),
      content: input.text,
      ...this.contextFields(context),
    });

    try {
      const result = await this.smsSender.send({ to: phone, text: input.text });
      return await this.messages.markAccepted(ledger.id, {
        providerMessageId: result.messageId,
        providerStatus: result.status,
      });
    } catch (error) {
      return await this.recordFailure(ledger, error);
    }
  }

  async sendEmail(
    input: IEmailDispatch,
    context: IDispatchContext = {},
  ): Promise<Message> {
    const recipients = RecipientHelper.normalize(input);
    if (RecipientHelper.exceedsMax(recipients)) {
      throw new BadRequestException('Demasiados destinatarios.');
    }

    const ledger = await this.messages.createPending({
      channel: 'EMAIL',
      provider: this.emailSender.provider,
      recipient: RecipientHelper.maskAll(recipients),
      content: `${input.subject}\n${input.html}`,
      ...this.contextFields(context),
    });

    try {
      const result = await this.emailSender.send({ ...input, ...recipients });
      return await this.messages.markAccepted(ledger.id, {
        providerMessageId: result.messageId,
        providerStatus: 'ACCEPTED',
      });
    } catch (error) {
      return await this.recordFailure(ledger, error);
    }
  }

  private contextFields(context: IDispatchContext) {
    return {
      caller: context.caller,
      createdBy: context.userId,
      idempotencyKey: context.idempotencyKey,
    };
  }

  private async recordFailure(
    ledger: Message,
    error: unknown,
  ): Promise<Message> {
    const rejected = error instanceof ProviderRejectedError;
    const transient = error instanceof ProviderUnavailableError;
    const code =
      rejected || transient
        ? (error.code ?? error.name)
        : 'UNEXPECTED_PROVIDER_ERROR';

    if (!rejected && !transient) {
      this.logger.error(
        `Error inesperado del proveedor (mensaje ${ledger.referenceId}): ${error instanceof Error ? error.message : String(error)}`,
      );
    }

    return await this.messages.markFailed(
      ledger.id,
      rejected ? 'REJECTED' : 'UNAVAILABLE',
      {
        errorCode: code,
        nextAttemptAt: rejected
          ? undefined
          : new Date(Date.now() + RETRY_HINT_MS),
      },
    );
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { AdvisoryLockId } from '@core/scheduler/advisory-lock-id.enum';
import { ScheduledJob, SchedulerCronKey } from '@core/scheduler/scheduled-job';
import { MessageDBService } from '../services/message-db.service';

const DAY_MS = 86_400_000;
/** Tope de lotes por tick: evita que una purga enorme monopolice el job. */
const MAX_BATCHES_PER_RUN = 50;

/**
 * Purga del ledger: (1) anula el contenido cifrado AUDIT vencido y (2) si `MESSAGE_RETENTION_DAYS`
 * > 0 borra filas más viejas. Procesa por lotes; una sola réplica por tick (advisory lock).
 */
@Injectable()
export class MessagePurgeJob extends ScheduledJob {
  readonly name = 'message-purge';
  readonly cronConfigKey: SchedulerCronKey = 'messagePurge';
  readonly lockId = AdvisoryLockId.MessagePurge;

  constructor(
    private readonly messages: MessageDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {
    super();
  }

  async run(): Promise<void> {
    const { purgeBatchSize, retentionDays } = this.config.messages;

    const contents = await this.drain(() =>
      this.messages.purgeExpiredContent(purgeBatchSize),
    );

    let rows = 0;
    if (retentionDays > 0) {
      const olderThan = new Date(Date.now() - retentionDays * DAY_MS);
      rows = await this.drain(() =>
        this.messages.deleteOlderThan(olderThan, purgeBatchSize),
      );
    }

    this.logger.log(
      `Purga de mensajes: contenidos anulados=${contents}, filas borradas=${rows}`,
    );
  }

  private async drain(batch: () => Promise<number>): Promise<number> {
    const size = this.config.messages.purgeBatchSize;
    let total = 0;
    for (let i = 0; i < MAX_BATCHES_PER_RUN; i++) {
      const count = await batch();
      total += count;
      if (count < size) break;
    }
    return total;
  }
}

import {
  BadGatewayException,
  Injectable,
  ServiceUnavailableException,
} from '@nestjs/common';
import { Message } from '@prisma/client';
import { MessageDBService } from '@modules/message-db/services/message-db.service';
import {
  IDispatchContext,
  MessageDispatcherService,
} from '@modules/messaging/services/message-dispatcher.service';
import { PaginationHelper } from '@common/helpers/pagination.helper';
import { ListMessagesRequestDTO } from '../dtos/list-messages.request.dto';
import {
  MessageContentResponseDTO,
  MessageResponseDTO,
  MessagesListResponseDTO,
  VerifyContentResponseDTO,
} from '../dtos/message.response.dto';
import { SendEmailRequestDTO } from '../dtos/send-email.request.dto';
import { SendSmsRequestDTO } from '../dtos/send-sms.request.dto';
import { VerifyContentRequestDTO } from '../dtos/verify-content.request.dto';

/**
 * Capa API: orquesta DTO <-> dominio y traduce el estado del ledger a HTTP.
 * REJECTED (el proveedor dijo que no) -> 502; UNAVAILABLE (transitorio) -> 503.
 */
@Injectable()
export class MessagesApiService {
  constructor(
    private readonly dispatcher: MessageDispatcherService,
    private readonly messages: MessageDBService,
  ) {}

  async sendSms(
    dto: SendSmsRequestDTO,
    context: IDispatchContext,
  ): Promise<MessageResponseDTO> {
    return this.toResponse(await this.dispatcher.sendSms(dto, context));
  }

  async sendEmail(
    dto: SendEmailRequestDTO,
    context: IDispatchContext,
  ): Promise<MessageResponseDTO> {
    return this.toResponse(await this.dispatcher.sendEmail(dto, context));
  }

  async list(query: ListMessagesRequestDTO): Promise<MessagesListResponseDTO> {
    const { items, total } = await this.messages.list(query);
    return PaginationHelper.create(
      items.map((m) => MessageResponseDTO.fromEntity(m)),
      total,
      query.page,
      query.pageSize,
    ) as MessagesListResponseDTO;
  }

  async findOne(referenceId: string): Promise<MessageResponseDTO> {
    return MessageResponseDTO.fromEntity(
      await this.messages.findByReferenceOrFail(referenceId),
    );
  }

  async getContent(referenceId: string): Promise<MessageContentResponseDTO> {
    const message = await this.messages.findByReferenceOrFail(referenceId);
    return { referenceId, content: this.messages.revealContent(message) };
  }

  async verifyContent(
    dto: VerifyContentRequestDTO,
  ): Promise<VerifyContentResponseDTO> {
    const message = await this.messages.findByReferenceOrFail(dto.referenceId);
    return { valid: this.messages.verifyContent(message, dto.content) };
  }

  private toResponse(message: Message): MessageResponseDTO {
    const body = {
      referenceId: message.referenceId,
      status: message.status,
    };
    if (message.status === 'REJECTED') {
      throw new BadGatewayException({
        message: 'El proveedor rechazó el envío.',
        ...body,
      });
    }
    if (message.status === 'UNAVAILABLE') {
      throw new ServiceUnavailableException({
        message: 'El proveedor no está disponible, reintente.',
        ...body,
      });
    }
    return MessageResponseDTO.fromEntity(message);
  }
}

import { Injectable } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { QueryFilter, Model } from 'mongoose';
import type {
  IActivityLogEntry,
  IActivityLogQuery,
  IActivityLogRecord,
  IActivityLogStore,
} from '../interfaces/activity-log-store.interface';
import { ActivityLog } from '../schemas/activity-log.schema';

/** Implementación Mongo del puerto: solo inserta y consulta (el borrado lo hace el índice TTL). */
@Injectable()
export class MongoActivityLogStore implements IActivityLogStore {
  readonly kind = 'mongo' as const;

  constructor(
    @InjectModel(ActivityLog.name)
    private readonly model: Model<ActivityLog>,
  ) {}

  async append(entry: IActivityLogEntry): Promise<void> {
    await this.model.create(entry);
  }

  async find(query: IActivityLogQuery): Promise<IActivityLogRecord[]> {
    const filter: QueryFilter<ActivityLog> = {};
    if (query.actorId !== undefined) filter.actorId = query.actorId;
    if (query.action) filter.action = query.action;
    if (query.entityType) filter.entityType = query.entityType;
    if (query.entityId) filter.entityId = query.entityId;
    if (query.from || query.to) {
      filter.createdAt = {
        ...(query.from && { $gte: query.from }),
        ...(query.to && { $lte: query.to }),
      };
    }

    const docs = await this.model
      .find(filter)
      .sort({ createdAt: -1 })
      .limit(query.limit)
      .lean()
      .exec();

    return docs.map((d) => ({
      id: String(d._id),
      actorId: d.actorId,
      action: d.action,
      entityType: d.entityType,
      entityId: d.entityId,
      metadata: d.metadata,
      traceId: d.traceId,
      createdAt: d.createdAt,
    }));
  }
}

import {
  Inject,
  Injectable,
  Logger,
  ServiceUnavailableException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { randomBytes } from 'crypto';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { INonceStore, NONCE_STORE } from './nonce.interfaces';

const NONCE_RANDOM_BYTES = 16;
const NONCE_FORMAT = /^[A-Za-z0-9._:-]{8,128}$/;

/**
 * Servicio de nonces anti-replay / tokens de un solo uso. Delega el almacenamiento en
 * `INonceStore` (DIP): el servicio no sabe si hay Redis o memoria.
 */
@Injectable()
export class NonceService {
  private readonly logger = new Logger(NonceService.name);

  constructor(
    @Inject(NONCE_STORE) private readonly store: INonceStore,
    @Inject(APP_CONFIG.KEY) private readonly config: ConfigType<AppConfigType>,
  ) {}

  get ttlSeconds(): number {
    return this.config.nonce.ttlSeconds;
  }

  /** Emite un nonce aleatorio (32 hex) válido por `NONCE_TTL_SECONDS`. */
  async issue(): Promise<string> {
    const nonce = randomBytes(NONCE_RANDOM_BYTES).toString('hex');
    await this.guarded(() => this.store.issue(nonce, this.ttlSeconds));
    return nonce;
  }

  /** Consume un nonce emitido: `true` una sola vez, `false` si no existe/expiró/ya se usó. */
  async consume(nonce: string | undefined): Promise<boolean> {
    if (!nonce || typeof nonce !== 'string') return false;
    return await this.guarded(() => this.store.consume(nonce));
  }

  /**
   * Registra un nonce elegido por el cliente (p. ej. `X-Nonce` de un request firmado).
   * `false` si ya fue visto (replay) o tiene formato inválido.
   */
  async claim(
    nonce: string | undefined,
    ttlSeconds?: number,
  ): Promise<boolean> {
    if (!nonce || !NONCE_FORMAT.test(nonce)) return false;
    return await this.guarded(() =>
      this.store.claim(nonce, ttlSeconds ?? this.ttlSeconds),
    );
  }

  /** Falla cerrado: si el store (Redis) no responde, 503 en vez de aceptar sin validar. */
  private async guarded<T>(operation: () => Promise<T>): Promise<T> {
    try {
      return await operation();
    } catch (error) {
      this.logger.error(
        `Store de nonces no disponible: ${error instanceof Error ? error.message : String(error)}`,
      );
      throw new ServiceUnavailableException(
        'Servicio de nonces no disponible.',
      );
    }
  }
}

