      await this.inbox.markRead(userId, referenceId),
    );
  }

  async unreadCount(userId: number): Promise<UnreadCountResponseDTO> {
    return { unread: await this.inbox.countUnread(userId) };
  }

  /** DEMO: se envía una notificación de prueba al propio usuario. */
  async sendTest(userId: number): Promise<TestNotificationResponseDTO> {
    const { notification, sent, gone, failed } =
      await this.notifications.notify(userId, {
        title: 'Notificación de prueba',
        body: 'Si ves esto, la bandeja y el fan-out push funcionan.',
        data: { kind: 'test' },
      });
    return {
      notification: NotificationResponseDTO.fromEntity(notification),
      sent,
      gone,
      failed,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { Notification, Prisma, PushSubscription } from '@prisma/client';
import {
  DOMAIN_EVENTS,
  NotificationCreatedEvent,
} from '@common/events/domain-events';
import { MessageDBService } from '@modules/message-db/services/message-db.service';
import {
  IPushPayload,
  IPushSendResult,
  PushSendOutcome,
} from '../interfaces/push-provider.interface';
import { NotificationInboxDBService } from './notification-inbox-db.service';
import { PushProviderRegistry } from './push-provider.registry';
import { PushSubscriptionsDBService } from './push-subscriptions-db.service';

export interface INotifyInput {
  title: string;
  body: string;
  data?: Record<string, string>;
  requiresAction?: boolean;
}

export interface INotifyResult {
  notification: Notification;
  sent: number;
  gone: number;
  failed: number;
}

/**
 * Patrón: Facade. `notify(userId, ...)` es el único punto que el resto de la app necesita:
 * guarda la notificación en la bandeja y hace fan-out a las suscripciones activas del usuario,
 * eligiendo el provider de cada canal (Strategy) y dejando cada entrega en el ledger de mensajes.
 * Un fallo de una suscripción nunca impide las demás ni la notificación in-app.
 */
@Injectable()
export class NotificationsService {
  private readonly logger = new Logger(NotificationsService.name);

  constructor(
    private readonly inbox: NotificationInboxDBService,
    private readonly subscriptions: PushSubscriptionsDBService,
    private readonly registry: PushProviderRegistry,
    private readonly messages: MessageDBService,
    private readonly events: EventEmitter2,
  ) {}

  async notify(userId: number, input: INotifyInput): Promise<INotifyResult> {
    const notification = await this.inbox.create({
      userId,
      title: input.title,
      body: input.body,
      data: input.data as Prisma.InputJsonValue | undefined,
      requiresAction: input.requiresAction,
    });

    // Observer: el tiempo real (y cualquier otro interesado) reacciona sin que este servicio lo conozca.
    const created: NotificationCreatedEvent = {
      userId,
      notification: {
        referenceId: notification.referenceId,
        title: notification.title,
        body: notification.body,
        data: notification.data,
        requiresAction: notification.requiresAction,
        createdAt: notification.createdAt,
      },
    };
    this.events.emit(DOMAIN_EVENTS.NOTIFICATION_CREATED, created);

    const active = await this.subscriptions.findActiveByUser(userId);
    const payload: IPushPayload = {
      title: input.title,
      body: input.body,
      data: { notificationId: notification.referenceId, ...input.data },
    };

    const settled = await Promise.allSettled(
      active.map((subscription) => this.deliver(userId, subscription, payload)),
    );

    const result: INotifyResult = {
      notification,
      sent: 0,
      gone: 0,
      failed: 0,
    };
    for (const entry of settled) {
      const outcome =
        entry.status === 'fulfilled' ? entry.value : PushSendOutcome.FAILED;
      if (outcome === PushSendOutcome.SENT) result.sent++;
      else if (outcome === PushSendOutcome.GONE) result.gone++;
      else result.failed++;
    }
    return result;
  }

  private async deliver(
    userId: number,
    subscription: PushSubscription,
    payload: IPushPayload,
  ): Promise<PushSendOutcome> {
    const provider = this.registry.forChannel(subscription.channel);
    const ledger = await this.messages.createPending({
      channel: 'PUSH',
      provider: provider.name,
      recipient: `***${subscription.token.slice(-6)}`,
      content: `${payload.title}\n${payload.body}`,
      createdBy: userId,
    });

    let result: IPushSendResult;
    try {
      result = await provider.send(subscription, payload);
    } catch (error) {
      result = {
        outcome: PushSendOutcome.FAILED,
        error: error instanceof Error ? error.message : String(error),
      };
    }

    switch (result.outcome) {
      case PushSendOutcome.SENT:
        await this.messages.markAccepted(ledger.id, {
          providerMessageId: result.providerMessageId,
        });
        break;
      case PushSendOutcome.GONE:
        await this.messages.markFailed(ledger.id, 'REJECTED', {
          errorCode: result.error ?? 'GONE',
        });
        await this.subscriptions.deactivate(subscription.id);
        this.logger.log(
          `Suscripción ${subscription.id} desactivada (token inexistente)`,
        );
        break;
      default:
        await this.messages.markFailed(ledger.id, 'UNAVAILABLE', {
          errorCode: result.error,
        });
    }
    return result.outcome;
  }
}

import {
  CallHandler,
  ExecutionContext,
  HttpException,
  HttpStatus,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable, catchError, tap, throwError } from 'rxjs';
import { PinoLogger } from 'nestjs-pino';
import { Request, Response } from 'express';
import { TRACE_ID_HEADER } from '@core/middlewares/trace-id.middleware';
import { RequestContext } from '@common/context/request-context';
import { formatPayload } from './payload-formatter';

/**
 * Patrón: interceptor de observabilidad (AOP). Mide latencia y loguea entrada/salida/error
 * con traceId; los payloads pasan por `formatPayload` (redacción + truncado).
 */
@Injectable()
export class ObservabilityInterceptor implements NestInterceptor {
  constructor(private readonly logger: PinoLogger) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const startedAt = Date.now();
    const http = context.switchToHttp();
    const req = http.getRequest<Request>();
    const res = http.getResponse<Response>();
    const traceId =
      (req[TRACE_ID_HEADER] as string | undefined) ??
      RequestContext.getTraceId();
    const label = `${req.method} ${req.url}`;

    this.logger.info(
      { request: req.body ? formatPayload(req.body) : undefined },
      `Incoming | ${label} | Trace ID: ${traceId}`,
    );

    return next.handle().pipe(
      tap((responseBody: unknown) => {
        const statusCode = res.statusCode;
        const ok = statusCode < 300;
        const payload = {
          response:
            responseBody !== undefined
              ? formatPayload(responseBody)
              : undefined,
          latencyMs: Date.now() - startedAt,
        };
        const message = `${ok ? 'Success' : 'Not OK'} | ${label} - (${statusCode} - ${statusName(statusCode)}) | Trace ID: ${traceId}`;
        if (ok) this.logger.info(payload, message);
        else this.logger.error(payload, message);
      }),
      catchError((error: unknown) => {
        const statusCode =
          error instanceof HttpException
            ? error.getStatus()
            : HttpStatus.INTERNAL_SERVER_ERROR;
        this.logger.error(
          {
            error: error instanceof Error ? error.message : String(error),
            stack: error instanceof Error ? error.stack : undefined,
            latencyMs: Date.now() - startedAt,
          },
          `Error | ${label} - (${statusCode} - ${statusName(statusCode)}) | Trace ID: ${traceId}`,
        );
        return throwError(() => error);
      }),
    );
  }
}

function statusName(statusCode: number): string {
  return (
    Object.entries(HttpStatus).find(
      ([, value]) => Number(value) === statusCode,
    )?.[0] ?? 'UNKNOWN'
  );
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { CryptoHelper } from '@common/helpers/crypto-helpers';

import * as DTO from '@api/onboarding/dto';
import { OnboardingService } from '@modules/onboarding/services/onboarding.service';

/**
 * Servicio de API de Onboarding - Capa BFF
 *
 * Responsabilidades:
 * - Validar DTOs
 * - Desencriptar contraseñas
 * - Orquestar llamadas al OnboardingService
 * - Transformar respuestas a DTOs
 */
@Injectable()
export class OnboardingApiService {
  constructor(private readonly onboardingService: OnboardingService) {}

  /**
   * Registra un nuevo usuario (onboarding público)
   */
  async onboarding(
    dto: DTO.OnboardingUserRequestDTO,
  ): Promise<DTO.OnboardingUserResponseDTO> {
    // Desencriptar ambas contraseñas
    const decryptedPassword = CryptoHelper.decrypt(
      dto.password,
      'sha256',
    ).toString('utf-8');

    const decryptedConfirmPassword = CryptoHelper.decrypt(
      dto.confirmPassword,
      'sha256',
    ).toString('utf-8');

    // Validar que las contraseñas coincidan
    if (decryptedPassword !== decryptedConfirmPassword) {
      throw new BadRequestException('Las contraseñas no coinciden.');
    }

    // Registrar usuario con la contraseña desencriptada
    const user = await this.onboardingService.registerUser({
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      phoneNumber: dto.phoneNumber,
      password: decryptedPassword,
      acceptedTerms: dto.acceptTerms,
    });

    // Mapear a DTO de respuesta
    return {
      referenceId: user.referenceId,
      email: user.email,
      status: user.status,
    };
  }
}

import { Prisma, UserStatus, UserProfileStatus, Users } from '@prisma/client';
import { Injectable, Logger, ConflictException } from '@nestjs/common';

import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { AuthPasswordService } from '@modules/auth/services/auth-password.service';
import { EmailService } from '@modules/email/services/email.service';
import { EmailTypeEnum } from '@modules/email/enum/email-type.enum';
import { PrismaErrorCodes } from '@common/enum/prisma-error-codes.enum';

/**
 * Servicio de Onboarding - Lógica de Negocio
 * Maneja el registro público de nuevos usuarios
 */
@Injectable()
export class OnboardingService {
  private readonly logger = new Logger(OnboardingService.name);

  constructor(
    private readonly usersRepository: UsersDBService,
    private readonly passwordService: AuthPasswordService,
    private readonly emailService: EmailService,
  ) {}

  /**
   * Registra un nuevo usuario en el sistema
   */
  async registerUser(data: {
    firstName: string;
    lastName: string;
    email: string;
    phoneNumber: string;
    password: string;
    acceptedTerms: boolean;
  }): Promise<Users> {
    try {
      // 1. Crear usuario
      const createdUser = await this.usersRepository.create({
        firstName: data.firstName,
        lastName: data.lastName,
        email: data.email,
        phoneNumber: data.phoneNumber,
        createdBy: data.email,
        status: UserStatus.PENDING_VERIFICATION,
        profileStatus: UserProfileStatus.DOCUMENT_PENDING,
        isEmployee: false,
        isLdap: false,
        acceptedTermsAt: data.acceptedTerms ? new Date() : null,
      });

      // 2. Crear credenciales (reutilizar lógica de passwords)
      await this.passwordService.createOrUpdatePassword(
        createdUser.id,
        data.password,
      );

      // 3. Enviar email de verificación (sin esperar)
      void this.emailService.sendEmailByType(
        data.email,
        EmailTypeEnum.VERIFICATION,
        createdUser,
      );

      return createdUser;
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === (PrismaErrorCodes.UniqueConstraintFailed as string)
      ) {
        throw new ConflictException('Usuario ya existe.');
      }
      throw error;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import {
  DOMAIN_EVENTS,
  OrderStatusChangedEvent,
} from '@common/events/domain-events';
import { t } from '@common/i18n/i18n.helper';
import { NotificationsService } from '@modules/notifications/services/notifications.service';

/**
 * Patrón: Observer. Orders solo publica `order.status-changed`; este listener decide notificar al
 * dueño (bandeja + push + websocket vía `notification.created`). Un consumidor nuevo del mismo
 * evento no obliga a tocar orders (OCP). Un fallo acá se loguea y no afecta la transición.
 */
@Injectable()
export class OrderNotificationsListener {
  private readonly logger = new Logger(OrderNotificationsListener.name);

  constructor(private readonly notifications: NotificationsService) {}

  @OnEvent(DOMAIN_EVENTS.ORDER_STATUS_CHANGED, { async: true })
  async handle(event: OrderStatusChangedEvent): Promise<void> {
    try {
      await this.notifications.notify(event.ownerId, {
        title: t('notifications.ORDER_STATUS_TITLE'),
        body: t('notifications.ORDER_STATUS_BODY', {
          reference: event.orderReferenceId,
          from: event.from,
          to: event.to,
        }),
        data: { orderReferenceId: event.orderReferenceId, status: event.to },
      });
    } catch (error) {
      this.logger.error(
        `No se pudo notificar el cambio de la orden ${event.orderReferenceId}: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import {
  DOMAIN_EVENTS,
  OrderStatusChangedEvent,
} from '@common/events/domain-events';
import { OrdersDBService } from '@modules/orders-db/services/orders-db.service';
import { FeeCalculator } from '@modules/orders-db/helpers/fee-calculator';
import { IUserDataOnJwt } from '@modules/auth/interfaces/user-data-on-jwt.interface';
import { normalizeDecimal } from '@common/helpers/decimal.helper';
import {
  assertOwnership,
  isAdminSubject,
} from '@common/helpers/ownership.helper';
import { ICallerContext } from '@common/interfaces/caller-context.interface';
import {
  CreateOrderRequestDTO,
  ListOrdersRequestDTO,
  UpdateOrderStatusRequestDTO,
} from '../dtos/request';
import {
  OrderResponseDTO,
  OrdersListResponseDTO,
} from '../dtos/response/order.response.dto';

/**
 * Capa API: orquesta (DTO <-> dominio, ownership, fee). Las reglas de estado y la
 * concurrencia viven en `modules/orders-db`.
 */
@Injectable()
export class OrdersApiService {
  private readonly logger = new Logger(OrdersApiService.name);

  constructor(
    private readonly ordersDBService: OrdersDBService,
    private readonly feeCalculator: FeeCalculator,
    private readonly events: EventEmitter2,
  ) {}

  async create(
    dto: CreateOrderRequestDTO,
    user: IUserDataOnJwt,
    caller?: ICallerContext,
  ): Promise<OrderResponseDTO> {
    const amount = normalizeDecimal(dto.amount);
    const order = await this.ordersDBService.create({
      ownerId: user.id,
      amount,
      fee: this.feeCalculator.calculate(amount),
      currency: dto.currency,
      description: dto.description,
    });

    this.logger.log(
      `Orden ${order.referenceId} creada (trace ${caller?.traceId ?? 'n/a'}, origen ${caller?.sourceService ?? 'n/a'})`,
    );
    return OrderResponseDTO.fromEntity(order);
  }

  async list(
    query: ListOrdersRequestDTO,
    user: IUserDataOnJwt,
  ): Promise<OrdersListResponseDTO> {
    const { items, total } = await this.ordersDBService.list({
      // Un usuario común solo ve lo suyo; un admin ve todo.
      ownerId: isAdminSubject(user) ? undefined : user.id,
      statuses: query.status,
      page: query.page,
      pageSize: query.pageSize,
    });

    return {
      data: items.map((order) => OrderResponseDTO.fromEntity(order)),
      pagination: {
        total,
        page: query.page,
        pageSize: query.pageSize,
        totalPages: Math.ceil(total / query.pageSize),
      },
    };
  }

  async findOne(
    referenceId: string,
    user: IUserDataOnJwt,
  ): Promise<OrderResponseDTO> {
    const order = await this.ordersDBService.findByReferenceOrFail(referenceId);
    assertOwnership(order, user);
    return OrderResponseDTO.fromEntity(order);
  }

  async updateStatus(
    referenceId: string,
    dto: UpdateOrderStatusRequestDTO,
    user: IUserDataOnJwt,
  ): Promise<OrderResponseDTO> {
    const order = await this.ordersDBService.findByReferenceOrFail(referenceId);
    assertOwnership(order, user);
    const updated = await this.ordersDBService.transition(order, dto.status);
    const changed: OrderStatusChangedEvent = {
      orderReferenceId: updated.referenceId,
      ownerId: updated.ownerId,
      from: order.status,
      to: updated.status,
    };
    this.events.emit(DOMAIN_EVENTS.ORDER_STATUS_CHANGED, changed);
    return OrderResponseDTO.fromEntity(updated);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { Order, OrderStatus, Prisma } from '@prisma/client';
import { OrdersRepository } from '../repositories/orders.repository';
import { assertTransition } from '../helpers/order-state-machine.helper';

export const MAX_PENDING_ORDERS_PER_OWNER = 5;

export interface ListOrdersParams {
  ownerId?: number;
  statuses?: OrderStatus[];
  page: number;
  pageSize: number;
}

@Injectable()
export class OrdersDBService {
  constructor(private readonly ordersRepository: OrdersRepository) {}

  async create(data: {
    ownerId: number;
    amount: Prisma.Decimal;
    fee: Prisma.Decimal;
    currency?: string;
    description?: string;
  }): Promise<Order> {
    return await this.ordersRepository.createWithPendingLimit(
      data,
      MAX_PENDING_ORDERS_PER_OWNER,
    );
  }

  async findByReferenceOrFail(referenceId: string): Promise<Order> {
    const order = await this.ordersRepository.findByReference(referenceId);
    if (!order) throw new NotFoundException('Orden no encontrada.');
    return order;
  }

  async list(
    params: ListOrdersParams,
  ): Promise<{ items: Order[]; total: number }> {
    const where: Prisma.OrderWhereInput = {
      ...(params.ownerId !== undefined && { ownerId: params.ownerId }),
      ...(params.statuses?.length && { status: { in: params.statuses } }),
    };

    const [items, total] = await Promise.all([
      this.ordersRepository.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (params.page - 1) * params.pageSize,
        take: params.pageSize,
      }),
      this.ordersRepository.count({ where }),
    ]);
    return { items, total };
  }

  /**
   * Transición validada por la máquina de estados y aplicada con update condicional
   * (anti-TOCTOU): si otro request cambió el estado entre la lectura y la escritura → 409.
   */
  async transition(order: Order, to: OrderStatus): Promise<Order> {
    assertTransition(order.status, to);
    await this.ordersRepository.updateWhereStatus(
      order.id,
      [order.status],
      { status: to },
      {
        conflictMessage:
          'La orden cambió de estado, recargue e intente nuevamente.',
      },
    );
    return await this.findByReferenceOrFail(order.referenceId);
  }
}

import { ConflictException, Injectable } from '@nestjs/common';
import { Order, OrderStatus, Prisma } from '@prisma/client';
import { PrismaBaseRepository } from '@core/database/base/prisma/prisma-base.repository';
import { PrismaDatasource } from '@core/database/services/prisma.service';

// P2034: write conflict / deadlock bajo aislamiento Serializable (es reintentable).
const SERIALIZATION_FAILURE = 'P2034';

@Injectable()
export class OrdersRepository extends PrismaBaseRepository<Order> {
  constructor(prisma: PrismaDatasource) {
    super(prisma, prisma.order);
  }

  async findByReference(referenceId: string): Promise<Order | null> {
    return await this.model.findUnique({ where: { referenceId } });
  }

  /**
   * Ejemplo de invariante que un UNIQUE no puede expresar ("máximo N órdenes PENDING por
   * dueño"): `count` + `create` dentro de una transacción interactiva Serializable. Sin
   * Serializable dos requests concurrentes leerían el mismo count y ambos insertarían.
   */
  async createWithPendingLimit(
    data: Prisma.OrderUncheckedCreateInput,
    maxPending: number,
  ): Promise<Order> {
    try {
      return await this.prisma.$transaction(
        async (tx) => {
          const pending = await tx.order.count({
            where: { ownerId: data.ownerId, status: OrderStatus.PENDING },
          });
          if (pending >= maxPending) {
            throw new ConflictException(
              `Se alcanzó el máximo de ${maxPending} órdenes pendientes.`,
            );
          }
          return await tx.order.create({ data });
        },
        { isolationLevel: Prisma.TransactionIsolationLevel.Serializable },
      );
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === SERIALIZATION_FAILURE
      ) {
        throw new ConflictException(
          'Conflicto de concurrencia al crear la orden, reintente.',
        );
      }
      throw error;
    }
  }
}

import { PipeTransform, Injectable, BadRequestException } from '@nestjs/common';

@Injectable()
export class ParseFilesPipe implements PipeTransform {
  /**
   * @param options.requiredFields Lista de campos que deben estar presentes obligatoriamente
   */
  constructor(private readonly options?: { requiredFields?: string[] }) {}

  transform(files: Record<string, Express.Multer.File[]>) {
    // 1. Verificar si se subió algo
    if (!files || Object.keys(files).length === 0) {
      throw new BadRequestException('No se han proporcionado archivos');
    }

    // 2. Verificar campos obligatorios (si se definieron)
    if (this.options?.requiredFields) {
      for (const field of this.options.requiredFields) {
        if (!files[field] || files[field].length === 0) {
          throw new BadRequestException(
            `El campo de archivo '${field}' es obligatorio`,
          );
        }
      }
    }

    return files;
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { CACHE_MANAGER } from '@nestjs/cache-manager';
import { ConfigType } from '@nestjs/config';
import type { Cache } from 'cache-manager';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { CACHE_KEYS } from './cache-ttl.constant';

/**
 * Patrón: cache-aside con invalidación por "época". Cachea el resultado de resolver al usuario
 * (roles + permisos) por referenceId. Cambiar roles/permisos de un usuario o de un rol afecta a
 * un conjunto de usuarios difícil de enumerar, así que `invalidateAll()` incrementa una época
 * compartida (las claves viejas dejan de leerse y expiran por TTL) en vez de borrar claves una
 * a una. TTL 0 (PERMISSIONS_CACHE_TTL_SECONDS) deshabilita todo. Cualquier error del store se
 * trata como miss: el cache nunca puede romper la autenticación.
 */
@Injectable()
export class PermissionsCacheService {
  private readonly logger = new Logger(PermissionsCacheService.name);
  private static readonly EPOCH_TTL_MS = 30 * 24 * 3600 * 1000;

  constructor(
    @Inject(CACHE_MANAGER) private readonly cache: Cache,
    @Inject(APP_CONFIG.KEY) private readonly config: ConfigType<AppConfigType>,
  ) {}

  get enabled(): boolean {
    return this.config.cache.permissionsTtlSeconds > 0;
  }

  /**
   * Cache-aside: devuelve el valor cacheado o ejecuta `loader` y lo guarda. La época se lee
   * ANTES de cargar, así un `invalidateAll()` concurrente deja el resultado (posiblemente viejo)
   * bajo una época que ya nadie lee, en vez de repoblar el cache con datos obsoletos.
   */
  async getOrLoad<T>(userRef: string, loader: () => Promise<T>): Promise<T> {
    if (!this.enabled) return await loader();

    let epoch: string;
    try {
      epoch = await this.currentEpoch();
      const hit = await this.cache.get<T>(
        CACHE_KEYS.permissions(epoch, userRef),
      );
      if (hit !== undefined && hit !== null) return hit;
    } catch (error) {
      this.warn('lectura', error);
      return await loader();
    }

    const value = await loader();
    try {
      await this.cache.set(
        CACHE_KEYS.permissions(epoch, userRef),
        value,
        this.config.cache.permissionsTtlSeconds * 1000,
      );
    } catch (error) {
      this.warn('escritura', error);
    }
    return value;
  }

  /** Invalida los permisos cacheados de TODOS los usuarios (cambio de roles/permisos). */
  async invalidateAll(): Promise<void> {
    if (!this.enabled) return;
    try {
      await this.cache.set(
        CACHE_KEYS.permissionsEpoch,
        `${Date.now()}`,
        PermissionsCacheService.EPOCH_TTL_MS,
      );
    } catch (error) {
      this.warn('invalidación', error);
    }
  }

  private async currentEpoch(): Promise<string> {
    return (await this.cache.get<string>(CACHE_KEYS.permissionsEpoch)) ?? '0';
  }

  private warn(operation: string, error: unknown): void {
    this.logger.warn(
      `Cache de permisos (${operation}) omitido: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { Permissions, Prisma } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { GetPermissionListQueryDTO } from '@modules/roles-permission-db/dtos/get-permission.request';

@Injectable()
export class PermissionsDBService {
  private readonly logger = new Logger(PermissionsDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Raw DB ───────────────────────────────────────────────────────────────

  async create(data: {
    name: string;
    description?: string;
    createdBy: string;
  }): Promise<Permissions> {
    return await this.prisma.extended.permissions.create({
      data: {
        name: data.name,
        description: data.description,
        createdBy: data.createdBy,
        isActive: true,
      },
    });
  }

  async findById(id: number): Promise<Permissions | null> {
    return await this.prisma.extended.permissions.findUnique({ where: { id } });
  }

  async findByName(name: string): Promise<Permissions | null> {
    return await this.prisma.extended.permissions.findUnique({
      where: { name },
    });
  }

  async findByIds(ids: number[]): Promise<Permissions[]> {
    return await this.prisma.extended.permissions.findMany({
      where: { id: { in: ids }, isActive: true },
    });
  }

  async findAll(query: GetPermissionListQueryDTO): Promise<Permissions[]> {
    const where: Prisma.PermissionsWhereInput = {};

    if (query?.isActive !== undefined) where.isActive = query.isActive;

    if (query?.search) {
      where.OR = [
        { name: { contains: query.search, mode: 'insensitive' } },
        { description: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    return await this.prisma.extended.permissions.findMany({
      where,
      orderBy: { name: 'asc' },
    });
  }

  async update(
    id: number,
    data: {
      name?: string;
      description?: string;
      isActive?: boolean;
      lastChangedBy: string;
      changedReason?: string;
    },
  ): Promise<Permissions> {
    const updated = await this.prisma.extended.permissions.update({
      where: { id },
      data: {
        name: data.name,
        description: data.description,
        isActive: data.isActive,
        lastChangedBy: data.lastChangedBy,
        lastChangedAt: new Date(),
        changedReason: data.changedReason,
      },
    });
    await this.permissionsCache.invalidateAll();
    return updated;
  }

  async softDelete(
    id: number,
    deletedBy: string,
    reason?: string,
  ): Promise<Permissions> {
    const updated = await this.prisma.extended.permissions.update({
      where: { id },
      data: {
        isActive: false,
        lastChangedBy: deletedBy,
        lastChangedAt: new Date(),
        changedReason: reason || 'Permiso eliminado',
      },
    });
    await this.permissionsCache.invalidateAll();
    return updated;
  }

  async hardDelete(id: number): Promise<Permissions> {
    return await this.prisma.extended.permissions.delete({ where: { id } });
  }

  async countByStatus(): Promise<{
    total: number;
    active: number;
    inactive: number;
  }> {
    const [total, active] = await Promise.all([
      this.prisma.extended.permissions.count(),
      this.prisma.extended.permissions.count({ where: { isActive: true } }),
    ]);
    return { total, active, inactive: total - active };
  }

  async existsByName(name: string, excludeId?: number): Promise<boolean> {
    const where: Prisma.PermissionsWhereInput = { name };
    if (excludeId) where.id = { not: excludeId };
    const count = await this.prisma.extended.permissions.count({ where });
    return count > 0;
  }

  async isInUse(permissionId: number): Promise<boolean> {
    const [inRoles, inUsers] = await Promise.all([
      this.prisma.extended.rolePermissions.count({ where: { permissionId } }),
      this.prisma.extended.userPermissions.count({ where: { permissionId } }),
    ]);
    return inRoles > 0 || inUsers > 0;
  }

  // ─── Business logic ───────────────────────────────────────────────────────

  async createPermission(data: {
    name: string;
    description?: string;
    createdBy: string;
  }): Promise<Permissions> {
    if (!this.isValidPermissionFormat(data.name)) {
      throw new BadRequestException(
        'El nombre del permiso debe seguir el formato "resource:action" (ej: customers:read)',
      );
    }

    const exists = await this.existsByName(data.name);
    if (exists)
      throw new ConflictException(`El permiso "${data.name}" ya existe.`);

    return await this.create(data);
  }

  async getPermissionById(id: number): Promise<Permissions> {
    const permission = await this.findById(id);
    if (!permission)
      throw new NotFoundException(`Permiso con ID ${id} no encontrado.`);
    return permission;
  }

  async getPermissionByName(name: string): Promise<Permissions> {
    const permission = await this.findByName(name);
    if (!permission)
      throw new NotFoundException(`Permiso "${name}" no encontrado.`);
    return permission;
  }

  async getAllPermissions(
    query: GetPermissionListQueryDTO,
  ): Promise<Permissions[]> {
    return this.findAll(query);
  }

  async getPermissionsStats() {
    return this.countByStatus();
  }

  async updatePermission(
    id: number,
    data: {
      name?: string;
      description?: string;
      isActive?: boolean;
      lastChangedBy: string;
      changedReason?: string;
    },
  ): Promise<Permissions> {
    await this.getPermissionById(id);

    if (data.name) {
      if (!this.isValidPermissionFormat(data.name)) {
        throw new BadRequestException(
          'El nombre del permiso debe seguir el formato "resource:action" (ej: customers:read)',
        );
      }
      const exists = await this.existsByName(data.name, id);
      if (exists)
        throw new ConflictException(`El permiso "${data.name}" ya existe.`);
    }

    return await this.update(id, data);
  }

  async deletePermission(
    id: number,
    deletedBy: string,
    reason?: string,
  ): Promise<Permissions> {
    await this.getPermissionById(id);

    const inUse = await this.isInUse(id);
    if (inUse) {
      throw new BadRequestException(
        'No se puede eliminar el permiso porque está asignado a roles o usuarios. Desactívalo en su lugar.',
      );
    }

    return await this.softDelete(id, deletedBy, reason);
  }

  async validatePermissions(permissionIds: number[]): Promise<Permissions[]> {
    const permissions = await this.findByIds(permissionIds);

    if (permissions.length !== permissionIds.length) {
      const missingIds = permissionIds.filter(
        (id) => !permissions.map((p) => p.id).includes(id),
      );
      throw new NotFoundException(
        `Los siguientes id's de permisos no existen o están inactivos: ${missingIds.join(', ')}`,
      );
    }

    return permissions;
  }

  private isValidPermissionFormat(name: string): boolean {
    return /^[a-z][a-z0-9_-]*:[a-z][a-z0-9_-]*$/.test(name);
  }
}

