import { Inject, Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { PrismaClient } from '@prisma/client';
import { AsyncLocalStorage } from 'async_hooks';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { RequestContext } from '@common/context/request-context';

export const auditStorage = new AsyncLocalStorage<{
  userId: string;
  ip: string;
  userAgent: string;
  applicationName: string;
}>();

// Guard: evita re-entrar a la lógica de auditoría cuando tx[model][operation] re-dispara la extensión
const auditTxActive = new AsyncLocalStorage<boolean>();

@Injectable()
export class PrismaDatasource extends PrismaClient implements OnModuleInit {
  public isConnected: boolean = false;
  private readonly logger = new Logger(PrismaDatasource.name);

  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly appConfig: ConfigType<AppConfigType>,
  ) {
    super();
  }

  public readonly extended = this.$extends({
    query: {
      $allModels: {
        $allOperations: async ({ model, operation, args, query }) => {
          const writeOperations = [
            'create',
            'update',
            'upsert',
            'delete',
            'createMany',
            'updateMany',
            'deleteMany',
          ];

          const context = auditStorage.getStore();
          const isReentrant = auditTxActive.getStore();

          if (
            context &&
            !isReentrant &&
            writeOperations.includes(operation) &&
            (model as string) !== 'AuditLogs'
          ) {
            const base = this as unknown as PrismaClient;

            return auditTxActive.run(true, () =>
              base.$transaction(async (tx) => {
                // set_config con is_local=true: aplica solo a esta transacción
                // $executeRaw con template literals: parametrizado, sin riesgo de SQL injection
                await tx.$executeRaw`SELECT set_config('app.current_user_id', ${context.userId}, true)`;
                await tx.$executeRaw`SELECT set_config('app.client_ip', ${context.ip}, true)`;
                await tx.$executeRaw`SELECT set_config('app.user_agent', ${context.userAgent}, true)`;
                await tx.$executeRaw`SELECT set_config('app.application_name', ${context.applicationName}, true)`;
                // traceId de la request: el trigger lo guarda en audit_logs.extra_data para correlacionar
                // pepper de la firma de auditoría: viene del entorno, nunca del SQL versionado
                await tx.$executeRaw`SELECT set_config('app.audit_pepper', ${this.appConfig.audit.signaturePepper}, true)`;
                await tx.$executeRaw`SELECT set_config('app.trace_id', ${RequestContext.getTraceId() ?? ''}, true)`;

                // Ejecutar la operación del modelo a través de tx (misma conexión/transacción)
                // Así el trigger dispara dentro de la misma tx y lee las variables de sesión
                return tx[model as string][operation](args) as Promise<unknown>;
              }),
            );
          }

          return query(args);
        },
      },
    },
  });

  async onModuleInit() {
    await this.$connect()
      .then(() => {
        this.isConnected = true;
        this.logger.log('Database connected');
      })
      .catch((e) => {
        this.isConnected = false;
        this.logger.error(e, 'Database connection error');
      });
  }

  async onModuleDestroy() {
    await this.$disconnect();
  }

  /*handleDbQueryEvent(event: Prisma.QueryEvent) {
    this.logger.log(
      {
        query: event.query,
        params: event.params,
        duration: `${event.duration} ms`,
        timestamp: event.timestamp,
        traceId: this.request[TRACE_ID_HEADER],
      },
      'Database QUERY',
    );
  }

  handleDbQueryError(error: Prisma.PrismaClientKnownRequestError) {
    this.logger.error(
      { ...error, traceId: this.request[TRACE_ID_HEADER] },
      'Database ERROR',
    );
  }

  handleDbQueryWarn(warn: any) {
    this.logger.warn(
      { ...warn, traceId: this.request[TRACE_ID_HEADER] },
      'Database WARN',
    );
  }

  handleDbQueryInfo(info: any) {
    console.log('Database info: ', info);
  }*/
}

import { Inject, Injectable } from '@nestjs/common';
import type { PushChannel } from '@prisma/client';
import {
  IPushProvider,
  PUSH_PROVIDERS,
} from '../interfaces/push-provider.interface';
import { NoopPushProvider } from '../providers/noop-push.provider';

/** Resuelve el provider de un canal: el habilitado si existe, si no el Noop (nunca null). */
@Injectable()
export class PushProviderRegistry {
  constructor(
    @Inject(PUSH_PROVIDERS) private readonly providers: IPushProvider[],
    private readonly noop: NoopPushProvider,
  ) {}

  forChannel(channel: PushChannel): IPushProvider {
    return (
      this.providers.find((p) => p.channel === channel && p.isEnabled()) ??
      this.noop
    );
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PushChannel, PushSubscription } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';

export interface IRegisterSubscription {
  channel: PushChannel;
  token: string;
  p256dh?: string;
  auth?: string;
}

@Injectable()
export class PushSubscriptionsDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  /**
   * Alta idempotente por (channel, token). Si el token ya existía (p. ej. otro usuario inició
   * sesión en el mismo dispositivo) pasa a pertenecer a `userId` y se reactiva.
   */
  register(
    userId: number,
    input: IRegisterSubscription,
  ): Promise<PushSubscription> {
    const keys = {
      p256dh: input.p256dh ?? null,
      auth: input.auth ?? null,
    };
    return this.prisma.pushSubscription.upsert({
      where: {
        channel_token: { channel: input.channel, token: input.token },
      },
      create: { userId, ...input, ...keys },
      update: { userId, active: true, ...keys },
    });
  }

  /** Ownership estricto: solo borra si la suscripción es del usuario; si no, 404. */
  async remove(userId: number, id: number): Promise<void> {
    const { count } = await this.prisma.pushSubscription.deleteMany({
      where: { id, userId },
    });
    if (count === 0) throw new NotFoundException('Suscripción no encontrada.');
  }

  findActiveByUser(userId: number): Promise<PushSubscription[]> {
    return this.prisma.pushSubscription.findMany({
      where: { userId, active: true },
      orderBy: { id: 'asc' },
    });
  }

  async deactivate(id: number): Promise<void> {
    await this.prisma.pushSubscription.updateMany({
      where: { id },
      data: { active: false },
    });
  }
}

import { Injectable, Inject, Logger } from '@nestjs/common';
import {
  QueryOptions,
  QueryTypes,
  Transaction,
  TransactionOptions,
} from '@sequelize/core';
import { DatabaseConnections } from '@core/database/enum/database.enum';
import { SequelizeService } from '@core/database/services/sequelize.service';

/**
 * Opciones de consulta que acepta el método query de Sequelize (subconjunto usado por el starter).
 */
export type IRawQueryOptions = {
  // SELECT, INSERT, UPDATE, DELETE, BULKUPDATE, RAW...
  type?: QueryTypes;
  // Transacción opcional para ejecutar la query dentro de ella
  transaction?: Transaction;
  // Placeholders `:nombre` (objeto) o `?` (array). INTERPOLA el valor en el texto SQL.
  replacements?: Record<string, unknown> | unknown[];
  // Parámetros reales `$1`, `$2` (array) o `$nombre` (objeto). Obligatorio para payloads grandes.
  bind?: Record<string, unknown> | unknown[];
  // Devuelve solo la primera fila (`T | null`) en vez de un array
  plain?: boolean;
  // Si Sequelize debe imprimir el SQL en la consola
  logging?: boolean;
};

/**
 * Patrón: Facade/Adapter sobre `sequelize.query` para SQL crudo (SP, TVF, JSON_TABLE, SQL específico
 * del dialecto que el ORM no expresa bien). Una instancia por conexión: la default se inyecta por
 * clase y las nombradas con `@InjectRawQueryExecutor(connectionName)`.
 */
@Injectable()
export class RawQueryExecutorService {
  constructor(
    @Inject(DatabaseConnections.DEFAULT)
    private readonly dbService: SequelizeService,
  ) {}

  /**
   * Ejecuta una consulta SQL cruda y devuelve los resultados.
   *
   * @template T El tipo del objeto o array de objetos que esperas como resultado.
   * @param sqlQuery La cadena SQL a ejecutar.
   * @param options Opciones de la consulta (transaction, replacements, bind, type, plain).
   * @returns Una promesa que resuelve con el resultado de la consulta (con `plain: true`, `T | null`).
   */
  async executeRawQuery<T = unknown[]>(
    sqlQuery: string,
    options: IRawQueryOptions = {},
  ): Promise<T> {
    const queryOptions: QueryOptions = {
      // Por defecto SELECT: en el dialecto IBM i también devuelve el result set de CALL y TABLE(...)
      type: options.type ?? QueryTypes.SELECT,
      transaction: options.transaction,
      replacements: options.replacements,
      bind: options.bind,
      plain: options.plain,
      logging: options.logging
        ? (sql: string) => Logger.debug(sql, RawQueryExecutorService.name)
        : false,
    };

    const results = await this.dbService
      .getInstance()
      .query(sqlQuery, queryOptions);

    return results as T;
  }

  /**
   * Ejecuta un UPDATE/DELETE y devuelve las filas afectadas.
   * Con `QueryTypes.BULKUPDATE` es el único camino que devuelve el conteo como número en el dialecto
   * IBM i; sin `type` el driver devuelve `[[], []]` y `Number(resultado)` da siempre 0.
   */
  async executeAffectedRows(
    sqlQuery: string,
    options: Omit<IRawQueryOptions, 'type' | 'plain'> = {},
  ): Promise<number> {
    const affected = await this.executeRawQuery<number | undefined>(sqlQuery, {
      ...options,
      type: QueryTypes.BULKUPDATE,
    });
    return Number(affected ?? 0);
  }

  /**
   * Transacción administrada (commit/rollback automáticos) sobre la conexión de este executor.
   */
  async transaction<T>(
    fn: (tx: Transaction) => PromiseLike<T> | T,
    options?: TransactionOptions,
  ): Promise<T> {
    return this.dbService.transaction(fn, options);
  }

  /**
   * Inicia una transacción manual: quien la abre debe llamar `commit()`/`rollback()`.
   */
  async beginTransaction(options?: TransactionOptions): Promise<Transaction> {
    return await this.dbService.beginTransaction(options);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import type { Server } from 'socket.io';

export const userRoom = (userId: number): string => `user:${userId}`;

/**
 * Patrón: Facade/Port hacia socket.io. El resto de la app emite con `emitToUser` sin conocer el
 * servidor; mientras el gateway no haya inicializado (tests, procesos sin WS) es un no-op (Null Object).
 */
@Injectable()
export class RealtimeService {
  private readonly logger = new Logger(RealtimeService.name);
  private server: Server | null = null;

  attach(server: Server): void {
    this.server = server;
  }

  emitToUser(userId: number, event: string, payload: unknown): boolean {
    if (!this.server) return false;
    try {
      this.server.to(userRoom(userId)).emit(event, payload);
      return true;
    } catch (error) {
      this.logger.warn(
        `No se pudo emitir "${event}" a user:${userId}: ${error instanceof Error ? error.message : String(error)}`,
      );
      return false;
    }
  }
}

import { Injectable } from '@nestjs/common';
import {
  HealthIndicatorResult,
  HealthIndicatorService,
} from '@nestjs/terminus';
import { RedisService } from './redis.service';

/**
 * Indicador INFORMATIVO (igual que SMTP): Redis es una dependencia degradable porque cache,
 * throttler y nonces tienen fallback en memoria, así que no baja el estado general.
 */
@Injectable()
export class RedisHealthIndicator {
  constructor(
    private readonly healthIndicatorService: HealthIndicatorService,
    private readonly redis: RedisService,
  ) {}

  async check(): Promise<HealthIndicatorResult<'redis'>> {
    const session = this.healthIndicatorService.check('redis');
    if (!this.redis.enabled) {
      return session.up({ mode: 'memory-fallback' });
    }
    return (await this.redis.ping())
      ? session.up({ mode: 'redis' })
      : session.down({ mode: 'redis', message: 'Redis no disponible' });
  }
}

import {
  Inject,
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import type Redis from 'ioredis';
import { REDIS_CLIENT } from './redis.constants';

/**
 * Patrón: Null Object + ciclo de vida. Envuelve el cliente ioredis singleton (o `null` si no hay
 * REDIS_URL) para que los consumidores decidan "Redis o memoria" con `service.client`, sin
 * conocer la config. Conecta en `onModuleInit` (con `lazyConnect` + `enableOfflineQueue:false`
 * el primer comando fallaría si la conexión se abriera de forma implícita) y nunca bloquea ni
 * rompe el arranque si Redis no responde.
 */
@Injectable()
export class RedisService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(RedisService.name);
  private lastErrorMessage: string | null = null;

  constructor(@Inject(REDIS_CLIENT) private readonly redis: Redis | null) {}

  /** Cliente ioredis, o `null` si Redis no está configurado. */
  get client(): Redis | null {
    return this.redis;
  }

  get enabled(): boolean {
    return this.redis !== null;
  }

  /** `true` si hay cliente y la conexión está lista para recibir comandos. */
  get isReady(): boolean {
    return this.redis?.status === 'ready';
  }

  async onModuleInit(): Promise<void> {
    if (!this.redis) {
      this.logger.log('REDIS_URL no configurado: se usan fallbacks en memoria');
      return;
    }
    // Sin listener, un 'error' de ioredis sería una excepción no capturada.
    this.redis.on('error', (error: Error) => {
      if (error.message !== this.lastErrorMessage) {
        this.lastErrorMessage = error.message;
        this.logger.warn(`Redis: ${error.message}`);
      }
    });
    this.redis.on('ready', () => {
      this.lastErrorMessage = null;
      this.logger.log('Redis conectado');
    });
    try {
      await this.redis.connect();
    } catch (error) {
      this.logger.warn(
        `No se pudo conectar a Redis al iniciar (se reintentará): ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  }

  /** Ping informativo para health: `true` solo si Redis responde PONG. */
  async ping(): Promise<boolean> {
    if (!this.isReady || !this.redis) return false;
    try {
      return (await this.redis.ping()) === 'PONG';
    } catch {
      return false;
    }
  }

  onModuleDestroy(): void {
    this.redis?.disconnect();
  }
}

import {
  BadRequestException,
  Inject,
  Injectable,
  Logger,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Prisma } from '@prisma/client';
import * as ExcelJS from 'exceljs';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { StorageService } from '@modules/storage/services/storage.service';
import { IJobContext, IJobHandler } from '../interfaces/job-handler.interface';
import { NonRetryableJobError } from '../errors/non-retryable-job.error';

export const REPORT_EXPORT_JOB_TYPE = 'report.export';
const MAX_ROWS = 1000;
const XLSX_MIME =
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

interface IReportExportPayload {
  title: string;
  rows: number;
}

/**
 * Handler DEMO (Strategy): genera un Excel chico con exceljs. Si el storage S3 está configurado lo
 * sube y devuelve key/bucket; si no, devuelve el archivo en base64 dentro de `result` (por eso el
 * tope de filas). Es el modelo a copiar para un export real: payload validado + artefacto + result.
 */
@Injectable()
export class ReportExportHandler implements IJobHandler {
  readonly type = REPORT_EXPORT_JOB_TYPE;
  private readonly logger = new Logger(ReportExportHandler.name);

  constructor(
    private readonly storage: StorageService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  validatePayload(payload: unknown): void {
    const parsed = this.parse(payload);
    if (typeof parsed === 'string') throw new BadRequestException(parsed);
  }

  async handle(job: IJobContext): Promise<Prisma.InputJsonValue> {
    const parsed = this.parse(job.payload);
    if (typeof parsed === 'string') throw new NonRetryableJobError(parsed);

    const buffer = await this.buildWorkbook(parsed);
    const fileName = `report-${job.referenceId}.xlsx`;

    if (!this.isStorageConfigured()) {
      this.logger.log(`Storage no configurado: ${fileName} va en el result`);
      return {
        fileName,
        rows: parsed.rows,
        storage: null,
        contentBase64: buffer.toString('base64'),
      };
    }

    const [uploaded] = await this.storage.uploadFilesBatch([
      {
        file: {
          buffer,
          originalname: fileName,
          mimetype: XLSX_MIME,
        } as Express.Multer.File,
        path: 'exports',
        fileName,
        contentType: XLSX_MIME,
      },
    ]);
    return {
      fileName,
      rows: parsed.rows,
      storage: { key: uploaded.key, bucket: uploaded.bucket },
    };
  }

  private parse(payload: unknown): IReportExportPayload | string {
    const source =
      typeof payload === 'object' && payload !== null
        ? (payload as Record<string, unknown>)
        : {};
    const title = source.title ?? 'Reporte demo';
    const rows = source.rows ?? 10;

    if (typeof title !== 'string' || title.length === 0 || title.length > 100) {
      return 'title debe ser un texto de 1 a 100 caracteres';
    }
    if (
      !Number.isInteger(rows) ||
      (rows as number) < 1 ||
      (rows as number) > MAX_ROWS
    ) {
      return `rows debe ser un entero entre 1 y ${MAX_ROWS}`;
    }
    return { title, rows: rows as number };
  }

  private async buildWorkbook(payload: IReportExportPayload): Promise<Buffer> {
    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet(payload.title.slice(0, 31));
    sheet.columns = [
      { header: 'N°', key: 'n', width: 8 },
      { header: 'Descripción', key: 'description', width: 30 },
      { header: 'Fecha', key: 'date', width: 22 },
    ];
    sheet.getRow(1).font = { bold: true };

    const now = new Date().toISOString();
    for (let i = 1; i <= payload.rows; i++) {
      sheet.addRow({ n: i, description: `Fila de ejemplo ${i}`, date: now });
    }

    return Buffer.from(await workbook.xlsx.writeBuffer());
  }

  private isStorageConfigured(): boolean {
    const { bucketName, accessKeyId, secretAccessKey, region } = this.config.s3;
    return Boolean(bucketName && accessKeyId && secretAccessKey && region);
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { IReportService } from '../domain/interfaces/report.interface';
import { IReportOptions, IReportPayload } from '../domain/types/report.type';
import { ExcelGenerator } from '../infrastructure/excel-generator.hint';
import { PdfHtmlGenerator } from '../infrastructure/pdf-html-generator.hint';
import { PdfNativeGenerator } from '../infrastructure/pdf-native-generator.hint';

@Injectable()
export class ReportService implements IReportService {
  public async generate(
    payload: IReportPayload,
    options: IReportOptions,
  ): Promise<Buffer> {
    switch (options.format) {
      case 'xlsx':
        return await ExcelGenerator.generateXlsx(payload);

      case 'csv':
        return ExcelGenerator.generateCsv(payload);

      case 'pdf':
        return this.handlePdfGeneration(payload, options);

      default:
        throw new BadRequestException(
          `Formato no soportado: ${options.format as string}`,
        );
    }
  }

  private async handlePdfGeneration(
    payload: IReportPayload,
    options: IReportOptions,
  ): Promise<Buffer> {
    const engine = options.pdfEngine || 'html';

    if (engine === 'html') {
      if (!options.templateHtml) {
        throw new BadRequestException(
          'El motor HTML requiere la propiedad "templateHtml".',
        );
      }
      return await PdfHtmlGenerator.generate(payload, options.templateHtml);
    }

    if (engine === 'native') {
      if (!options.nativeDefinition) {
        throw new BadRequestException(
          'El motor Nativo requiere la propiedad "nativeDefinition".',
        );
      }
      return await PdfNativeGenerator.generate(options.nativeDefinition);
    }

    throw new BadRequestException(
      `Motor PDF "${engine as string}" no reconocido.`,
    );
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { RolePermissions } from '@prisma/client';

@Injectable()
export class RolePermissionsDBService {
  private readonly logger = new Logger(RolePermissionsDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Assign ──────────────────────────────────────────────────────────────

  async assignPermissionsToRole(data: {
    roleId: number;
    permissionIds: number[];
    createdBy: string;
  }): Promise<RolePermissions[]> {
    const result = await this.prisma.extended.$transaction(async (tx) => {
      const oldPermissions = await tx.rolePermissions.findMany({
        where: { roleId: data.roleId },
        include: { permission: true },
      });

      await tx.auditLogs.create({
        data: {
          tableName: 'role_permissions',
          recordId: data.roleId.toString(),
          operationType: 'UPDATE',
          oldData: oldPermissions,
          newData: { permissionIds: data.permissionIds },
          changedBy: data.createdBy,
        },
      });

      await tx.rolePermissions.deleteMany({ where: { roleId: data.roleId } });

      if (data.permissionIds.length === 0) return [];

      await tx.rolePermissions.createMany({
        data: data.permissionIds.map((permissionId) => ({
          roleId: data.roleId,
          permissionId,
          createdBy: data.createdBy,
        })),
        skipDuplicates: true,
      });

      return await tx.rolePermissions.findMany({
        where: { roleId: data.roleId },
        include: { permission: true },
      });
    });
    await this.permissionsCache.invalidateAll();
    return result;
  }

  // ─── Read ─────────────────────────────────────────────────────────────────

  async getPermissionsByRoleId(roleId: number) {
    return await this.prisma.extended.rolePermissions.findMany({
      where: { roleId, permission: { isActive: true } },
      include: { permission: true },
    });
  }

  async getRolesByPermissionId(permissionId: number) {
    return await this.prisma.extended.rolePermissions.findMany({
      where: { permissionId, role: { isActive: true } },
      include: { role: true },
    });
  }

  async roleHasPermission(
    roleId: number,
    permissionId: number,
  ): Promise<boolean> {
    const count = await this.prisma.extended.rolePermissions.count({
      where: { roleId, permissionId, permission: { isActive: true } },
    });
    return count > 0;
  }

  // ─── Remove ───────────────────────────────────────────────────────────────

  async removePermissionFromRole(
    roleId: number,
    permissionId: number,
    removedBy: string,
  ): Promise<void> {
    await this.prisma.extended.$transaction(async (tx) => {
      await tx.auditLogs.create({
        data: {
          tableName: 'role_permissions',
          recordId: `${roleId}-${permissionId}`,
          operationType: 'DELETE',
          oldData: { roleId, permissionId },
          changedBy: removedBy,
        },
      });

      await tx.rolePermissions.deleteMany({ where: { roleId, permissionId } });
    });
    await this.permissionsCache.invalidateAll();
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';

import * as RequestDTO from '@api/roles-permission/dtos/request';
import * as ResponseDTO from '@api/roles-permission/dtos/response';

import { RolesDBService } from '@modules/roles-permission-db/services/roles-db.service';
import { PermissionsDBService } from '@modules/roles-permission-db/services/permissions-db.service';
import { UserRolesDBService } from '@modules/roles-permission-db/services/user-roles-db.service';
import { UserPermissionsDBService } from '@modules/roles-permission-db/services/user-permissions-db.service';
import { RolesPermissionsMapper } from '@api/roles-permission/helpers';

import { UsersDBService } from '@modules/users-db/services/users-db.service';

@Injectable()
export class RolesApiService {
  private readonly logger = new Logger(RolesApiService.name);

  constructor(
    private readonly rolesDBService: RolesDBService,
    private readonly permissionsDBService: PermissionsDBService,
    private readonly userRolesDBService: UserRolesDBService,
    private readonly userPermissionsDBService: UserPermissionsDBService,
    private readonly usersDBService: UsersDBService,
    private readonly mapper: RolesPermissionsMapper,
  ) {}

  // ==================== ROLES ====================

  async createRole(
    dto: RequestDTO.CreateRoleRequestDTO,
    createdBy: string,
  ): Promise<ResponseDTO.RoleResponseDTO> {
    this.logger.log(
      `Usuario [${createdBy}] solicita crear el rol: "${dto.name}"`,
    );
    const role = await this.rolesDBService.createRole({
      name: dto.name,
      description: dto.description,
      createdBy,
    });
    return this.mapper.permissionToResponse(role);
  }

  async getRoleById(id: number): Promise<ResponseDTO.RoleResponseDTO> {
    this.logger.log(`Obteniendo rol con ID: ${id}`);
    const role = await this.rolesDBService.getRoleById(id);
    return this.mapper.permissionToResponse(role);
  }

  async getAllRoles(
    query: RequestDTO.GetRoleListQueryDTO,
  ): Promise<ResponseDTO.RoleListResponseDTO> {
    this.logger.log('Listando roles');
    const roles = await this.rolesDBService.getAllRoles(query);
    const stats = await this.rolesDBService.getRolesStats();

    return {
      roles: roles.map((role) => this.mapper.permissionToResponse(role)),
      total: stats.total,
      active: stats.active,
      inactive: stats.inactive,
    };
  }

  async updateRole(
    id: number,
    dto: RequestDTO.UpdateRoleRequestDTO,
    updatedBy: string,
  ): Promise<ResponseDTO.RoleResponseDTO> {
    this.logger.log(`Actualizando rol con ID: ${id}`);
    const role = await this.rolesDBService.updateRole(id, {
      name: dto.name,
      description: dto.description,
      isActive: dto.isActive,
      lastChangedBy: updatedBy,
    });
    return this.mapper.permissionToResponse(role);
  }

  // ==================== USER ROLES ====================

  async assignRolesToUser(
    userId: number,
    dto: RequestDTO.AssignRolesToUserRequestDTO,
    assignedBy: string,
  ): Promise<ResponseDTO.UserRoleAssignmentResponseDTO> {
    this.logger.log(`Asignando roles al usuario con ID: ${userId}`);
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`El usuario con ID ${userId} no existe`);

    const roleIds = [...new Set(dto.roles.map((r) => r.id))];

    await this.userRolesDBService.assignRolesToUserWithValidation({
      userId,
      roleIds,
      createdBy: assignedBy,
    });

    const updatedUserRoles = await this.userRolesDBService.getUserRoles(userId);

    return {
      success: true,
      userId: user.id,
      userEmail: user.email,
      userName: `${user.firstName} ${user.lastName}`,
      roles: updatedUserRoles.map((ur) => ({
        id: ur.role.id,
        name: ur.role.name,
        displayName: ur.role?.displayName ?? '',
        assigned: true,
        message: 'Rol activo en el perfil del usuario',
      })),
      totalProcessed: roleIds.length,
      successfulAssignments: updatedUserRoles.length,
      failedAssignments: 0,
      assignedAt: new Date(),
      assignedBy,
    };
  }

  async getUserWithRoles(
    userId: number,
  ): Promise<ResponseDTO.UserWithRolesResponseDTO> {
    this.logger.log(`Obteniendo roles del usuario con ID: ${userId}`);
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`El usuario con ID ${userId} no existe`);

    const userRoles = await this.userRolesDBService.getUserRoles(userId);
    const directPermissions =
      await this.userPermissionsDBService.getUserPermissions(userId);

    const roleIds = userRoles.map((ur) => ur.role.id);
    const rolePermissionsData =
      await this.usersDBService.getRolePermissions(roleIds);

    const allPermissionsMap = new Map<
      string,
      { name: string; source: string }
    >();

    rolePermissionsData.forEach((perm) => {
      const roleSource =
        userRoles.find((ur) => ur.role.id === roleIds.find((id) => id))?.role
          .name || 'rol';
      allPermissionsMap.set(perm.name, { name: perm.name, source: roleSource });
    });

    directPermissions.forEach((dp) => {
      allPermissionsMap.set(dp.permission.name, {
        name: dp.permission.name,
        source: 'directo',
      });
    });

    return {
      userId: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      roles: userRoles.map((ur) => ({
        id: ur.role.id,
        name: ur.role.name,
        displayName: ur.role?.displayName ?? '',
        description: ur.role.description,
        isActive: true,
      })),
      directPermissions: directPermissions.map((dp) => ({
        id: dp.permission.id,
        name: dp.permission.name,
        displayName: dp?.permission?.displayName ?? '',
        source: 'directo',
      })),
      allPermissions: Array.from(allPermissionsMap.values()).map(
        (p, index) => ({
          id: index + 1,
          name: p.name,
          displayName: p?.name ?? '',
          source: p.source,
        }),
      ),
      rolesCount: userRoles.length,
      permissionsCount: allPermissionsMap.size,
    };
  }

  // ==================== USER PERMISSIONS ====================

  async assignPermissionsToUser(
    userId: number,
    dto: RequestDTO.AssignPermissionsToUserRequestDTO,
    assignedBy: string,
  ): Promise<ResponseDTO.UserPermissionAssignmentResponseDTO> {
    this.logger.log(`Asignando permisos directos al usuario con ID: ${userId}`);
    const permissionIds = dto.permissions.map((p) => p.id);

    const validatedPermissions =
      await this.permissionsDBService.validatePermissions(permissionIds);

    await this.userPermissionsDBService.assignPermissionsToUserWithValidation({
      userId,
      permissionIds,
      createdBy: assignedBy,
    });

    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`El usuario con ID ${userId} no existe`);

    return {
      success: true,
      userId: user.id,
      userEmail: user.email,
      userName: `${user.firstName} ${user.lastName}`,
      permissions: validatedPermissions.map((p) => ({
        id: p.id,
        name: p.name,
        displayName: p?.displayName ?? '',
        assigned: true,
        message: 'Permiso directo asignado correctamente',
      })),
      totalProcessed: permissionIds.length,
      successfulAssignments: permissionIds.length,
      failedAssignments: 0,
      assignedAt: new Date(),
      assignedBy,
    };
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  ConflictException,
  BadRequestException,
} from '@nestjs/common';
import { Roles, Prisma } from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { GetRoleListQueryDTO } from '@modules/roles-permission-db/dtos/get-role.request';
import { RolePermissionsDBService } from './role-permissions-db.service';

@Injectable()
export class RolesDBService {
  private readonly logger = new Logger(RolesDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly rolePermissionsDBService: RolePermissionsDBService,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Raw DB ───────────────────────────────────────────────────────────────

  async create(data: {
    name: string;
    description?: string;
    createdBy: string;
  }): Promise<Roles> {
    return await this.prisma.extended.roles.create({
      data: {
        name: data.name,
        description: data.description,
        createdBy: data.createdBy,
        isActive: true,
      },
    });
  }

  async findById(id: number): Promise<Roles | null> {
    return await this.prisma.extended.roles.findUnique({ where: { id } });
  }

  async findByName(name: string): Promise<Roles | null> {
    return await this.prisma.extended.roles.findUnique({ where: { name } });
  }

  async findAll(query: GetRoleListQueryDTO): Promise<Roles[]> {
    const where: Prisma.RolesWhereInput = {};

    if (query?.isActive !== undefined) where.isActive = query.isActive;

    if (query?.search) {
      where.OR = [
        { name: { contains: query.search, mode: 'insensitive' } },
        { description: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    return await this.prisma.extended.roles.findMany({
      where,
      orderBy: { createdAt: 'desc' },
    });
  }

  async getPermissionsByRoleIds(roleIds: number[]) {
    return this.prisma.extended.rolePermissions.findMany({
      where: { roleId: { in: roleIds } },
      include: { permission: true },
    });
  }

  async update(
    id: number,
    data: {
      name?: string;
      description?: string;
      isActive?: boolean;
      lastChangedBy: string;
      changedReason?: string;
    },
  ): Promise<Roles> {
    const updated = await this.prisma.extended.roles.update({
      where: { id },
      data: {
        name: data.name,
        description: data.description,
        isActive: data.isActive,
        lastChangedBy: data.lastChangedBy,
        lastChangedAt: new Date(),
        changedReason: data.changedReason,
      },
    });
    await this.permissionsCache.invalidateAll();
    return updated;
  }

  async softDelete(
    id: number,
    deletedBy: string,
    reason?: string,
  ): Promise<Roles> {
    const updated = await this.prisma.extended.roles.update({
      where: { id },
      data: {
        isActive: false,
        lastChangedBy: deletedBy,
        lastChangedAt: new Date(),
        changedReason: reason || 'Rol eliminado',
      },
    });
    await this.permissionsCache.invalidateAll();
    return updated;
  }

  async hardDelete(id: number): Promise<Roles> {
    return await this.prisma.extended.roles.delete({ where: { id } });
  }

  async findByIdWithPermissions(id: number) {
    return await this.prisma.extended.roles.findUnique({
      where: { id },
      include: {
        rolePermissions: {
          where: { permission: { isActive: true } },
          include: { permission: true },
        },
      },
    });
  }

  async countByStatus(): Promise<{
    total: number;
    active: number;
    inactive: number;
  }> {
    const [total, active] = await Promise.all([
      this.prisma.extended.roles.count(),
      this.prisma.extended.roles.count({ where: { isActive: true } }),
    ]);
    return { total, active, inactive: total - active };
  }

  async existsByName(name: string, excludeId?: number): Promise<boolean> {
    const where: Prisma.RolesWhereInput = { name };
    if (excludeId) where.id = { not: excludeId };
    const count = await this.prisma.extended.roles.count({ where });
    return count > 0;
  }

  async hasUsers(roleId: number): Promise<boolean> {
    const count = await this.prisma.extended.userRoles.count({
      where: { roleId },
    });
    return count > 0;
  }

  // ─── Business logic ───────────────────────────────────────────────────────

  async createRole(data: {
    name: string;
    description?: string;
    createdBy: string;
  }): Promise<Roles> {
    const exists = await this.existsByName(data.name);
    if (exists) throw new ConflictException(`El rol "${data.name}" ya existe.`);
    return await this.create(data);
  }

  async getRoleById(id: number): Promise<Roles> {
    const role = await this.findById(id);
    if (!role) throw new NotFoundException(`Rol con ID ${id} no encontrado.`);
    return role;
  }

  async getRoleWithPermissions(id: number) {
    const role = await this.findByIdWithPermissions(id);
    if (!role) throw new NotFoundException(`Rol con ID ${id} no encontrado.`);
    return role;
  }

  async getAllRoles(query: GetRoleListQueryDTO): Promise<Roles[]> {
    return this.findAll(query);
  }

  async getRolesStats() {
    return this.countByStatus();
  }

  async updateRole(
    id: number,
    data: {
      name?: string;
      description?: string;
      isActive?: boolean;
      lastChangedBy: string;
      changedReason?: string;
    },
  ): Promise<Roles> {
    await this.getRoleById(id);

    if (data.name) {
      const exists = await this.existsByName(data.name, id);
      if (exists)
        throw new ConflictException(`El rol "${data.name}" ya existe.`);
    }

    return await this.update(id, data);
  }

  async deleteRole(
    id: number,
    deletedBy: string,
    reason?: string,
  ): Promise<Roles> {
    await this.getRoleById(id);

    const usersAssigned = await this.hasUsers(id);
    if (usersAssigned) {
      throw new BadRequestException(
        'No se puede eliminar el rol porque tiene usuarios asignados. Desactívalo en su lugar.',
      );
    }

    return await this.softDelete(id, deletedBy, reason);
  }

  async assignPermissionsToRole(data: {
    roleId: number;
    permissionIds: number[];
    createdBy: string;
  }) {
    await this.getRoleById(data.roleId);
    return await this.rolePermissionsDBService.assignPermissionsToRole(data);
  }

  async getRolePermissions(roleId: number) {
    await this.getRoleById(roleId);
    return await this.rolePermissionsDBService.getPermissionsByRoleId(roleId);
  }

  async removePermissionFromRole(
    roleId: number,
    permissionId: number,
    removedBy: string,
  ): Promise<void> {
    await this.getRoleById(roleId);
    await this.rolePermissionsDBService.removePermissionFromRole(
      roleId,
      permissionId,
      removedBy,
    );
  }
}

import { Injectable } from '@nestjs/common';
import {
  PermissionResponseDTO,
  RoleResponseDTO,
} from '@api/roles-permission/dtos/response';

interface IRolePermission {
  id: number;
  name: string;
  displayName: string | null;
  description: string | null;
