import {
  Inject,
  Injectable,
  Logger,
  OnApplicationShutdown,
  OnModuleInit,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import * as Sentry from '@sentry/nestjs';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import type {
  IExceptionContext,
  IExceptionReporter,
} from './exception-reporter.interface';
import { formatPayload } from './payload-formatter';
import { redactDeep } from './redaction';

const FLUSH_TIMEOUT_MS = 2000;
/** Tope del mapa de dedupe: evita crecer sin límite con errores siempre distintos. */
const MAX_TRACKED_FINGERPRINTS = 500;

/**
 * Patrón: Adapter opcional sobre @sentry/nestjs (implementa `IExceptionReporter`). Sin
 * `SENTRY_DSN` no inicializa el SDK y `captureException` es un no-op: la app arranca igual.
 * PII: body/query pasan por `formatPayload` y todo el evento por `redactDeep` (la MISMA política
 * que los logs, DRY) en `beforeSend`; no se envían cookies, headers sin redactar ni IP.
 * Dedupe: el mismo error (fingerprint) no se reenvía dentro de la ventana configurada, para que
 * un error en bucle no agote la cuota del proveedor.
 */
@Injectable()
export class SentryReporterService
  implements IExceptionReporter, OnModuleInit, OnApplicationShutdown
{
  private readonly logger = new Logger(SentryReporterService.name);
  private readonly lastSentAt = new Map<string, number>();
  private initialized = false;

  constructor(
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  onModuleInit(): void {
    const { sentryDsn } = this.config.observability;
    if (!sentryDsn) {
      this.logger.log('SENTRY_DSN no configurado: reporte de errores apagado');
      return;
    }

    Sentry.init({
      dsn: sentryDsn,
      environment: this.config.env,
      release: this.config.project.version,
      // Solo error tracking: sin tracing de performance y sin recolección automática de PII
      // (usuario, cookies, headers, bodies, query); el contexto útil lo adjunta captureException.
      tracesSampleRate: 0,
      dataCollection: {
        userInfo: false,
        cookies: false,
        httpHeaders: false,
        httpBodies: [],
        urlQueryParams: false,
      },
      beforeSend: (event) => this.beforeSend(event),
    });
    this.initialized = true;
    this.logger.log('Sentry inicializado');
  }

  async onApplicationShutdown(): Promise<void> {
    if (this.initialized) await Sentry.flush(FLUSH_TIMEOUT_MS);
  }

  isEnabled(): boolean {
    return this.initialized;
  }

  /** Nunca lanza: un fallo al reportar no debe tapar la respuesta de error real. */
  captureException(exception: unknown, context: IExceptionContext = {}): void {
    if (!this.initialized) return;

    try {
      Sentry.withScope((scope) => {
        if (context.traceId) scope.setTag('traceId', context.traceId);
        if (context.method) scope.setTag('http.method', context.method);
        if (context.route) scope.setTag('http.route', context.route);
        if (context.userId !== undefined) {
          scope.setUser({ id: String(context.userId) });
        }
        scope.setContext('request', {
          body: formatPayload(context.body),
          query: formatPayload(context.query),
        });
        Sentry.captureException(exception);
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      this.logger.error(`No se pudo reportar a Sentry | ${message}`);
    }
  }

  private fingerprint(event: Sentry.ErrorEvent): string {
    const value = event.exception?.values?.[0];
    const frames = value?.stacktrace?.frames;
    const top = frames?.[frames.length - 1];
    return `${value?.type ?? 'Error'}:${value?.value ?? ''}:${top?.filename ?? ''}:${top?.lineno ?? ''}`;
  }

  private beforeSend(event: Sentry.ErrorEvent): Sentry.ErrorEvent | null {
    const windowMs = this.config.observability.sentryDedupeWindowSeconds * 1000;
    const key = this.fingerprint(event);
    const now = Date.now();
    const last = this.lastSentAt.get(key);
    if (windowMs > 0 && last !== undefined && now - last < windowMs) {
      return null;
    }
    this.lastSentAt.set(key, now);
    if (this.lastSentAt.size > MAX_TRACKED_FINGERPRINTS)
      this.prune(now, windowMs);
    return this.scrub(event);
  }

  private prune(now: number, windowMs: number): void {
    for (const [key, at] of this.lastSentAt) {
      if (now - at >= windowMs) this.lastSentAt.delete(key);
    }
  }

  /** Quita/redacta todo lo que pueda llevar PII antes de que el evento salga del proceso. */
  private scrub(event: Sentry.ErrorEvent): Sentry.ErrorEvent {
    if (event.request) {
      delete event.request.cookies;
      event.request.headers = redactDeep(event.request.headers) as Record<
        string,
        string
      >;
      event.request.data = redactDeep(event.request.data);
    }
    if (event.user) event.user = { id: event.user.id };
    if (event.extra) {
      event.extra = redactDeep(event.extra) as Record<string, unknown>;
    }
    if (event.contexts) {
      event.contexts = redactDeep(event.contexts) as typeof event.contexts;
    }
    return event;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import {
  BulkCreateOptions,
  CreateOptions,
  CreationAttributes,
  FindOptions,
  Model, // Usamos Model para los métodos de instancia
  ModelStatic, // Usamos ModelStatic para los métodos estáticos
  Transaction,
  UpdateOptions,
  WhereOptions,
} from '@sequelize/core';
import { DatabaseConnections } from '@core/database/enum/database.enum';
import { SequelizeService } from '@core/database/services/sequelize.service';

/**
 * Interfaz base para los atributos de cualquier entidad de Sequelize.
 * Extiende para añadir los campos específicos de tu modelo.
 *
 * @template EntityPK El tipo de la clave primaria (e.g., number | string).
 */
export interface ISequelizeBaseAttributes<
  EntityPK extends number | string = number,
> {
  id?: EntityPK;
  // Puedes añadir aquí atributos comunes como createdAt, updatedAt, etc.
  [key: string]: unknown;
}

/**
 * Opciones reutilizables para los métodos del repositorio.
 */
export type ISequelizeRepositoryOptions = {
  transaction?: Transaction;
  attributes?: FindOptions['attributes'];
  logging?: boolean;
};

/**
 * Clase base (abstracta) para todos los repositorios.
 * Implementa la lógica CRUD genérica para cualquier modelo de Sequelize.
 *
 * @template TModel La clase del Modelo de Sequelize (ej: PromotionWalletEntity).
 * @template TAttributes La Interfaz de Atributos del modelo (ej: IPromotionWalletAttributes).
 * @template TPK El tipo de la clave primaria (ej: number | string).
 */
@Injectable()
export abstract class SequelizeBaseRepository<
  TModel extends Model, // La instancia del modelo (para tipar el retorno de findOne/createOne)
  TAttributes extends ISequelizeBaseAttributes, // La interfaz de atributos para create/update
  TPK extends number | string = number, // El tipo de la clave primaria
> {
  // ModelStatic<TModel> es el constructor del modelo (los métodos estáticos: create, findOne, etc.)
  protected model: ModelStatic<TModel>;

  // El constructor debe recibir el modelo específico a través de inyección
  // Esto obliga a las clases hijas a definir su constructor correctamente.
  constructor(
    @Inject(DatabaseConnections.DEFAULT)
    private readonly dbService: SequelizeService,
    // El modelo (clase estática) DEBE ser inyectado por la clase hija
    // con un parámetro con nombre genérico, p. ej., 'entityModel'.
    model: ModelStatic<TModel>,
  ) {
    this.model = model;
  }

  // --- Métodos de utilidad ---

  /**
   * Obtiene la instancia de Sequelize Service.
   */
  getInstance(): SequelizeService {
    return this.dbService;
  }

  /**
   * Ejecuta una transacción wrapper usando la instancia de Sequelize.
   */
  async transaction<T>(fn: (tx: Transaction) => Promise<T>): Promise<T> {
    return this.dbService.getInstance().transaction(fn);
  }

  // --- MÉTODOS CRUD GENÉRICOS ---

  /**
   * Encuentra un registro por criterios (where).
   */
  async findOne(
    where: WhereOptions<TAttributes>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<TModel | null> {
    const findOptions: FindOptions = {
      where,
      attributes: options.attributes,
      transaction: options.transaction,
      logging: false,
    };
    // El método findOne devuelve una instancia del modelo TModel
    return this.model.findOne(findOptions);
  }

  /**
   * Encuentra varios registros con paginación simple.
   */
  async findAll(
    where: WhereOptions<TAttributes> = {},
    opts: {
      limit?: number;
      offset?: number;
      order?: FindOptions['order'];
      attributes?: ISequelizeRepositoryOptions['attributes'];
      /** Relaciones a cargar (p. ej. un BelongsTo; un HasMany inflaría el count y exigiría `distinct`). */
      include?: FindOptions['include'];
      transaction?: Transaction;
      logging?: boolean;
    } = {},
  ): Promise<{ rows: TModel[]; count: number }> {
    const findOptions: FindOptions = {
      where,
      limit: opts.limit,
      offset: opts.offset,
      order: opts.order,
      attributes: opts.attributes,
      include: opts.include,
      transaction: opts.transaction,
      logging: false,
    };
    // Se castea findOptions al tipo correcto para findAndCountAll
    return this.model.findAndCountAll(findOptions as FindOptions<TAttributes>);
  }

  /**
   * Crea un registro.
   */
  async createOne(
    payload: TAttributes,
    options: CreateOptions = {},
  ): Promise<TModel> {
    // Retorna la instancia del modelo TModel
    return this.model.create(payload, options);
  }

  /**
   * Crea múltiples registros en bulk.
   */
  async bulkCreate(
    payloads: TAttributes[],
    options: BulkCreateOptions = {},
  ): Promise<TModel[]> {
    return this.model.bulkCreate(
      payloads as CreationAttributes<TModel>[],
      options,
    );
  }

  /**
   * Actualiza un registro identificado por where y devuelve el registro actualizado.
   */
  async updateOne(
    where: WhereOptions<TAttributes>,
    values: Partial<TAttributes>,
    options: {
      transaction?: Transaction;
      returning?: boolean;
      logging?: boolean;
    } = {},
  ): Promise<TModel | null> {
    const updateOptions: UpdateOptions = {
      where,
      transaction: options.transaction,
      logging: options.logging,
      returning: options.returning,
    } as UpdateOptions;

    await this.model.update(values, updateOptions);

    // Recuperamos el registro actualizado.
    return this.model.findOne({ where, transaction: options.transaction });
  }

  /**
   * Actualiza múltiples registros que coincidan con where. Devuelve número de filas afectadas.
   */
  async bulkUpdate(
    where: WhereOptions<TAttributes>,
    values: Partial<TAttributes>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<number> {
    const updateOptions: UpdateOptions = {
      where,
      transaction: options.transaction,
    };
    const [affectedCount] = await this.model.update(values, updateOptions);
    return typeof affectedCount === 'number' ? affectedCount : 0;
  }

  /**
   * Actualiza en bulk diferentes payloads por ID (asume 'id' como Primary Key).
   */
  async bulkUpdateByIds(
    items: Array<{
      id: TPK;
      values: Partial<TAttributes>;
    }>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<void> {
    const runInTransaction = async (transaction: Transaction) => {
      for (const it of items) {
        await this.model.update(it.values, {
          where: { id: it.id } as WhereOptions<TAttributes>,
          transaction,
        });
      }
    };

    if (options.transaction) {
      await runInTransaction(options.transaction);
    } else {
      await this.transaction(runInTransaction);
    }
  }

  /**
   * Elimina (hard delete) registros que cumplan where.
   */
  async delete(
    where: WhereOptions<TAttributes>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<number> {
    return this.model.destroy({ where, transaction: options.transaction });
  }

  /**
   * Cuenta registros que cumplan where.
   */
  async count(
    where: WhereOptions<TAttributes> = {},
    options: ISequelizeRepositoryOptions = {},
  ): Promise<number> {
    const result = await this.model.count({
      where,
      transaction: options.transaction,
    });

    return result || 0;
  }

  /**
   * Metodo que retorna datos de la entidad por PK
   * @param id Id de la entidad
   * @returns Retorna datos de la entidad
   */
  async findByPk(id: TPK): Promise<TModel | null> {
    return await this.model.findByPk(id);
  }
}

import { Logger, Injectable } from '@nestjs/common';
import {
  WhereOptions,
  Transaction,
  CreateOptions,
  BulkCreateOptions,
} from '@sequelize/core';
import { Model } from '@sequelize/core';
// Importamos las interfaces y la clase base del repositorio
import {
  ISequelizeBaseAttributes,
  ISequelizeRepositoryOptions,
  SequelizeBaseRepository,
} from '@core/database/base/sequelize/sequelize-base.repository';

/**
 * Service base (abstracto) para todos los módulos.
 * Implementa la lógica de negocio CRUD simple y manejo de logs/transacciones.
 *
 * @template TModel La clase del Modelo de Sequelize (ej: PromotionWalletEntity).
 * @template TAttributes La Interfaz de Atributos del modelo (ej: IPromotionWalletAttributes).
 * @template TRepository La clase del Repository específico (ej: PromotionWalletRepository).
 */
@Injectable()
export abstract class SequelizeBaseService<
  TModel extends Model,
  TAttributes extends ISequelizeBaseAttributes,
  TRepository extends SequelizeBaseRepository<
    TModel,
    TAttributes,
    number | string
  >, // TRepository extiende el BaseRepository con los tipos correctos
> {
  // El logger se tipa con el nombre de la clase hija para logs limpios
  protected readonly logger: Logger;

  // Inyectamos el repositorio específico a través del constructor (clase hija)
  constructor(protected readonly repository: TRepository) {
    // Inicializamos el logger con el nombre de la clase que extiende
    this.logger = new Logger(this.constructor.name);
  }

  // --- Métodos de Transacción y Utilidad ---

  /**
   * Wrapper de transacción para lógica de negocio compleja.
   */
  async transaction<T>(fn: (tx: Transaction) => Promise<T>): Promise<T> {
    return this.repository.transaction(fn);
  }

  // --- MÉTODOS CRUD GENÉRICOS ---

  /**
   * Busca un registro por criterios.
   */
  async findOne(
    where: WhereOptions<TAttributes>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<TModel | null> {
    this.logger.warn(
      `Operation: [findOne] Buscando registro con where: ${JSON.stringify(where)}`,
    );
    return this.repository.findOne(where, options);
  }

  /**
   * Busca todos los registros con paginación.
   */
  async findAll(
    where: WhereOptions<TAttributes> = {},
    opts: Parameters<TRepository['findAll']>[1] = {},
  ): Promise<{ rows: TModel[]; count: number }> {
    this.logger.warn(
      `Operation: [findAll] Buscando registros con where: ${JSON.stringify(where)}`,
    );
    return this.repository.findAll(where, opts);
  }

  /**
   * Crea un único registro.
   */
  async createOne(
    payload: TAttributes,
    options: CreateOptions = {},
  ): Promise<TModel> {
    this.logger.warn(`Operation: [createOne] Creando nuevo registro.`);
    return this.repository.createOne(payload, options);
  }

  /**
   * Crea múltiples registros de manera masiva (bulk).
   */
  async bulkCreate(
    payloads: TAttributes[],
    options: BulkCreateOptions = {},
  ): Promise<TModel[]> {
    this.logger.warn(
      `Operation: [bulkCreate] Creando ${payloads.length} registros en bulk.`,
    );
    return this.repository.bulkCreate(payloads, options);
  }

  /**
   * Actualiza registros que coincidan con la cláusula 'where' y devuelve el número de filas afectadas.
   */
  async update(
    values: Partial<TAttributes>,
    options: { where: WhereOptions<TAttributes>; transaction?: Transaction },
  ): Promise<number> {
    if (!options.where) {
      throw new Error(
        'La cláusula where es requerida para el método update en el servicio.',
      );
    }

    this.logger.warn(
      `Operation: [update] Actualizando con where: ${JSON.stringify(options.where)}`,
    );

    // Delega al bulkUpdate del repositorio para obtener el conteo de filas afectadas
    return this.repository.bulkUpdate(options.where, values, {
      transaction: options.transaction,
    });
  }

  /**
   * Elimina registros.
   */
  async delete(
    where: WhereOptions<TAttributes>,
    options: ISequelizeRepositoryOptions = {},
  ): Promise<number> {
    this.logger.warn(
      `Operation: [delete] Eliminando registros con criterios: ${JSON.stringify(where)}`,
    );
    return this.repository.delete(where, options);
  }

  /**
   * Metodo que retorna la entidad por PK
   * @param id De la entidad a retornar
   * @returns Entidad
   */
  async findByPk(id: number | string): Promise<TModel | null> {
    return await this.repository.findByPk(id);
  }
}

import { Injectable, OnModuleDestroy } from '@nestjs/common';
import Sequelize, {
  ManagedTransactionOptions,
  ModelStatic,
  Transaction,
  TransactionOptions,
} from '@sequelize/core';
import { IBMiDialect } from '@sequelize/db2-ibmi';
import { PostgresDialect } from '@sequelize/postgres';
import { AppConnectionOptions } from '../database';
import { withQueryTimeout } from '../helpers/db2-connection-string.helper';

/** Callback de una transacción administrada. */
export type TransactionFn<T> = (tx: Transaction) => PromiseLike<T> | T;

/** Defaults del pool DB2 (el de Sequelize, max 5, se satura bajo carga concurrente). */
export const DEFAULT_DB2_POOL = {
  max: 10,
  min: 2,
  acquire: 30000,
  idle: 10000,
} as const;

/**
 * Patrón: Facade sobre la instancia de Sequelize (una por conexión nombrada). Centraliza la
 * configuración del pool, el QueryTimeout y las transacciones.
 *
 * COMMITMENT CONTROL (IBM i): una transacción de Sequelize solo cubre lo que corre con `COMMIT=*CHG`
 * y sobre tablas journaled. Un SP `*NONE` escribe fuera de la transacción y NO se revierte con ella:
 * llamarlo post-commit y sin `transaction`. Un SP `*CHG` dentro de la tx arrastra todo lo anterior
 * con su COMMIT/ROLLBACK. Una tabla sin journal falla con SQL7008 al usar commitment control.
 */
@Injectable()
export class SequelizeService implements OnModuleDestroy {
  private sequelize: Sequelize;
  private models: ModelStatic[] = [];

  constructor(private readonly options: AppConnectionOptions) {
    this.sequelize = this.initInstance(options);
    options.registerHooks?.(options.models ?? []);
  }

  private initInstance({ type, options, models }: AppConnectionOptions) {
    switch (type) {
      case 'db2':
        return new Sequelize({
          dialect: IBMiDialect,
          odbcConnectionString: withQueryTimeout(
            options.odbcConnectionString,
            options.queryTimeoutSec,
          ),
          connectionTimeout: 60,
          // Cada conexión del pool es un job en el servidor IBM i: coordinar con el sysadmin
          // antes de subir `max` (DB2_POOL_MAX).
          pool: { ...DEFAULT_DB2_POOL, ...options.pool },
          models,
        });
      case 'postgres':
        return new Sequelize({
          dialect: PostgresDialect,
          host: options.host,
          user: options.user,
          password: options.password,
          database: options.database,
          models,
        });
      default:
        throw new Error('Invalid connection type (db2 | postgres)');
    }
  }

  async onModuleDestroy() {
    const result = await this.sequelize.close();
    console.log('connection closed ', result);
  }

  getInstance(): Sequelize {
    return this.sequelize;
  }

  /**
   * Transacción administrada: commit al resolver `fn`, rollback si lanza. Preferirla sobre la manual.
   * `options.isolationLevel` se pasa tal cual al dialecto (el soporte depende del release de IBM i).
   */
  async transaction<T>(
    fn: TransactionFn<T>,
    options?: ManagedTransactionOptions,
  ): Promise<T> {
    return options
      ? this.sequelize.transaction(options, fn)
      : this.sequelize.transaction(fn);
  }

  /**
   * Transacción no administrada: quien la abre es responsable de `commit()`/`rollback()`.
   * Los repositorios reciben la `Transaction` por parámetro, nunca la abren.
   */
  async beginTransaction(options?: TransactionOptions): Promise<Transaction> {
    return this.sequelize.startUnmanagedTransaction(options);
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { AdvisoryLockId } from '@core/scheduler/advisory-lock-id.enum';
import { ScheduledJob, SchedulerCronKey } from '@core/scheduler/scheduled-job';
import { MessageDBService } from '@modules/message-db/services/message-db.service';
import { SmsUnavailableError } from '@modules/sms/errors/sms.errors';
import {
  IDeliveryStatusSource,
  SMS_DELIVERY_SOURCE,
} from '@modules/sms/interfaces/delivery-status-source.interface';
import {
  PENDING_PROVIDER_STATUSES,
  PROVIDER_STATUS_TO_MESSAGE_STATUS,
} from '../constants/sms-status-map.constant';

/**
 * Polling de estado de entrega de SMS. Vive en `api/` porque orquesta dos módulos (fuente de
 * entrega + ledger). Sin fuente (`SMS_DELIVERY_SOURCE=off`) el job ni se registra. Mapea el estado
 * del proveedor al enum del ledger; un proveedor caído solo se loguea y se reintenta en el próximo ciclo.
 */
@Injectable()
export class SmsDeliveryPollJob extends ScheduledJob {
  readonly name = 'sms-delivery-poll';
  readonly cronConfigKey: SchedulerCronKey = 'smsDeliveryPoll';
  readonly lockId = AdvisoryLockId.SmsDeliveryPoll;

  constructor(
    @Inject(SMS_DELIVERY_SOURCE)
    private readonly source: IDeliveryStatusSource | null,
    private readonly messages: MessageDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {
    super();
  }

  override isEnabled(): boolean {
    return this.source !== null;
  }

  async run(): Promise<void> {
    if (!this.source) return;

    const pending = await this.messages.findSmsAwaitingDelivery(
      this.config.sms.deliveryPollLimit,
    );
    if (pending.length === 0) return;

    let reports;
    try {
      reports = await this.source.fetchReports(
        pending.map((m) => m.providerMessageId as string),
      );
    } catch (error) {
      if (error instanceof SmsUnavailableError) {
        this.logger.warn(
          'Proveedor SMS inalcanzable, se reintenta en el próximo ciclo',
        );
        return;
      }
      throw error;
    }

    for (const report of reports) {
      if (PENDING_PROVIDER_STATUSES.has(report.providerStatus)) continue;

      const status = PROVIDER_STATUS_TO_MESSAGE_STATUS[report.providerStatus];
      if (!status) {
        this.logger.warn(
          `Estado de proveedor no reconocido, se ignora: ${report.providerStatus}`,
        );
        continue;
      }
      await this.messages.applyDeliveryStatus(
        report.messageId,
        status,
        report.providerStatus,
        report.errorDescription,
      );
    }
  }
}

import { Inject, Injectable } from '@nestjs/common';
import {
  HealthIndicatorResult,
  HealthIndicatorService,
} from '@nestjs/terminus';
import {
  EMAIL_SENDER,
  IEmailSender,
} from '../interfaces/email-sender.interface';

/**
 * Indicador INFORMATIVO: se expone en la respuesta del healthcheck pero NO participa de
 * `HealthCheckService.check`, así un SMTP caído no marca al servicio entero como no saludable
 * (el correo es una dependencia degradable, no crítica).
 */
@Injectable()
export class SmtpHealthIndicator {
  constructor(
    private readonly healthIndicatorService: HealthIndicatorService,
    @Inject(EMAIL_SENDER) private readonly sender: IEmailSender,
  ) {}

  check(): HealthIndicatorResult<'smtp'> {
    const session = this.healthIndicatorService.check('smtp');
    return this.sender.isAvailable()
      ? session.up({ provider: this.sender.provider })
      : session.down({
          provider: this.sender.provider,
          message: 'SMTP no disponible',
        });
  }
}

import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { StorageService } from '@modules/storage/services/storage.service';
import { StorageUploadInput } from '@modules/storage/interfaces/storage.interface';
import {
  HttpException,
  Injectable,
  InternalServerErrorException,
} from '@nestjs/common';
import {
  IUploadFileParams,
  IUploadedFileUrls,
} from './interfaces/storage.interface';

@Injectable()
export class StorageApiService {
  constructor(
    private readonly storageService: StorageService,
    private readonly usersDb: UsersDBService,
  ) {}

  async uploadFile(params: IUploadFileParams): Promise<void> {
    const { files, userId, referenceId, documentType, documentNumber } = params;

    await this.uploadFilesToStorage(files, referenceId, 1);
    await this.usersDb.updateDocument(Number(userId), {
      documentNumber,
      documentType,
    });
  }

  private async uploadFilesToStorage(
    files: IUploadFileParams['files'],
    referenceId: string,
    applicationId: number,
  ): Promise<IUploadedFileUrls> {
    try {
      const uploadInputs = this.buildUploadInputs(
        files,
        referenceId,
        applicationId,
      );
      const uploadedFiles =
        await this.storageService.uploadFilesQueue(uploadInputs);

      return uploadedFiles.reduce<IUploadedFileUrls>((accumulator, file) => {
        if (file.id) {
          accumulator[file.id as keyof IUploadedFileUrls] = file.key;
        }

        return accumulator;
      }, {});
    } catch (error) {
      if (error instanceof HttpException) {
        throw error;
      }

      throw new InternalServerErrorException(
        'Failed to upload files to storage',
        { cause: error },
      );
    }
  }

  private buildUploadInputs(
    files: IUploadFileParams['files'],
    referenceId: string,
    applicationId: number,
  ): StorageUploadInput[] {
    return Object.entries(files).flatMap(([fieldName, fileGroup]) =>
      fileGroup.map((file) => ({
        id: fieldName,
        file,
        path: `onboarding/tenants/${referenceId}/${applicationId}`,
      })),
    );
  }
}

import {
  PutObjectCommand,
  S3Client,
  DeleteObjectCommand,
  GetObjectCommand,
  PutObjectCommandOutput,
  DeleteObjectCommandOutput,
} from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
import {
  BadRequestException,
  Inject,
  Injectable,
  ServiceUnavailableException,
} from '@nestjs/common';
import { STORAGE_MODULE_OPTIONS } from '../interfaces/storage.interface';
import type {
  StorageExecutionOptions,
  StorageModuleOptions,
  StoragePresignedUrlOptions,
  StoragePresignedUrlResult,
  StorageUploadInput,
  StorageUploadResult,
} from '../interfaces/storage.interface';
import { AsyncManager } from '@common/helpers/async-manager';
import { ProcessBatchManager } from '@common/helpers/process-batch';
import { StorageHelper } from '../helpers/storage.helper';
import { DeleteFileTarget, PresignedUrlTarget } from '../types/storage.types';

@Injectable()
export class StorageService {
  private readonly manager: AsyncManager;
  private readonly urlCache = new Map<
    string,
    { url: string; expires: number }
  >();

  constructor(
    private readonly s3: S3Client,
    @Inject(STORAGE_MODULE_OPTIONS)
    private readonly options: StorageModuleOptions,
  ) {
    this.manager = new AsyncManager(this.options.maxConcurrency || 5);
  }

  async uploadFilesQueue(
    files: StorageUploadInput[],
  ): Promise<StorageUploadResult[]> {
    if (!files.length) {
      throw new BadRequestException('At least one file is required');
    }

    const uploadPromises = files.map(async (fileInput) => {
      const key = StorageHelper.resolveUploadKey(fileInput);
      const bucket = fileInput.bucket ?? this.options.defaultBucket;

      await this.uploadQueue({
        file: fileInput.file.buffer,
        key: key,
        mimetype: fileInput.contentType ?? fileInput.file.mimetype,
        bucket: bucket,
      });

      return {
        key,
        bucket,
        id: fileInput.id,
      };
    });

    return Promise.all(uploadPromises);
  }

  /**
   * Método para cargar imagen
   * @param input Datos de la imagen: file, key, mimetype, bucket
   * @returns void
   */
  async uploadQueue(input: {
    file: Buffer;
    key: string;
    mimetype: string;
    bucket?: string;
  }): Promise<PutObjectCommandOutput> {
    return this.manager.enqueue(
      () =>
        this.s3.send(
          new PutObjectCommand({
            Bucket: input.bucket ?? this.options.defaultBucket,
            Key: input.key,
            Body: input.file,
            ContentType: input.mimetype,
          }),
        ),
      {
        attempts: this?.options?.retryAttempts ?? 3,
        delayMs: 1000,
        shouldRetry: (err) => StorageHelper.isRetryable(err),
      },
    );
  }

  /**
   * Método que tiene la url pre-firmada, soporta expiración variable y ser llamado por el queue.
   * @param target Archivo objetivo, contiene: key, bucket, userId
   * @returns string
   */
  async getPresignedUrlQueue(target: {
    key: string;
    bucket?: string;
    expiresIn?: number;
  }): Promise<string> {
    const bucket = target.bucket ?? this.options.defaultBucket;
    const expiresIn =
      target.expiresIn ?? this.options.presignedUrlExpiresInSeconds;

    const cacheKey = `${bucket}:${target.key}:${expiresIn}`;
    const now = Date.now();

    if (this.urlCache.has(cacheKey)) {
      const cached = this.urlCache.get(cacheKey)!;
      if (cached.expires > now + 60000) return cached.url;
    }

    return this.manager.enqueue(
      async () => {
        const url = await getSignedUrl(
          this.s3 as any,
          new GetObjectCommand({ Bucket: bucket, Key: target.key }) as any,
          { expiresIn },
        );

        this.urlCache.set(cacheKey, {
          url,
          expires: now + expiresIn * 1000,
        });

        return url;
      },
      { attempts: 2, delayMs: 500 },
    );
  }

  async getPresignedGetUrlsQueue(
    files: PresignedUrlTarget[],
    options?: StoragePresignedUrlOptions,
  ): Promise<StoragePresignedUrlResult[]> {
    if (!files.length) {
      throw new BadRequestException('At least one key is required');
    }

    const expiresInSeconds = StorageHelper.resolvePresignedUrlExpiresIn(
      options?.expiresInSeconds ?? this.options.presignedUrlExpiresInSeconds,
    );

    const urlPromises = files.map(async (fileInput) => {
      const normalizedFile =
        typeof fileInput === 'string' ? { key: fileInput } : fileInput;
      const key = StorageHelper.normalizeKey(normalizedFile.key, 'key');
      const bucket = normalizedFile.bucket ?? this.options.defaultBucket;

      const url = await this.getPresignedUrlQueue({
        key,
        bucket,
        expiresIn: expiresInSeconds,
      });

      return {
        key,
        bucket,
        url,
        id: normalizedFile.id,
      };
    });

    return Promise.all(urlPromises);
  }

  /**
   * Borra múltiples archivos del storage respetando la cola de concurrencia.
   * @param keys Array de llaves de los archivos
   * @param bucket Bucket (opcional)
   */
  async deleteFilesQueue(
    keys: string[],
    bucket?: string,
  ): Promise<DeleteObjectCommandOutput[]> {
    if (!keys.length) return [];

    const deletePromises = keys.map((key) => this.deleteQueue(key, bucket));

    return Promise.all(deletePromises);
  }

  /**
   * Borrado Seguro (Reemplazo/Update)
   * @param key Llave del archivo
   * @param bucket Bucket
   * @returns
   */
  async deleteQueue(
    key: string,
    bucket?: string,
  ): Promise<DeleteObjectCommandOutput> {
    return this.manager.enqueue(
      () =>
        this.s3.send(
          new DeleteObjectCommand({
            Bucket: bucket ?? this.options.defaultBucket,
            Key: key,
          }),
        ),
      {
        attempts: this.options.retryAttempts ?? 3,
        delayMs: 1000,
        shouldRetry: (err) => StorageHelper.isRetryable(err),
      },
    );
  }

  async uploadFilesBatch(
    files: StorageUploadInput[],
    executionOptions?: StorageExecutionOptions,
  ): Promise<StorageUploadResult[]> {
    if (!files.length) {
      throw new BadRequestException('At least one file is required');
    }

    const process = new ProcessBatchManager();

    const maxConcurrency = StorageHelper.resolvePositiveNumber(
      executionOptions?.maxConcurrency ?? this.options.maxConcurrency,
      'maxConcurrency',
    );

    return process.processInBatches(
      files,
      maxConcurrency,
      (fileInput): Promise<StorageUploadResult> =>
        this.uploadSingleFileBatch(fileInput, executionOptions),
    );
  }

  async deleteFilesBatch(
    files: DeleteFileTarget[],
    executionOptions?: StorageExecutionOptions,
  ): Promise<void> {
    if (!files.length) {
      throw new BadRequestException('At least one key is required');
    }
    const process = new ProcessBatchManager();

    const maxConcurrency = StorageHelper.resolvePositiveNumber(
      executionOptions?.maxConcurrency ?? this.options.maxConcurrency,
      'maxConcurrency',
    );

    await process.processInBatches(files, maxConcurrency, async (fileInput) => {
      const normalizedFile =
        typeof fileInput === 'string' ? { key: fileInput } : fileInput;
      const key = StorageHelper.normalizeKey(normalizedFile.key, 'key');
      const bucket = normalizedFile.bucket ?? this.options.defaultBucket;

      await process.executeWithRetry(
        () =>
          this.s3.send(
            new DeleteObjectCommand({
              Bucket: bucket,
              Key: key,
            }),
          ),
        executionOptions,
      );
    });
  }

  async deleteFileBatch(keys: string[]): Promise<void> {
    await this.deleteFilesBatch(keys);
  }

  async getPresignedGetUrlsBatch(
    files: PresignedUrlTarget[],
    options?: StoragePresignedUrlOptions,
  ): Promise<StoragePresignedUrlResult[]> {
    if (!files.length) {
      throw new BadRequestException('At least one key is required');
    }
    const process = new ProcessBatchManager();

    const maxConcurrency = StorageHelper.resolvePositiveNumber(
      options?.maxConcurrency ?? this.options.maxConcurrency,
      'maxConcurrency',
    );
    const expiresInSeconds = StorageHelper.resolvePresignedUrlExpiresIn(
      options?.expiresInSeconds,
    );

    return process.processInBatches(
      files,
      maxConcurrency,
      async (fileInput): Promise<StoragePresignedUrlResult> => {
        const normalizedFile =
          typeof fileInput === 'string' ? { key: fileInput } : fileInput;
        const key = StorageHelper.normalizeKey(normalizedFile.key, 'key');
        const bucket = normalizedFile.bucket ?? this.options.defaultBucket;
        const signerClient = this.s3 as unknown as Parameters<
          typeof getSignedUrl
        >[0];
        const getObjectCommand = new GetObjectCommand({
          Bucket: bucket,
          Key: key,
        }) as unknown as Parameters<typeof getSignedUrl>[1];

        const url = await getSignedUrl(signerClient, getObjectCommand, {
          expiresIn: expiresInSeconds,
        });

        return {
          key,
          bucket,
          url,
          id: normalizedFile.id,
        };
      },
    );
  }

  private async uploadSingleFileBatch(
    fileInput: StorageUploadInput,
    executionOptions?: StorageExecutionOptions,
  ): Promise<StorageUploadResult> {
    StorageHelper.validateFileInput(fileInput);
    const process = new ProcessBatchManager();

    const bucket = fileInput.bucket ?? this.options.defaultBucket;
    const key = StorageHelper.resolveUploadKey(fileInput);

    try {
      await process.executeWithRetry(
        () =>
          this.s3.send(
            new PutObjectCommand({
              Bucket: bucket,
              Key: key,
              Body: fileInput.file.buffer,
              ContentType: fileInput.contentType ?? fileInput.file.mimetype,
              ContentDisposition: fileInput.contentDisposition,
              Metadata: fileInput.metadata,
            }),
          ),
        executionOptions,
      );
    } catch (error) {
      throw new ServiceUnavailableException(
        'Storage service is temporarily unavailable',
        { cause: error },
      );
    }

    return {
      key,
      bucket,
      id: fileInput.id,
    };
  }
}

import { Injectable, NestMiddleware } from '@nestjs/common';
import { NextFunction, Request, Response } from 'express';
import { v4 as uuid } from 'uuid';
import { RequestContext } from '@common/context/request-context';

export const TRACE_ID_HEADER = 'X-Trace-Id';

// Solo caracteres seguros para logs/headers; evita inyección de líneas y payloads enormes.
const TRACE_ID_PATTERN = /^[A-Za-z0-9._:-]{8,64}$/;

export function resolveTraceId(incoming: unknown): string {
  const candidate = Array.isArray(incoming) ? incoming[0] : incoming;
  return typeof candidate === 'string' && TRACE_ID_PATTERN.test(candidate)
    ? candidate
    : uuid();
}

/**
 * Patrón: middleware de correlación. Acepta `X-Trace-Id` entrante si es válido (propaga la
 * traza entre servicios), si no genera uno; lo expone en request/response y en el
 * RequestContext (AsyncLocalStorage) para toda la cadena asíncrona del request.
 */
@Injectable()
export class TraceIdMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: NextFunction) {
    const traceId = resolveTraceId(req.headers[TRACE_ID_HEADER.toLowerCase()]);

    req[TRACE_ID_HEADER] = traceId;
    res.setHeader(TRACE_ID_HEADER, traceId);
    RequestContext.run({ traceId }, () => next());
  }
}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import {
  LegalDocumentType,
  LegalDocumentVersion,
  Prisma,
  UserConsent,
} from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { t } from '@common/i18n/i18n.helper';

export type UserConsentWithVersion = UserConsent & {
  documentVersion: LegalDocumentVersion;
};

export interface IAcceptConsent {
  userId: number;
  version: LegalDocumentVersion;
  ipAddress?: string;
  userAgent?: string;
}

/**
 * Registro de consentimientos. Solo se acepta la versión ACTIVA; revocar marca `revokedAt` (no
 * borra: la evidencia de qué aceptó el usuario y cuándo se conserva). Re-aceptar tras revocar
 * reactiva la misma fila (única por usuario+versión).
 */
@Injectable()
export class UserConsentsDBService {
  constructor(private readonly prisma: PrismaDatasource) {}

  /** ¿Tiene el usuario un consentimiento vigente (no revocado) de la versión ACTIVA del tipo? */
  async hasActiveConsent(
    userId: number,
    type: LegalDocumentType,
  ): Promise<boolean> {
    const count = await this.prisma.userConsent.count({
      where: {
        userId,
        revokedAt: null,
        documentVersion: { type, isActive: true },
      },
    });
    return count > 0;
  }

  async accept(input: IAcceptConsent): Promise<UserConsentWithVersion> {
    if (!input.version.isActive) {
      throw new ConflictException(t('legal.VERSION_NOT_ACTIVE'));
    }

    const key = {
      userId_documentVersionId: {
        userId: input.userId,
        documentVersionId: input.version.id,
      },
    };
    const existing = await this.prisma.userConsent.findUnique({ where: key });
    if (existing && existing.revokedAt === null) {
      throw new ConflictException(t('legal.ALREADY_ACCEPTED'));
    }

    const data = {
      acceptedAt: new Date(),
      revokedAt: null,
      ipAddress: input.ipAddress,
      userAgent: input.userAgent,
    };
    try {
      return await this.prisma.extended.userConsent.upsert({
        where: key,
        create: {
          ...data,
          userId: input.userId,
          documentVersionId: input.version.id,
          createdBy: String(input.userId),
        },
        update: { ...data, lastChangedBy: String(input.userId) },
        include: { documentVersion: true },
      });
    } catch (error) {
      // Carrera: dos aceptaciones simultáneas de la misma versión.
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new ConflictException(t('legal.ALREADY_ACCEPTED'));
      }
      throw error;
    }
  }

  /** Revoca los consentimientos vigentes del tipo. @returns cantidad revocada */
  async revoke(userId: number, type: LegalDocumentType): Promise<number> {
    const { count } = await this.prisma.extended.userConsent.updateMany({
      where: { userId, revokedAt: null, documentVersion: { type } },
      data: { revokedAt: new Date(), lastChangedBy: String(userId) },
    });
    if (count === 0) throw new NotFoundException(t('legal.CONSENT_NOT_FOUND'));
    return count;
  }

  listByUser(userId: number): Promise<UserConsentWithVersion[]> {
    return this.prisma.userConsent.findMany({
      where: { userId },
      include: { documentVersion: true },
      orderBy: { acceptedAt: 'desc' },
    });
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { UserPermissions } from '@prisma/client';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { PermissionsDBService } from './permissions-db.service';

@Injectable()
export class UserPermissionsDBService {
  private readonly logger = new Logger(UserPermissionsDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly usersDBService: UsersDBService,
    private readonly permissionsDBService: PermissionsDBService,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Raw DB ───────────────────────────────────────────────────────────────

  async assignPermissionsToUser(data: {
    userId: number;
    permissionIds: number[];
    createdBy: string;
  }): Promise<UserPermissions[]> {
    const result = await this.prisma.extended.$transaction(async (tx) => {
      const oldPermissions = await tx.userPermissions.findMany({
        where: { userId: data.userId },
        include: { permission: true },
      });

      await tx.auditLogs.create({
        data: {
          tableName: 'user_permissions',
          recordId: data.userId.toString(),
          operationType: 'UPDATE',
          oldData: oldPermissions,
          newData: { permissionIds: data.permissionIds },
          changedBy: data.createdBy,
        },
      });

      await tx.userPermissions.deleteMany({ where: { userId: data.userId } });

      if (data.permissionIds.length === 0) return [];

      await tx.userPermissions.createMany({
        data: data.permissionIds.map((permissionId) => ({
          userId: data.userId,
          permissionId,
          createdBy: data.createdBy,
        })),
        skipDuplicates: true,
      });

      return await tx.userPermissions.findMany({
        where: { userId: data.userId },
        include: { permission: true },
      });
    });
    await this.permissionsCache.invalidateAll();
    return result;
  }

  async getPermissionsByUserId(userId: number) {
    return await this.prisma.extended.userPermissions.findMany({
      where: { userId, permission: { isActive: true } },
      include: { permission: true },
    });
  }

  async removePermissionFromUser(
    userId: number,
    permissionId: number,
    removedBy: string,
  ): Promise<void> {
    await this.prisma.extended.$transaction(async (tx) => {
      await tx.auditLogs.create({
        data: {
          tableName: 'user_permissions',
          recordId: `${userId}-${permissionId}`,
          operationType: 'DELETE',
          oldData: { userId, permissionId },
          changedBy: removedBy,
        },
      });

      await tx.userPermissions.deleteMany({ where: { userId, permissionId } });
    });
    await this.permissionsCache.invalidateAll();
  }

  async userHasPermission(
    userId: number,
    permissionId: number,
  ): Promise<boolean> {
    const count = await this.prisma.extended.userPermissions.count({
      where: { userId, permissionId, permission: { isActive: true } },
    });
    return count > 0;
  }

  async getUsersByPermissionId(permissionId: number) {
    return await this.prisma.extended.userPermissions.findMany({
      where: { permissionId, user: { status: 'ACTIVE' } },
      include: { user: true },
    });
  }

  // ─── Business logic ───────────────────────────────────────────────────────

  async assignPermissionsToUserWithValidation(data: {
    userId: number;
    permissionIds: number[];
    createdBy: string;
  }): Promise<UserPermissions[]> {
    const user = await this.usersDBService.findById(data.userId);
    if (!user)
      throw new NotFoundException(
        `Usuario con ID ${data.userId} no encontrado.`,
      );

    if (data.permissionIds.length > 0) {
      const permissions = await this.permissionsDBService.findByIds(
        data.permissionIds,
      );
      if (permissions.length !== data.permissionIds.length) {
        const foundIds = permissions.map((p) => p.id);
        const missingIds = data.permissionIds.filter(
          (id) => !foundIds.includes(id),
        );
        throw new BadRequestException(
          `Los siguientes id's de permisos no existen o están inactivos: ${missingIds.join(', ')}`,
        );
      }
    }

    return await this.assignPermissionsToUser(data);
  }

  async getUserPermissions(userId: number) {
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${userId} no encontrado.`);
    return await this.getPermissionsByUserId(userId);
  }

  async removePermissionFromUserWithValidation(
    userId: number,
    permissionId: number,
    removedBy: string,
  ): Promise<void> {
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${userId} no encontrado.`);

    const hasPermission = await this.userHasPermission(userId, permissionId);
    if (!hasPermission) {
      throw new BadRequestException(
        `El usuario no tiene asignado el permiso con ID ${permissionId}.`,
      );
    }

    await this.removePermissionFromUser(userId, permissionId, removedBy);
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { UserRoles } from '@prisma/client';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { RolesDBService } from './roles-db.service';

@Injectable()
export class UserRolesDBService {
  private readonly logger = new Logger(UserRolesDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly usersDBService: UsersDBService,
    private readonly rolesDBService: RolesDBService,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Raw DB ───────────────────────────────────────────────────────────────

  async assignRolesToUser(data: {
    userId: number;
    roleIds: number[];
    createdBy: string;
  }): Promise<UserRoles[]> {
    const result = await this.prisma.extended.$transaction(async (tx) => {
      const oldRoles = await tx.userRoles.findMany({
        where: { userId: data.userId },
        include: { role: true },
      });

      await tx.auditLogs.create({
        data: {
          tableName: 'user_roles',
          recordId: data.userId.toString(),
          operationType: 'UPDATE',
          oldData: oldRoles,
          newData: { roleIds: data.roleIds },
          changedBy: data.createdBy,
        },
      });

      await tx.userRoles.deleteMany({ where: { userId: data.userId } });

      if (data.roleIds.length === 0) return [];

      await tx.userRoles.createMany({
        data: data.roleIds.map((roleId) => ({
          userId: data.userId,
          roleId,
          createdBy: data.createdBy,
        })),
        skipDuplicates: true,
      });

      return await tx.userRoles.findMany({
        where: { userId: data.userId },
        include: { role: true },
      });
    });
    await this.permissionsCache.invalidateAll();
    return result;
  }

  async getRolesByUserId(userId: number) {
    return await this.prisma.extended.userRoles.findMany({
      where: { userId, role: { isActive: true } },
      include: { role: true },
    });
  }

  async removeRoleFromUser(
    userId: number,
    roleId: number,
    removedBy: string,
  ): Promise<void> {
    await this.prisma.extended.$transaction(async (tx) => {
      await tx.auditLogs.create({
        data: {
          tableName: 'user_roles',
          recordId: `${userId}-${roleId}`,
          operationType: 'DELETE',
          oldData: { userId, roleId },
          changedBy: removedBy,
        },
      });

      await tx.userRoles.deleteMany({ where: { userId, roleId } });
    });
    await this.permissionsCache.invalidateAll();
  }

  async userHasRole(userId: number, roleId: number): Promise<boolean> {
    const count = await this.prisma.extended.userRoles.count({
      where: { userId, roleId, role: { isActive: true } },
    });
    return count > 0;
  }

  async getUsersByRoleId(roleId: number) {
    return await this.prisma.extended.userRoles.findMany({
      where: { roleId, user: { status: 'ACTIVE' } },
      include: { user: true },
    });
  }

  async countUsersByRole(roleId: number): Promise<number> {
    return await this.prisma.extended.userRoles.count({ where: { roleId } });
  }

  // ─── Business logic ───────────────────────────────────────────────────────

  async assignRolesToUserWithValidation(data: {
    userId: number;
    roleIds: number[];
    createdBy: string;
  }) {
    const user = await this.usersDBService.findById(data.userId);
    if (!user)
      throw new NotFoundException(
        `Usuario con ID ${data.userId} no encontrado.`,
      );

    if (data.roleIds.length > 0) {
      const roles = await Promise.all(
        data.roleIds.map((id) => this.rolesDBService.findById(id)),
      );
      const invalidRoles = data.roleIds.filter(
        (id, i) => !roles[i] || !roles[i].isActive,
      );
      if (invalidRoles.length > 0) {
        throw new NotFoundException(
          `Los siguientes roles no existen o están inactivos: ${invalidRoles.join(', ')}`,
        );
      }
    }

    return await this.assignRolesToUser(data);
  }

  async getUserRoles(userId: number) {
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${userId} no encontrado.`);
    return await this.getRolesByUserId(userId);
  }

  async getPermissionsFromUserRoles(userId: number) {
    const userRoles = await this.getUserRoles(userId);
    const roleIds = userRoles.map((ur) => ur.role.id);
    if (roleIds.length === 0) return [];

    const rolePermissions =
      await this.rolesDBService.getPermissionsByRoleIds(roleIds);
    return rolePermissions.map((rp) => ({
      roleId: rp.roleId,
      name: rp.permission.name,
      description: rp.permission.description,
    }));
  }

  async removeRoleFromUserWithValidation(
    userId: number,
    roleId: number,
    removedBy: string,
  ): Promise<void> {
    const user = await this.usersDBService.findById(userId);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${userId} no encontrado.`);

    const hasRole = await this.userHasRole(userId, roleId);
    if (!hasRole) {
      throw new BadRequestException(
        `El usuario no tiene asignado el rol con ID ${roleId}.`,
      );
    }

    await this.removeRoleFromUser(userId, roleId, removedBy);
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';

@Injectable()
export class UserRolesDBService {
  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  async getUserRoleIds(userId: number): Promise<number[]> {
    const userRoles = await this.prisma.extended.userRoles.findMany({
      where: { userId, isActive: true, role: { isActive: true } },
      select: { roleId: true },
    });
    return userRoles.map((ur) => ur.roleId);
  }

  async replaceUserRoles(
    userId: number,
    roleIds: number[],
    changedBy: string,
    tx?: any,
  ): Promise<void> {
    if (roleIds.length === 0) {
      throw new BadRequestException(
        'Debe asignarse al menos un rol al usuario.',
      );
    }

    if (roleIds.length > 1) {
      throw new BadRequestException(
        'Solo se permite asignar un rol por usuario.',
      );
    }

    const client = tx ?? this.prisma.extended;

    // Desactiva todos los roles actuales
    await client.userRoles.updateMany({
      where: { userId, isActive: true },
      data: {
        isActive: false,
        lastChangedBy: changedBy,
        lastChangedAt: new Date(),
      },
    });

    // Upsert: reactivar si ya existía el par userId+roleId, crear si no
    await client.userRoles.upsert({
      where: {
        userId_roleId: { userId, roleId: roleIds[0] },
      },
      update: {
        isActive: true,
        lastChangedBy: changedBy,
        lastChangedAt: new Date(),
      },
      create: {
        userId,
        roleId: roleIds[0],
        createdBy: changedBy,
        isActive: true,
      },
    });
    // Si el caller usa una tx, la ventana hasta el commit queda acotada por el TTL del cache.
    await this.permissionsCache.invalidateAll();
  }

  async getAllAvailableRoles(): Promise<
    {
      id: number;
      name: string;
      displayName: string | null;
      description: string | null;
    }[]
  > {
    return this.prisma.extended.roles.findMany({
      where: { isActive: true },
      select: { id: true, name: true, displayName: true, description: true },
      orderBy: { name: 'asc' },
    });
  }
}

import { Injectable } from '@nestjs/common';
import { UserStatus } from '@prisma/client';
import { UpdateUserRequestDTO } from '@api/users/dtos/request/update-user.request.dto';
import { ListUsersRequestDTO } from '@api/users/dtos/request/list-users.request.dto';
import { BlockUserRequestDTO } from '@api/users/dtos/request/block-user.request.dto';
import { UnblockUserRequestDTO } from '@api/users/dtos/request/unblock-user.request.dto';
import { UpdateEditContextRequestDTO } from '@modules/users-db/dtos/edit-context.request.dto';
import {
  UserResponseDTO,
  UserDetailResponseDTO,
  UsersListResponseDTO,
} from '@api/users/dtos/response/user.response.dto';
import {
  EditContextRoleDTO,
  GetEditContextResponseDTO,
  UpdateEditContextResponseDTO,
} from '@api/users/dtos/response/edit-context.response.dto';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { ITenantContext } from '@common/interfaces/tenant-context.interface';
import { UserRolesDBService } from '@modules/users-db/services/user-roles-db.service';
import { UserHelper } from '../helpers/user.helper';
import { IUserDataOnJwt } from '@modules/auth/interfaces/user-data-on-jwt.interface';

@Injectable()
export class UsersApiService {
  constructor(
    private readonly usersService: UsersDBService,
    private readonly userRolesDBService: UserRolesDBService,
  ) {}

  async findAll(
    dto: ListUsersRequestDTO,
    tenantCtx: ITenantContext,
    user: IUserDataOnJwt,
  ): Promise<UsersListResponseDTO> {
    const page = Number(dto.page ?? 1);
    const pageSize = Number(dto.pageSize ?? 10);
    const orderBy = String(dto.orderBy ?? 'createdAt');
    const orderDir: 'asc' | 'desc' = dto.orderDir ?? 'desc';

    const { data, total } = await this.usersService.findAllUsers({
      page,
      pageSize,
      orderBy,
      orderDir,
      startDate: dto.startDate,
      endDate: dto.endDate,
      name: dto.name,
      email: dto.email,
      documentNumber: dto.documentNumber,
      status: dto.status,
      tenantCode: tenantCtx.tenantCode,
      currentLevel: tenantCtx.level,
      level: tenantCtx.level,
      groupingId: tenantCtx.groupingId,
      branchCode: tenantCtx.branchCode,
      operatorReferenceId: user.referenceId,
    });

    return {
      data: data.map((user) => UserHelper.mapUserToResponse(user)),
      pagination: {
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
      },
    };
  }

  async findOne(id: number): Promise<UserDetailResponseDTO> {
    const user = await this.usersService.findUserByIdWithDetail(id);

    return UserHelper.mapUserToDetailResponse(user);
  }

  async findOneByReference(
    referenceId: string,
  ): Promise<UserDetailResponseDTO> {
    const user =
      await this.usersService.findUserByReferenceIdWithDetail(referenceId);

    return UserHelper.mapUserToDetailResponse(user);
  }

  async getEditContext(
    referenceId: string,
  ): Promise<GetEditContextResponseDTO> {
    const user =
      await this.usersService.findUserByReferenceIdWithDetail(referenceId);

    const [assignedRoleIds, availableRoles] = await Promise.all([
      this.userRolesDBService.getUserRoleIds(user.id),
      this.userRolesDBService.getAllAvailableRoles(),
    ]);

    const assignedRoles: EditContextRoleDTO[] = availableRoles
      .filter((r) => assignedRoleIds.includes(r.id))
      .map((r) => ({
        id: r.id,
        name: r.name,
        displayName: r.displayName,
        description: r.description,
      }));

    const unassignedRoles: EditContextRoleDTO[] = availableRoles
      .filter((r) => !assignedRoleIds.includes(r.id))
      .map((r) => ({
        id: r.id,
        name: r.name,
        displayName: r.displayName,
        description: r.description,
      }));

    return {
      user: {
        id: user.id,
        referenceId: user.referenceId,
        firstName: user.firstName,
        lastName: user.lastName,
        email: user.email,
        documentNumber: user.documentNumber,
        phoneNumber: user.phoneNumber,
        status: user.status,
        isEmployee: user.isEmployee,
        isLdap: user.isLdap,
        changedReason: user.changedReason,
      },
      roles: {
        assigned: assignedRoles,
        available: unassignedRoles,
      },
    };
  }

  async updateEditContext(
    referenceId: string,
    dto: UpdateEditContextRequestDTO,
    operatorUser: { email: string },
  ): Promise<UpdateEditContextResponseDTO> {
    const user =
      await this.usersService.findUserByReferenceIdWithDetail(referenceId);

    await this.usersService.updateUserWithContext(
      user,
      dto,
      operatorUser.email,
    );
    return { message: 'Usuario actualizado correctamente' };
  }

  async update(
    id: number,
    dto: UpdateUserRequestDTO,
    updatedBy: string,
  ): Promise<UserResponseDTO> {
    const user = await this.usersService.updateUser(
      id,
      {
        email: dto.email,
        firstName: dto.firstName,
        lastName: dto.lastName,
        documentNumber: dto.documentNumber,
        phoneNumber: dto.phoneNumber,
        isEmployee: dto.isEmployee,
        isLdap: dto.isLdap,
        status: dto.status,
        changedReason: dto.changedReason,
      },
      updatedBy,
    );

    return UserHelper.mapUserToResponse(user);
  }

  async updateByReference(
    referenceId: string,
    dto: UpdateUserRequestDTO,
    updatedBy: string,
  ): Promise<UserResponseDTO> {
    const user = await this.usersService.findUserByReferenceId(referenceId);

    const updated = await this.usersService.updateUser(
      user.id,
      {
        email: dto.email,
        firstName: dto.firstName,
        lastName: dto.lastName,
        documentNumber: dto.documentNumber,
        phoneNumber: dto.phoneNumber,
        isEmployee: dto.isEmployee,
        isLdap: dto.isLdap,
        status: dto.status,
        changedReason: dto.changedReason,
      },
      updatedBy,
    );

    return UserHelper.mapUserToResponse(updated);
  }

  async deleteByReference(
    referenceId: string,
    deletedBy: string,
  ): Promise<void> {
    const user = await this.usersService.findUserByReferenceId(referenceId);
    await this.usersService.inactivateUser(user.id, deletedBy);
  }

  async block(
    id: number,
    dto: BlockUserRequestDTO,
    updatedBy: string,
  ): Promise<UserResponseDTO> {
    const user = await this.usersService.updateUser(
      id,
      {
        status: UserStatus.BLOCKED,
        changedReason: dto.reason,
      },
      updatedBy,
    );

    return UserHelper.mapUserToResponse(user);
  }

  async unblock(
    id: number,
    dto: UnblockUserRequestDTO,
    updatedBy: string,
  ): Promise<UserResponseDTO> {
    const user = await this.usersService.updateUser(
      id,
      {
        status: UserStatus.ACTIVE,
        changedReason: dto.reason,
      },
      updatedBy,
    );

    return UserHelper.mapUserToResponse(user);
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import {
  AccessLevel,
  DocumentType,
  Prisma,
  UserProfileStatus,
  Users,
  UserStatus,
} from '@prisma/client';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import { PermissionsCacheService } from '@core/cache/permissions-cache.service';
import { UserCredentialsWithUser } from '@modules/auth/types';
import {
  UserWithSecurities,
  userWithSecuritiesExtended,
  UserWithSecuritiesExtended,
} from '@modules/auth/types/user.types';
import { EmailService } from '@modules/email/services/email.service';
import { EmailTypeEnum } from '@modules/email/enum/email-type.enum';
import { UpdateEditContextRequestDTO } from '@modules/users-db/dtos/edit-context.request.dto';
import { UserRolesDBService } from './user-roles-db.service';
import { RoleDTO, PermissionDTO } from '../interfaces/users-db.interface';
import { UserWithDetail, userDetailInclude } from '../types/users-db.type';

@Injectable()
export class UsersDBService {
  private readonly logger = new Logger(UsersDBService.name);

  constructor(
    private readonly prisma: PrismaDatasource,
    private readonly emailService: EmailService,
    private readonly userRolesDBService: UserRolesDBService,
    private readonly permissionsCache: PermissionsCacheService,
  ) {}

  // ─── Create ──────────────────────────────────────────────────────────────

  async create(data: Prisma.UsersCreateInput): Promise<Users> {
    return await this.prisma.extended.users.create({ data });
  }

  async createUser(data: {
    email: string;
    firstName: string;
    lastName: string;
    documentNumber?: string;
    isEmployee: boolean;
    isLdap: boolean;
    status?: UserStatus;
    legacyUserId?: string;
    lastLogin?: Date;
    createdBy: string;
    currentAccessLevel?: AccessLevel;
    acceptedTermsAt?: Date;
  }): Promise<Users> {
    const existing = await this.findByEmailAndDocument(
      data.email,
      data.documentNumber || '',
    );

    if (existing) {
      throw new BadRequestException(
        `El usuario con el email ${data.email} ya existe.`,
      );
    }

    const created = await this.create(data);

    try {
      await this.emailService.sendEmailByType(
        data.email,
        EmailTypeEnum.VERIFICATION,
        created,
      );
    } catch (error) {
      this.logger.error(`Error enviando email de verificación: ${error}`);
    }

    return created;
  }

  async createUserWithContext(data: {
    email: string;
    firstName: string;
    lastName: string;
    documentNumber?: string;
    documentType?: DocumentType;
    phoneNumber?: string;
    isEmployee: boolean;
    isLdap: boolean;
    status: UserStatus;
    createdBy: string;
    currentAccessLevel?: AccessLevel;
    roleIds?: number[];
    tenantCtx?: {
      ruc: string;
      tenantCode: string;
      level: AccessLevel;
      branchCodes?: string[];
      groupingIds?: number[];
    };
  }): Promise<Users> {
    const existing = await this.findByEmailAndDocument(
      data.email,
      data.documentNumber || '',
    );

    if (existing) {
      throw new BadRequestException(
        `El usuario con el email ${data.email} ya existe.`,
      );
    }

    const created = await this.prisma.extended.$transaction(async (tx) => {
      const user = await tx.users.create({
        data: {
          email: data.email,
          firstName: data.firstName,
          lastName: data.lastName,
          documentNumber: data.documentNumber ?? null,
          documentType: data.documentType ?? DocumentType.CIP,
          phoneNumber: data.phoneNumber ?? null,
          isEmployee: data.isEmployee,
          isLdap: data.isLdap,
          status: data.status,
          createdBy: data.createdBy,
          currentAccessLevel: data.currentAccessLevel,
          profileStatus: UserProfileStatus.COMPLETE,
        },
      });

      if (data.roleIds?.length) {
        await this.userRolesDBService.replaceUserRoles(
          user.id,
          data.roleIds,
          data.createdBy,
          tx,
        );
      }

      return user;
    });

    try {
      await this.emailService.sendEmailByType(
        data.email,
        EmailTypeEnum.VERIFICATION,
        created,
      );
      await this.emailService.sendEmailByType(
        data.email,
        EmailTypeEnum.CREATE_PASSWORD,
        created,
      );
    } catch (error) {
      this.logger.error(`Error enviando email de verificación: ${error}`);
    }

    return created;
  }

  // ─── Find many ───────────────────────────────────────────────────────────

  async findAll(params: {
    page: number;
    pageSize: number;
    orderBy: string;
    orderDir?: 'asc' | 'desc';
    startDate?: string;
    endDate?: string;
    name?: string;
    email?: string;
    documentNumber?: string;
    status?: UserStatus;
    tenantCode?: string;
    currentAccessLevel?: AccessLevel;
    level?: AccessLevel;
    groupingId?: number;
    branchCode?: string;
    operatorReferenceId?: string;
  }): Promise<{ data: Users[]; total: number }> {
    const {
      page,
      pageSize,
      orderBy,
      orderDir = 'desc',
      startDate,
      endDate,
      name,
      email,
      documentNumber,
      status,
      currentAccessLevel,
      operatorReferenceId,
    } = params;

    const skip = (page - 1) * pageSize;
    const ilike = Prisma.QueryMode.insensitive;

    const createdAt: Prisma.DateTimeFilter | undefined =
      startDate || endDate
        ? {
            gte: startDate ? new Date(startDate) : undefined,
            lte: endDate ? new Date(endDate) : undefined,
          }
        : undefined;

    const nameFilter = name
      ? name
          .trim()
          .split(/\s+/)
          .map((term) => ({
            OR: [
              { firstName: { contains: term, mode: ilike } },
              { lastName: { contains: term, mode: ilike } },
            ],
          }))
      : undefined;

    const where: Prisma.UsersWhereInput = {
      status: status ? { equals: status } : undefined,
      createdAt,
      AND: nameFilter,
      email: email ? { contains: email, mode: ilike } : undefined,
      documentNumber: documentNumber
        ? { contains: documentNumber, mode: ilike }
        : undefined,
      currentAccessLevel:
        currentAccessLevel && currentAccessLevel !== AccessLevel.COMMERCE
          ? { equals: currentAccessLevel }
          : undefined,
      referenceId: { not: operatorReferenceId },
    };

    const [data, total] = await this.prisma.extended.$transaction([
      this.prisma.extended.users.findMany({
        where,
        skip,
        take: pageSize,
        orderBy: { [orderBy]: orderDir },
      }),
      this.prisma.extended.users.count({ where }),
    ]);

    return { data, total };
  }

  async findAllUsers(params: {
    page: number;
    pageSize: number;
    orderBy: string;
    orderDir?: 'asc' | 'desc';
    startDate?: string;
    endDate?: string;
    name?: string;
    email?: string;
    documentNumber?: string;
    status?: UserStatus;
    tenantCode?: string;
    currentLevel?: AccessLevel;
    level?: AccessLevel;
    groupingId?: number;
    branchCode?: string;
    operatorReferenceId?: string;
  }): Promise<{ data: Users[]; total: number }> {
    return this.findAll(params);
  }

  // ─── Find one ────────────────────────────────────────────────────────────

  async findById(id: number): Promise<Users | null> {
    return await this.prisma.extended.users.findUnique({ where: { id } });
  }

  async findUserById(id: number): Promise<Users> {
    const user = await this.findById(id);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${id} no encontrado.`);
    return user;
  }

  async findByIdWithDetail(id: number): Promise<UserWithDetail | null> {
    return await this.prisma.extended.users.findUnique({
      where: { id },
      include: userDetailInclude,
    });
  }

  async findUserByIdWithDetail(id: number): Promise<UserWithDetail> {
    const user = await this.findByIdWithDetail(id);
    if (!user)
      throw new NotFoundException(`Usuario con ID ${id} no encontrado.`);
    return user;
  }

  async findByReferenceId(referenceId: string): Promise<Users | null> {
    return await this.prisma.extended.users.findUnique({
      where: { referenceId },
    });
  }

  async findUserByReferenceId(referenceId: string): Promise<Users> {
    const user = await this.findByReferenceId(referenceId);
    if (!user) throw new NotFoundException(`Usuario no encontrado.`);
    return user;
  }

  async findByReferenceIdWithDetail(
    referenceId: string,
  ): Promise<UserWithDetail | null> {
    return await this.prisma.extended.users.findUnique({
      where: { referenceId },
      include: userDetailInclude,
    });
  }

  async findUserByReferenceIdWithDetail(
    referenceId: string,
  ): Promise<UserWithDetail> {
    const user = await this.findByReferenceIdWithDetail(referenceId);
    if (!user) throw new NotFoundException(`Usuario no encontrado.`);
    return user;
  }

  async findByEmail(email: string): Promise<Users | null> {
    return await this.prisma.extended.users.findUnique({ where: { email } });
  }

  async findUserByEmail(email: string): Promise<Users | null> {
    return this.findByEmail(email);
  }

  async findByEmailAndDocument(
    email: string,
    documentNumber: string,
  ): Promise<Users | null> {
    return await this.prisma.extended.users.findFirst({
      where: { email, documentNumber },
    });
  }

  async findActiveUserByEmail(
    email: string,
  ): Promise<UserWithSecurities | null> {
    return await this.prisma.extended.users.findFirst({
      where: {
        email,
        status: { in: [UserStatus.ACTIVE, UserStatus.PENDING_VERIFICATION] },
      },
      include: {
        roles: true,
        permissions: true,
        credentials: true,
      },
    });
  }

  async findActiveUserById(id: number): Promise<Users | null> {
    return await this.prisma.extended.users.findFirst({
      where: {
        id,
        status: { in: [UserStatus.ACTIVE, UserStatus.PENDING_VERIFICATION] },
      },
    });
  }

  async findCredentialsByEmail(
    email: string,
  ): Promise<UserCredentialsWithUser | null> {
    return await this.prisma.extended.userCredentials.findFirst({
      where: { isActive: true, user: { email } },
      include: {
        user: {
          include: { roles: true, permissions: true, credentials: true },
        },
      },
    });
  }

  async findActiveUserByEmailWithPermissions(
    email: string,
  ): Promise<UserWithSecuritiesExtended | null> {
    return (await this.prisma.extended.users.findFirst({
      where: {
        email,
        status: { in: [UserStatus.ACTIVE, UserStatus.PENDING_VERIFICATION] },
      },
      include: userWithSecuritiesExtended.include,
    })) as UserWithSecuritiesExtended;
  }

  // ─── Update ──────────────────────────────────────────────────────────────

  async update(id: number, data: Prisma.UsersUpdateInput): Promise<Users> {
    const updated = await this.prisma.extended.users.update({
      where: { id },
      data,
    });
    await this.permissionsCache.invalidateAll();
    return updated;
  }

  /** Actualiza solo los datos del documento de identidad (no afecta roles/permisos, sin invalidar cache). */
  async updateDocument(
    id: number,
    data: { documentType?: DocumentType; documentNumber?: string },
  ): Promise<void> {
    await this.prisma.extended.users.update({ where: { id }, data });
  }

  async updateUser(
    id: number,
    data: {
      email?: string;
      firstName?: string;
      lastName?: string;
      documentNumber?: string;
      phoneNumber?: string;
      isEmployee?: boolean;
      isLdap?: boolean;
      status?: UserStatus;
      changedReason?: string;
    },
    updatedBy: string,
  ): Promise<Users> {
    await this.findUserById(id);

    return await this.update(id, {
      ...data,
      lastChangedBy: updatedBy,
      lastChangedAt: new Date(),
      changedReason:
        data.changedReason ??
        (data.status === UserStatus.BLOCKED
          ? 'Cantidad de intentos fallidos superado'
          : undefined),
    });
  }

  async updateLastLogin(userId: number): Promise<void> {
    await this.prisma.extended.users.update({
      where: { id: userId },
      data: { lastLogin: new Date() },
    });
  }

  async updateStatus(userId: number, status: UserStatus): Promise<void> {
    await this.prisma.extended.users.update({
      where: { id: userId },
      data: { status },
    });
    await this.permissionsCache.invalidateAll();
  }

  async verifyUser(userId: number): Promise<void> {
    await this.prisma.extended.users.update({
      where: { id: userId },
      data: { status: UserStatus.ACTIVE, unverifiedEmail: null },
    });
  }

  async blockUser(id: number, reason: string): Promise<void> {
    await this.prisma.extended.users.update({
      where: { id },
      data: {
        status: UserStatus.BLOCKED,
        lastChangedAt: new Date(),
        changedReason: reason,
      },
    });
    await this.permissionsCache.invalidateAll();
  }

  async inactivate(id: number, deletedBy: string): Promise<void> {
    await this.prisma.extended.users.update({
      where: { id },
      data: {
        status: UserStatus.INACTIVE,
        lastChangedBy: deletedBy,
        lastChangedAt: new Date(),
        changedReason: `Eliminado por ${deletedBy}`,
      },
    });
    await this.permissionsCache.invalidateAll();
  }

  async inactivateUser(id: number, deletedBy: string): Promise<void> {
    await this.findUserById(id);
    await this.inactivate(id, deletedBy);
  }

  // ─── Roles y permisos ────────────────────────────────────────────────────

  async getUserRoles(userId: number): Promise<RoleDTO[]> {
    const userRoles = await this.prisma.extended.userRoles.findMany({
      where: { userId, role: { isActive: true } },
      include: {
        role: { select: { id: true, name: true, description: true } },
      },
    });

    return userRoles.map(
      (ur): RoleDTO => ({
        id: ur.role.id,
        name: ur.role.name,
        description: ur.role.description,
      }),
    );
  }

  async getUserPermissions(userId: number): Promise<PermissionDTO[]> {
    const userPermissions = await this.prisma.extended.userPermissions.findMany(
      {
        where: { userId, permission: { isActive: true } },
        include: { permission: { select: { name: true } } },
      },
    );

    return userPermissions.map(
      (up): PermissionDTO => ({ name: up.permission.name }),
    );
  }

  async getRolePermissions(roleIds: number[]): Promise<PermissionDTO[]> {
    if (roleIds.length === 0) return [];

    const rolePermissions = await this.prisma.extended.rolePermissions.findMany(
      {
        where: { roleId: { in: roleIds }, permission: { isActive: true } },
        include: { permission: { select: { name: true } } },
      },
    );

    const unique = new Map<string, PermissionDTO>();
    rolePermissions.forEach((rp) => {
      if (!unique.has(rp.permission.name)) {
        unique.set(rp.permission.name, { name: rp.permission.name });
      }
    });

    return Array.from(unique.values());
  }

  // ─── Context update (transaction) ────────────────────────────────────────

  async updateUserWithContext(
    user: Users,
    dto: UpdateEditContextRequestDTO,
    operatorUserEmail: string,
  ): Promise<void> {
    await this.prisma.extended.$transaction(async (tx) => {
      if (dto.user) {
        await tx.users.update({
          where: { id: user.id },
          data: {
            firstName: dto.user.firstName,
            lastName: dto.user.lastName,
            email: dto.user.email,
            documentNumber: dto.user.documentNumber ?? null,
            isEmployee: dto.user.isEmployee,
            isLdap: dto.user.isLdap,
            status: dto.user.status,
            changedReason: dto.user.changedReason ?? null,
            lastChangedBy: operatorUserEmail,
            lastChangedAt: new Date(),
          },
        });
      }

      if (dto.roleIds !== undefined) {
        await this.userRolesDBService.replaceUserRoles(
          user.id,
          dto.roleIds,
          operatorUserEmail,
          tx,
        );
      }
    });
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { PushChannel } from '@prisma/client';
import * as webpush from 'web-push';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import {
  IPushPayload,
  IPushProvider,
  IPushSendResult,
  IPushTarget,
  PushSendOutcome,
} from '../interfaces/push-provider.interface';

/**
 * Adapter Web Push (VAPID). Las claves se pasan por llamada (`vapidDetails`) en vez de
 * `setVapidDetails` global, así no hay estado compartido entre providers ni entre tests.
 */
@Injectable()
export class WebPushProvider implements IPushProvider {
  readonly channel = PushChannel.WEBPUSH;
  readonly name = 'WEBPUSH';
  private readonly logger = new Logger(WebPushProvider.name);
  private readonly vapid: webpush.VapidKeys & { subject: string };
  private readonly enabled: boolean;

  constructor(@Inject(APP_CONFIG.KEY) config: ConfigType<AppConfigType>) {
    const { publicKey, privateKey, subject } = config.push.webPush;
    this.vapid = { publicKey, privateKey, subject };
    this.enabled = Boolean(publicKey && privateKey && subject);
  }

  isEnabled(): boolean {
    return this.enabled;
  }

  /** Clave pública VAPID para que el front se suscriba (`applicationServerKey`). */
  getPublicKey(): string {
    return this.vapid.publicKey;
  }

  async send(
    target: IPushTarget,
    payload: IPushPayload,
  ): Promise<IPushSendResult> {
    if (!this.enabled) {
      return {
        outcome: PushSendOutcome.FAILED,
        error: 'VAPID no configurado',
      };
    }
    if (!target.p256dh || !target.auth) {
      return {
        outcome: PushSendOutcome.GONE,
        error: 'Suscripción sin claves p256dh/auth',
      };
    }

    try {
      await webpush.sendNotification(
        {
          endpoint: target.token,
          keys: { p256dh: target.p256dh, auth: target.auth },
        },
        JSON.stringify({
          title: payload.title,
          body: payload.body,
          data: payload.data,
        }),
        {
          vapidDetails: {
            subject: this.vapid.subject,
            publicKey: this.vapid.publicKey,
            privateKey: this.vapid.privateKey,
          },
        },
      );
      return { outcome: PushSendOutcome.SENT };
    } catch (error) {
      const statusCode = (error as { statusCode?: number } | undefined)
        ?.statusCode;
      if (statusCode === 404 || statusCode === 410) {
        return { outcome: PushSendOutcome.GONE, error: String(statusCode) };
      }
      const message = error instanceof Error ? error.message : 'unknown';
      this.logger.error(`Fallo al enviar Web Push: ${message}`);
      return { outcome: PushSendOutcome.FAILED, error: message };
    }
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { WsException } from '@nestjs/websockets';
import type { Socket } from 'socket.io';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { CryptoHelper } from '@common/helpers/crypto-helpers';
import { IJwtPayload } from '@common/interfaces/jwt-payload.interface';
import { JwtStrategy } from '@modules/auth/strategies/jwt.strategy';
import { IUserDataOnJwt } from '@modules/auth/interfaces/user-data-on-jwt.interface';

export const WS_USER_KEY = 'user';
const ACCESS_COOKIE = 'accessToken';

/**
 * Patrón: Adapter. Reutiliza la validación JWT HTTP (firma RS256 + `JwtStrategy.validate`, con su
 * cache de permisos) para sockets, así WS y REST aplican exactamente la misma regla de identidad (DRY).
 * El token viaja en `handshake.auth.token`, en `Authorization: Bearer` o en la cookie `accessToken`.
 */
@Injectable()
export class WsAuthService {
  constructor(
    private readonly jwtStrategy: JwtStrategy,
    @Inject(APP_CONFIG.KEY) config: ConfigType<AppConfigType>,
  ) {
    CryptoHelper.initConfigService(config);
  }

  extractToken(client: Socket): string | undefined {
    const fromAuth = (client.handshake.auth as Record<string, unknown>)?.token;
    if (typeof fromAuth === 'string' && fromAuth) return fromAuth;

    const header = client.handshake.headers.authorization;
    if (header?.toLowerCase().startsWith('bearer ')) return header.slice(7);

    return readCookie(client.handshake.headers.cookie, ACCESS_COOKIE);
  }

  /** Autentica el socket (idempotente: reutiliza el usuario ya resuelto en `client.data`). */
  async authenticate(client: Socket): Promise<IUserDataOnJwt> {
    const cached = (client.data as Record<string, unknown>)[WS_USER_KEY];
    if (cached) return cached as IUserDataOnJwt;

    const token = this.extractToken(client);
    if (!token) throw new WsException('Token no proporcionado');

    try {
      const payload = CryptoHelper.verifyJwt<IJwtPayload>(token);
      if (payload.tokenType !== 'accessToken') throw new Error('tipo');
      const user = await this.jwtStrategy.validate(payload);
      (client.data as Record<string, unknown>)[WS_USER_KEY] = user;
      return user;
    } catch {
      throw new WsException('Token inválido');
    }
  }
}

export function readCookie(
  header: string | undefined,
  name: string,
): string | undefined {
  if (!header) return undefined;
  for (const part of header.split(';')) {
    const index = part.indexOf('=');
    if (index > 0 && part.slice(0, index).trim() === name) {
      return decodeURIComponent(part.slice(index + 1).trim());
    }
  }
  return undefined;
}

