import {
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Injectable,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ApiClientsDBService } from '@modules/api-clients-db/services/api-clients-db.service';
import type { ApiClientVerification } from '@modules/api-clients-db/interfaces/api-client.interface';
import { API_CLIENT_SCOPES } from '@modules/api-clients-db/constants/api-client-scopes.constants';
import { isIpAllowed } from '@common/helpers/ip.helper';
import { API_CLIENT_SCOPES_KEY } from '../decorators/api-client.decorators';
import type { ApiClientRequest } from '../interfaces/api-client-request.interface';

/**
 * Patrón: guard de autenticación M2M (Basic `clientId:secret`). Verifica el secret contra su hash
 * bcrypt (en `ApiClientsDBService`), aplica allowlist de IPs y, si el handler declara
 * `@ApiClientScopes(...)`, exige esos scopes. Publica la identidad en `request.apiClient`.
 * Los endpoints que solo necesitan "app cliente válida" (login, onboarding) no declaran scopes.
 */
@Injectable()
export class BasicAuthGuard implements CanActivate {
  private readonly logger = new Logger(BasicAuthGuard.name);

  constructor(
    private readonly apiClients: ApiClientsDBService,
    private readonly reflector: Reflector,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<ApiClientRequest>();
    const { clientId, secret } = this.parseBasicHeader(
      request.headers.authorization,
    );

    let verification: ApiClientVerification;
    try {
      verification = await this.apiClients.verifyCredentials(clientId, secret);
    } catch (error) {
      this.logger.error(
        'Error al validar credenciales de API',
        error instanceof Error ? error.stack : String(error),
      );
      throw new ForbiddenException(
        'Error de servicio al validar credenciales.',
      );
    }

    if (verification.result === 'invalid') {
      throw new UnauthorizedException('Credenciales inválidas.');
    }
    if (verification.result === 'inactive') {
      this.logger.warn(`Acceso denegado: cliente ${clientId} inactivo.`);
      throw new ForbiddenException(
        'El acceso para este cliente ha sido revocado.',
      );
    }

    const { principal } = verification;
    if (!isIpAllowed(request.ip, principal.allowedIps)) {
      this.logger.warn(`Acceso denegado: IP no permitida para ${clientId}.`);
      throw new ForbiddenException('IP no autorizada para este cliente.');
    }

    const required =
      this.reflector.getAllAndOverride<string[] | undefined>(
        API_CLIENT_SCOPES_KEY,
        [context.getHandler(), context.getClass()],
      ) ?? [];
    const granted = principal.scopes;
    const hasScopes =
      granted.includes(API_CLIENT_SCOPES.ALL) ||
      required.every((scope) => granted.includes(scope));
    if (!hasScopes) {
      throw new ForbiddenException('Scope insuficiente para este recurso.');
    }

    request.apiClient = principal;
    return true;
  }

  private parseBasicHeader(header: string | undefined): {
    clientId: string;
    secret: string;
  } {
    if (!header?.startsWith('Basic ')) {
      throw new UnauthorizedException('Se requiere Basic Authentication.');
    }
    const decoded = Buffer.from(header.slice(6), 'base64').toString('utf8');
    // El secret puede contener ':'; solo el primero separa clientId de secret.
    const separator = decoded.indexOf(':');
    if (separator <= 0 || separator === decoded.length - 1) {
      throw new UnauthorizedException(
        'Formato de credenciales Basic Auth incorrecto (debe ser client_id:client_secret).',
      );
    }
    return {
      clientId: decoded.slice(0, separator),
      secret: decoded.slice(separator + 1),
    };
  }
}

import {
  CanActivate,
  ExecutionContext,
  Inject,
  Injectable,
  InternalServerErrorException,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { ApiClientsDBService } from '@modules/api-clients-db/services/api-clients-db.service';
import { NonceService } from '@modules/nonce/nonce.service';
import {
  isTimestampInWindow,
  SIGNATURE_HEADERS,
  verifyRequestSignature,
} from '@common/helpers/crypto/request-signature.helper';
import type { ApiClientRequest } from '../interfaces/api-client-request.interface';

const headerValue = (
  value: string | string[] | undefined,
): string | undefined => (Array.isArray(value) ? value[0] : value);

/**
 * Patrón: guard de integridad + anti-replay, opcional por cliente. Corre DESPUÉS de
 * `BasicAuthGuard` (necesita `request.apiClient`) y solo actúa si la credencial tiene
 * `hmacEnabled`. Valida `X-Signature` sobre `METHOD\npath\ntimestamp\nsha256(body)` usando el
 * rawBody de Nest (el body parseado no sirve: reserializar altera los bytes), el
 * `X-Timestamp` dentro de la ventana configurable y, si viene, `X-Nonce` de un solo uso.
 * La firma se valida ANTES de consumir el nonce para que un tercero sin secreto no pueda
 * "quemar" nonces ajenos.
 */
@Injectable()
export class HmacSignatureGuard implements CanActivate {
  private readonly logger = new Logger(HmacSignatureGuard.name);

  constructor(
    private readonly apiClients: ApiClientsDBService,
    private readonly nonces: NonceService,
    @Inject(APP_CONFIG.KEY) private readonly config: ConfigType<AppConfigType>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest<ApiClientRequest>();
    const principal = request.apiClient;
    if (!principal) {
      throw new UnauthorizedException(
        'Se requiere autenticación de cliente antes de validar la firma.',
      );
    }
    if (!principal.hmacEnabled) return true;

    const signature = headerValue(request.headers[SIGNATURE_HEADERS.signature]);
    const timestamp = headerValue(request.headers[SIGNATURE_HEADERS.timestamp]);
    const nonce = headerValue(request.headers[SIGNATURE_HEADERS.nonce]);
    if (!signature || !timestamp) {
      throw new UnauthorizedException('Faltan X-Signature o X-Timestamp.');
    }

    const { hmacTimestampWindowSeconds: windowSeconds, hmacNonceRequired } =
      this.config.apiClients;
    if (!isTimestampInWindow(timestamp, windowSeconds)) {
      throw new UnauthorizedException(
        'X-Timestamp fuera de la ventana permitida.',
      );
    }
    if (hmacNonceRequired && !nonce) {
      throw new UnauthorizedException('Falta X-Nonce.');
    }

    const secret = await this.apiClients.getSigningSecret(principal.id);
    if (!secret) {
      this.logger.error(
        `Cliente ${principal.id} con HMAC activo pero sin signing secret.`,
      );
      throw new UnauthorizedException('Firma inválida.');
    }

    if (!request.rawBody && this.hasBody(request)) {
      throw new InternalServerErrorException(
        'rawBody no disponible: habilitar `rawBody: true` en NestFactory.create.',
      );
    }

    const valid = verifyRequestSignature(
      secret,
      {
        method: request.method,
        path: request.originalUrl,
        timestamp,
        body: request.rawBody,
        nonce,
      },
      signature,
    );
    if (!valid) {
      this.logger.warn(`Firma inválida para el cliente ${principal.id}.`);
      throw new UnauthorizedException('Firma inválida.');
    }

    if (nonce && !(await this.nonces.claim(nonce, windowSeconds * 2))) {
      throw new UnauthorizedException('Nonce inválido o ya utilizado.');
    }
    return true;
  }

  private hasBody(request: ApiClientRequest): boolean {
    const body: unknown = request.body;
    return (
      typeof body === 'object' &&
      body !== null &&
      Object.keys(body as Record<string, unknown>).length > 0
    );
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
  Logger,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';

import {
  PERMISSIONS_KEY,
  PERMISSIONS_MODE_KEY,
  PermissionsMode,
} from '@common/decorators/permissions.decorator';
import { PERMISSIONS } from '@common/enum/permissions.enum';
import { t } from '@common/i18n/i18n.helper';

interface IRequestUser {
  id?: string | number;
  userId?: string | number;
  permissions?: unknown;
}

/**
 * Patrón: guard de autorización declarativo (metadata + Reflector).
 * - Superusuario: `admin:all` pasa directo, así los controllers no repiten ese permiso.
 * - Metadata de handler y de clase (`getAllAndOverride`): el handler gana sobre la clase.
 * - 403 genérico al cliente (no filtra qué permiso falta); el detalle va al log.
 */
@Injectable()
export class PermissionsGuard implements CanActivate {
  private readonly logger = new Logger(PermissionsGuard.name);

  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const targets = [context.getHandler(), context.getClass()];
    const required = this.reflector.getAllAndOverride<string[] | undefined>(
      PERMISSIONS_KEY,
      targets,
    );

    if (!required || required.length === 0) {
      return true;
    }

    const { user } = context.switchToHttp().getRequest<{
      user?: IRequestUser;
    }>();
    const granted =
      user && Array.isArray(user.permissions)
        ? (user.permissions as string[])
        : [];

    if (granted.includes(PERMISSIONS.ADMIN.ALL)) {
      return true;
    }

    const mode =
      this.reflector.getAllAndOverride<PermissionsMode | undefined>(
        PERMISSIONS_MODE_KEY,
        targets,
      ) ?? 'any';
    const has = (permission: string) => granted.includes(permission);
    const allowed = mode === 'all' ? required.every(has) : required.some(has);

    if (!allowed) {
      this.logger.warn(
        `Acceso denegado userId=${user?.id ?? user?.userId ?? 'anonymous'} requeridos=[${required.join(',')}] modo=${mode}`,
      );
      throw new ForbiddenException(t('auth.INSUFFICIENT_PERMISSIONS'));
    }

    return true;
  }
}

import {
  CanActivate,
  ExecutionContext,
  HttpException,
  Inject,
  Injectable,
} from '@nestjs/common';
import { ConfigType } from '@nestjs/config';
import { Reflector } from '@nestjs/core';
import { LegalDocumentType } from '@prisma/client';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { t } from '@common/i18n/i18n.helper';
import { REQUIRES_ACTIVE_CONSENT_KEY } from '@common/decorators/requires-active-consent.constants';
import { UserConsentsDBService } from '../services/user-consents-db.service';

export const CONSENT_REQUIRED_CODE = 'CONSENT_REQUIRED';

/**
 * Patrón: guard declarativo (metadata + Reflector). El endpoint declara QUÉ documento exige
 * (`@RequiresActiveConsent(type)`) y el guard decide con una consulta; SRP: no autentica, asume
 * `request.user` (el decorador ya antepone JwtAuthGuard). Status configurable: 403 o 451.
 */
@Injectable()
export class RequiresActiveConsentGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly consents: UserConsentsDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly config: ConfigType<AppConfigType>,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const type = this.reflector.getAllAndOverride<
      LegalDocumentType | undefined
    >(REQUIRES_ACTIVE_CONSENT_KEY, [context.getHandler(), context.getClass()]);
    if (!type) return true;

    const request = context
      .switchToHttp()
      .getRequest<{ user?: { id?: number } }>();
    const userId = request.user?.id;

    if (
      userId !== undefined &&
      (await this.consents.hasActiveConsent(userId, type))
    ) {
      return true;
    }

    const status = this.config.compliance.consentRequiredStatus;
    throw new HttpException(
      {
        statusCode: status,
        code: CONSENT_REQUIRED_CODE,
        message: t('legal.CONSENT_REQUIRED'),
        documentType: type,
      },
      status,
    );
  }
}

import { ITenantContext } from '@common/interfaces/tenant-context.interface';
import { PrismaDatasource } from '@core/database/services/prisma.service';
import {
  Injectable,
  CanActivate,
  ExecutionContext,
  BadRequestException,
  ForbiddenException,
} from '@nestjs/common';

@Injectable()
export class TenantContextGuard implements CanActivate {
  constructor(private prisma: PrismaDatasource) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const user = request.user;

    const userExists = await this.prisma.extended.users.findUnique({
      where: { id: Number(user.id) },
      select: { id: true },
    });

    if (!userExists) {
      throw new ForbiddenException('El usuario no existe.');
    }

    const cookieData = request.cookies['tenant-ctx'];

    if (!cookieData) {
      throw new BadRequestException(
        'Falta la cookie tenant-ctx con el contexto de operación.',
      );
    }

    try {
      const decodedString = Buffer.from(cookieData, 'base64').toString('utf-8');
      const tenantContext: ITenantContext = JSON.parse(decodedString);

      request.tenantContext = tenantContext;

      return true;
    } catch (error) {
      if (error instanceof ForbiddenException) throw error;
      throw new BadRequestException(
        'El formato del contexto en la cookie tenant-ctx es inválido.',
      );
    }
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { Users } from '@prisma/client';

@Injectable()
export class UserByEmailLoaderGuard implements CanActivate {
  constructor(private readonly usersService: UsersDBService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const body = request.body;
    const query = request.query;

    if (!body?.email && !query?.email) {
      throw new BadRequestException(
        'La solicitud debe contener un campo "email" en el cuerpo o en los parametros.',
      );
    }

    const email: string = body?.email ?? query?.email;

    const fullUser: Users | null =
      await this.usersService.findActiveUserByEmail(email);

    if (!fullUser) {
      throw new NotFoundException(
        'Usuario no encontrado o inactivo para el email proporcionado.',
      );
    }

    request.user = fullUser;

    return true;
  }
}

import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';
import type { Socket } from 'socket.io';
import { WsAuthService } from './ws-auth.service';

/**
 * Patrón: guard de autenticación para mensajes WS. Delega en `WsAuthService` (misma validación
 * que el JWT HTTP); si el handshake ya autenticó el socket no vuelve a verificar el token.
 */
@Injectable()
export class WsJwtGuard implements CanActivate {
  constructor(private readonly auth: WsAuthService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const client = context.switchToWs().getClient<Socket>();
    await this.auth.authenticate(client);
    return true;
  }
}

