import { Logger } from '@nestjs/common';
import { PhoneHelper } from '@common/helpers/phone.helper';
import { SmsProviderError } from '../errors/sms.errors';
import type {
  ISmsMessage,
  ISmsSender,
  ISmsSendResult,
} from '../interfaces/sms-sender.interface';
import type { InfobipGateway } from './infobip.gateway';

/** Grupos de estado de Infobip que significan "el proveedor aceptó el SMS". */
const ACCEPTED_GROUPS: ReadonlySet<string> = new Set([
  'PENDING',
  'ACCEPTED',
  'DELIVERED',
]);

/** Adapter de `ISmsSender` sobre Infobip. */
export class InfobipSmsSender implements ISmsSender {
  readonly provider = 'INFOBIP';
  private readonly logger = new Logger(InfobipSmsSender.name);

  constructor(
    private readonly gateway: InfobipGateway,
    private readonly from?: string,
  ) {}

  async send(message: ISmsMessage): Promise<ISmsSendResult> {
    const response = await this.gateway.send({
      type: 'text',
      messages: [
        {
          destinations: [{ to: message.to }],
          text: message.text,
          ...(this.from ? { from: this.from } : {}),
        },
      ],
    });

    const sent = Array.isArray(response?.messages)
      ? response.messages[0]
      : undefined;
    if (!sent?.messageId || !sent.status?.groupName) {
      throw new SmsProviderError(
        'Respuesta de Infobip sin el formato esperado',
      );
    }
    if (!ACCEPTED_GROUPS.has(sent.status.groupName)) {
      throw new SmsProviderError(
        `Infobip rechazó el mensaje (${sent.status.groupName})`,
        sent.status.groupName,
      );
    }

    this.logger.log(
      `SMS aceptado messageId=${sent.messageId} estado=${sent.status.groupName} destino=${PhoneHelper.mask(message.to)}`,
    );
    return { messageId: sent.messageId, status: sent.status.groupName };
  }
}

import type { INonceStore } from '../nonce.interfaces';

const SWEEP_THRESHOLD = 1000;

/**
 * Patrón: fallback en memoria (válido para una sola instancia). Node es single-thread, así que
 * `consume`/`claim` son atómicos sin locks. La limpieza de expirados es perezosa (al superar un
 * umbral de entradas) para no necesitar timers que mantengan vivo el proceso.
 */
export class InMemoryNonceStore implements INonceStore {
  private readonly issued = new Map<string, number>();
  private readonly claimed = new Map<string, number>();

  constructor(private readonly now: () => number = Date.now) {}

  issue(nonce: string, ttlSeconds: number): Promise<void> {
    this.sweep(this.issued);
    this.issued.set(nonce, this.now() + ttlSeconds * 1000);
    return Promise.resolve();
  }

  consume(nonce: string): Promise<boolean> {
    const expiresAt = this.issued.get(nonce);
    this.issued.delete(nonce);
    return Promise.resolve(expiresAt !== undefined && expiresAt > this.now());
  }

  claim(nonce: string, ttlSeconds: number): Promise<boolean> {
    this.sweep(this.claimed);
    const expiresAt = this.claimed.get(nonce);
    if (expiresAt !== undefined && expiresAt > this.now()) {
      return Promise.resolve(false);
    }
    this.claimed.set(nonce, this.now() + ttlSeconds * 1000);
    return Promise.resolve(true);
  }

  private sweep(store: Map<string, number>): void {
    if (store.size < SWEEP_THRESHOLD) return;
    const now = this.now();
    for (const [key, expiresAt] of store) {
      if (expiresAt <= now) store.delete(key);
    }
  }
}

import {
  ValidatorConstraint,
  ValidatorConstraintInterface,
  ValidationArguments,
} from 'class-validator';
import { t } from '@common/i18n/i18n.helper';

export interface DateRangeDTO {
  startDate?: Date;
  endDate?: Date;
}

@ValidatorConstraint({ name: 'IsEndDateAfterStartDate', async: false })
export class IsEndDateAfterStartDate implements ValidatorConstraintInterface {
  private message: string = '';
  validate(endDate: unknown, args: ValidationArguments) {
    const obj = args.object as DateRangeDTO;
    if (!obj.startDate) {
      this.message = t('validation.START_DATE_REQUIRED');
      return false;
    }

    if (new Date(endDate as Date) < new Date(obj.startDate)) {
      this.message = t('validation.END_DATE_AFTER_START');
      return false;
    }

    return true;
  }

  defaultMessage(): string {
    return this.message || t('validation.END_DATE_INVALID');
  }
}

@ValidatorConstraint({ name: 'IsDateRangeWithinSixMonths', async: false })
export class IsDateRangeWithinSixMonths
  implements ValidatorConstraintInterface
{
  validate(endDate: unknown, args: ValidationArguments): boolean {
    const obj = args.object as DateRangeDTO;
    if (!obj.startDate || endDate == null) return true;
    const start = new Date(obj.startDate);
    const end = new Date(endDate as Date);
    if (isNaN(start.getTime()) || isNaN(end.getTime())) return true;
    const maxEnd = new Date(start);
    maxEnd.setMonth(maxEnd.getMonth() + 6);
    return end <= maxEnd;
  }

  defaultMessage(): string {
    return t('validation.DATE_RANGE_MAX_SIX_MONTHS');
  }
}

