/** Helper puro para to/cc/bcc: dedupe, tope de destinatarios y enmascarado para logs/ledger. */
export class RecipientHelper {
  /** Quita duplicados sin distinguir mayúsculas, conservando el orden de primera aparición. */
  static dedupe(recipients: readonly string[]): string[] {
    const seen = new Set<string>();
    return recipients.filter((recipient) => {
      const key = recipient.trim().toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  /**
   * Normaliza to/cc/bcc: dedupe por lista y una dirección no se repite entre listas
   * (to gana sobre cc, cc sobre bcc) para no enviar el mismo correo dos veces.
   */
  static normalize(recipients: IRecipients): IRecipients {
    const to = RecipientHelper.dedupe(recipients.to);
    const taken = new Set(to.map((r) => r.toLowerCase()));
    const take = (list?: readonly string[]): string[] | undefined => {
      if (!list) return undefined;
      const result = RecipientHelper.dedupe(list).filter(
        (r) => !taken.has(r.toLowerCase()),
      );
      result.forEach((r) => taken.add(r.toLowerCase()));
      return result.length > 0 ? result : undefined;
    };
    const cc = take(recipients.cc);
    const bcc = take(recipients.bcc);
    return { to, ...(cc ? { cc } : {}), ...(bcc ? { bcc } : {}) };
  }

  static exceedsMax(recipients: IRecipients): boolean {
    return (
      recipients.to.length +
        (recipients.cc?.length ?? 0) +
        (recipients.bcc?.length ?? 0) >
      MAX_RECIPIENTS
    );
  }

  static maskEmail(email: string): string {
    const at = email.lastIndexOf('@');
    if (at < 0) return '***';
    return at === 0 ? `***${email}` : `${email[0]}***${email.slice(at)}`;
  }

  /** Enmascara todos los destinatarios en una sola cadena (para la columna `recipient` del ledger). */
  static maskAll(recipients: IRecipients): string {
    return [
      ...recipients.to,
      ...(recipients.cc ?? []),
      ...(recipients.bcc ?? []),
    ]
      .map((email) => RecipientHelper.maskEmail(email))
      .join(', ');
  }

  static maskEmailsInText(text: string): string {
    return text.replace(EMAIL_PATTERN, (match) =>
      RecipientHelper.maskEmail(match),
    );
  }
}

import { INestApplicationContext, Logger } from '@nestjs/common';
import { IoAdapter } from '@nestjs/platform-socket.io';
import { createAdapter } from '@socket.io/redis-adapter';
import Redis from 'ioredis';
import type { ServerOptions } from 'socket.io';

/**
 * Patrón: Adapter opcional de socket.io. Con REDIS_URL los eventos/rooms se propagan entre
 * instancias; sin él (o si Redis no responde) se mantiene el adapter in-memory por defecto.
 * Usa clientes propios SIN `keyPrefix`: ioredis prefija el publish pero no el subscribe y los
 * canales dejarían de coincidir.
 */
export class RedisIoAdapter extends IoAdapter {
  private readonly log = new Logger(RedisIoAdapter.name);
  private adapterConstructor: ReturnType<typeof createAdapter> | null = null;
  private clients: Redis[] = [];

  constructor(app: INestApplicationContext) {
    super(app);
  }

  /** @returns `true` si quedó activo el adapter Redis. */
  async connect(redisUrl: string): Promise<boolean> {
    const pub = new Redis(redisUrl, { lazyConnect: true });
    const sub = pub.duplicate();
    for (const client of [pub, sub]) {
      client.on('error', (error: Error) =>
        this.log.warn(`Redis (socket.io): ${error.message}`),
      );
    }
    try {
      await Promise.all([pub.connect(), sub.connect()]);
    } catch (error) {
      this.log.warn(
        `Adapter Redis no disponible, se usa in-memory: ${error instanceof Error ? error.message : String(error)}`,
      );
      pub.disconnect();
      sub.disconnect();
      return false;
    }
    this.clients = [pub, sub];
    this.adapterConstructor = createAdapter(pub, sub);
    return true;
  }

  override createIOServer(port: number, options?: ServerOptions): unknown {
    const server = super.createIOServer(port, options) as {
      adapter: (constructor: unknown) => void;
    };
    if (this.adapterConstructor) server.adapter(this.adapterConstructor);
    return server;
  }

  override async dispose(): Promise<void> {
    await super.dispose();
    this.clients.forEach((client) => client.disconnect());
  }
}

import type Redis from 'ioredis';
import type { INonceStore } from '../nonce.interfaces';

const KEY_PREFIX = 'nonce:';

/**
 * Patrón: Adapter sobre ioredis. `SET NX EX` (claim/issue) y `GETDEL` (consume) son atómicos:
 * dos requests concurrentes con el mismo nonce no pueden ganar ambos (sin ventana get+del).
 */
export class RedisNonceStore implements INonceStore {
  constructor(private readonly redis: Redis) {}

  async issue(nonce: string, ttlSeconds: number): Promise<void> {
    await this.redis.set(`${KEY_PREFIX}${nonce}`, '1', 'EX', ttlSeconds);
  }

  async consume(nonce: string): Promise<boolean> {
    return (await this.redis.getdel(`${KEY_PREFIX}${nonce}`)) !== null;
  }

  async claim(nonce: string, ttlSeconds: number): Promise<boolean> {
    const result = await this.redis.set(
      `${KEY_PREFIX}claimed:${nonce}`,
      '1',
      'EX',
      ttlSeconds,
      'NX',
    );
    return result === 'OK';
  }
}

import { Logger } from '@nestjs/common';
import type { ThrottlerStorage } from '@nestjs/throttler';
import type Redis from 'ioredis';

type ThrottlerStorageRecord = Awaited<
  ReturnType<ThrottlerStorage['increment']>
>;

/**
 * Incremento atómico en Lua (un solo round-trip): cuenta hits en la ventana y, al superar el
 * límite, activa un bloqueo por `blockDuration`. Devuelve [totalHits, ttlRestanteMs, bloqueado,
 * bloqueoRestanteMs].
 */
const INCREMENT_SCRIPT = `
local hitKey = KEYS[1]
local blockKey = KEYS[2]
local ttl = tonumber(ARGV[1])
local limit = tonumber(ARGV[2])
local blockDuration = tonumber(ARGV[3])

local blockTtl = redis.call('PTTL', blockKey)
if blockTtl > 0 then
  local hits = tonumber(redis.call('GET', hitKey) or '0')
  return { hits, redis.call('PTTL', hitKey), 1, blockTtl }
end

local hits = redis.call('INCR', hitKey)
if hits == 1 then redis.call('PEXPIRE', hitKey, ttl) end
local ttlLeft = redis.call('PTTL', hitKey)

if hits > limit then
  redis.call('SET', blockKey, '1', 'PX', blockDuration)
  return { hits, ttlLeft, 1, blockDuration }
end
return { hits, ttlLeft, 0, 0 }
`;

/**
 * Patrón: Adapter de `ThrottlerStorage` sobre Redis (contadores compartidos entre instancias).
 * Falla ABIERTO: si Redis no responde se loguea y no se limita, porque el rate limit es una
 * defensa de capacidad, no de seguridad de datos; tumbar la API por un cache caído es peor.
 */
export class RedisThrottlerStorage implements ThrottlerStorage {
  private readonly logger = new Logger(RedisThrottlerStorage.name);

  constructor(private readonly redis: Redis) {}

  async increment(
    key: string,
    ttl: number,
    limit: number,
    blockDuration: number,
    throttlerName: string,
  ): Promise<ThrottlerStorageRecord> {
    const hitKey = `throttle:${throttlerName}:${key}`;
    try {
      const [totalHits, ttlLeft, blocked, blockLeft] = (await this.redis.eval(
        INCREMENT_SCRIPT,
        2,
        hitKey,
        `${hitKey}:block`,
        ttl,
        limit,
        blockDuration,
      )) as [number, number, number, number];

      return {
        totalHits,
        timeToExpire: Math.max(0, Math.ceil(ttlLeft / 1000)),
        isBlocked: blocked === 1,
        timeToBlockExpire: Math.max(0, Math.ceil(blockLeft / 1000)),
      };
    } catch (error) {
      this.logger.warn(
        `Rate limit omitido (Redis no disponible): ${error instanceof Error ? error.message : String(error)}`,
      );
      return {
        totalHits: 0,
        timeToExpire: Math.ceil(ttl / 1000),
        isBlocked: false,
        timeToBlockExpire: 0,
      };
    }
  }
}

