import { Logger, OnModuleInit } from '@nestjs/common';
import * as nodemailer from 'nodemailer';
import type { Transporter } from 'nodemailer';
import type SMTPTransport from 'nodemailer/lib/smtp-transport';
import {
  EmailProviderError,
  EmailUnavailableError,
} from '../errors/email.errors';
import { RecipientHelper } from '../helpers/recipient.helper';
import type {
  IEmailMessage,
  IEmailSender,
  IEmailSendResult,
} from '../interfaces/email-sender.interface';

export interface ISmtpOptions {
  host: string;
  port: number;
  user?: string;
  password?: string;
  from: string;
  secure?: boolean;
  timeoutMs: number;
}

/** Primer código SMTP de la familia 5xx: rechazo permanente (no se reintenta). */
const PERMANENT_SMTP_CODE = 500;

/** Adapter de `IEmailSender` sobre SMTP (nodemailer). */
export class SmtpEmailSender implements IEmailSender, OnModuleInit {
  readonly provider = 'SMTP';
  private readonly logger = new Logger(SmtpEmailSender.name);
  private readonly transporter: Transporter<SMTPTransport.SentMessageInfo>;
  private available = true;

  constructor(private readonly options: ISmtpOptions) {
    this.transporter = nodemailer.createTransport({
      host: options.host,
      port: options.port,
      secure: options.secure ?? options.port === 465,
      auth:
        options.user !== undefined && options.user !== ''
          ? { user: options.user, pass: options.password }
          : undefined,
      connectionTimeout: options.timeoutMs,
      greetingTimeout: options.timeoutMs,
      socketTimeout: options.timeoutMs,
    });
  }

  /** Verifica la conexión al arrancar SIN bloquear: una falla solo se loguea y queda en `isAvailable()`. */
  async onModuleInit(): Promise<void> {
    try {
      await this.transporter.verify();
      this.available = true;
      this.logger.log(
        `Conexión SMTP verificada ${this.options.host}:${this.options.port}`,
      );
    } catch (error) {
      this.available = false;
      const message = error instanceof Error ? error.message : String(error);
      this.logger.warn(
        `No se pudo verificar SMTP al arrancar | ${RecipientHelper.maskEmailsInText(message)}`,
      );
    }
  }

  isAvailable(): boolean {
    return this.available;
  }

  async send(message: IEmailMessage): Promise<IEmailSendResult> {
    const { to, cc, bcc } = RecipientHelper.normalize(message);
    const from = message.fromName
      ? `"${message.fromName}" <${this.options.from}>`
      : this.options.from;

    try {
      const info = await this.transporter.sendMail({
        from,
        to,
        cc,
        bcc,
        subject: message.subject,
        html: message.html,
        text: message.text,
        replyTo: message.replyTo,
      });
      const accepted = (info.accepted ?? []).map(toAddress);
      const rejected = (info.rejected ?? []).map(toAddress);

      if (accepted.length === 0) {
        throw new EmailProviderError(
          'El servidor SMTP rechazó a todos los destinatarios',
        );
      }
      this.available = true;
      this.logger.log(
        `Correo enviado messageId=${info.messageId ?? ''} destinatarios=${accepted.length}`,
      );
      return { messageId: String(info.messageId ?? ''), accepted, rejected };
    } catch (error) {
      throw this.classify(error);
    }
  }

  private classify(error: unknown): EmailProviderError | EmailUnavailableError {
    if (error instanceof EmailProviderError) return error;

    const detail = error instanceof Error ? error.message : String(error);
    this.logger.error(
      `Error al enviar el correo | ${RecipientHelper.maskEmailsInText(detail)}`,
    );

    const code = (error as { responseCode?: number } | undefined)?.responseCode;
    if (typeof code === 'number' && code >= PERMANENT_SMTP_CODE) {
      return new EmailProviderError(
        'El servidor SMTP rechazó el mensaje',
        String(code),
      );
    }
    return new EmailUnavailableError('El servidor SMTP no está disponible');
  }
}

const toAddress = (recipient: string | { address: string }): string =>
  typeof recipient === 'string' ? recipient : recipient.address;

export class SocketThrottle {
  private readonly hits = new Map<string, number[]>();

  constructor(
    private readonly limit: number,
    private readonly windowMs: number,
  ) {}

  /** `true` si el mensaje entra en el cupo; `false` si el socket excedió el límite. */
  consume(socketId: string, now: number = Date.now()): boolean {
    const recent = (this.hits.get(socketId) ?? []).filter(
      (at) => now - at < this.windowMs,
    );
    if (recent.length >= this.limit) {
      this.hits.set(socketId, recent);
      return false;
    }
    recent.push(now);
    this.hits.set(socketId, recent);
    return true;
  }

  release(socketId: string): void {
    this.hits.delete(socketId);
  }
}

import {
  IBuiltWhere,
  IWhereClause,
  IWhereOptions,
} from '@common/interfaces/build-where.interface';

const ALLOWED_OPERATORS: ReadonlySet<string> = new Set([
  '=',
  '<>',
  '>',
  '>=',
  '<',
  '<=',
  'LIKE',
  'NOT LIKE',
  'IN',
  'NOT IN',
]);
const IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;

/**
 * Patrón: builder estático puro (SRP/DRY) para SQL crudo parametrizado. Nunca concatena VALORES en
 * el SQL: todo valor sale como `:placeholder` + `replacements`. Lo que sí se interpola (columnas,
 * operadores, ORDER BY) pasa por whitelist. Sirve para cualquier dialecto con `:named` replacements.
 */
export class SqlQueryHelper {
  /**
   * Arma el `WHERE` dinámico a partir de un mapa de filtros.
   * - `=`/`LIKE`/...: `col OP :key`
   * - `IN` con array: `col IN (:key_0, :key_1)`. El dialecto IBM i NO expande arrays en `IN (:param)`,
   *   hay que generar un placeholder por valor (por eso este helper).
   * - `rawCondition`: condición libre, solo si el filtro trae valor.
   * - Valores vacíos (`undefined`, `null`, `''`, `[]`) omiten el filtro: se pueden pasar todos los
   *   filtros posibles y el helper descarta los no enviados.
   */
  static buildWhereClause(
    filters: Record<string, IWhereClause>,
    options?: IWhereOptions,
  ): IBuiltWhere {
    const conditions: string[] = [];
    const replacements: Record<string, unknown> = {};

    for (const [key, filter] of Object.entries(filters)) {
      if (!IDENTIFIER.test(key)) {
        throw new Error(`Nombre de filtro inválido: ${key}`);
      }
      if (this.isEmpty(filter.value)) continue;

      if (filter.rawCondition) {
        conditions.push(filter.rawCondition);
        if (new RegExp(`:${key}(?![A-Za-z0-9_])`).test(filter.rawCondition)) {
          replacements[key] = filter.value;
        }
        continue;
      }

      const operator = (filter.operator ?? '=').toUpperCase();
      if (!filter.column || !ALLOWED_OPERATORS.has(operator)) {
        throw new Error(`Filtro ${key}: columna u operador inválido`);
      }
      const column = filter.transform
        ? filter.transform(filter.column)
        : filter.column;

      if (Array.isArray(filter.value)) {
        const { placeholders, replacements: inReplacements } =
          this.buildInPlaceholders(key, filter.value);
        conditions.push(`${column} ${operator} (${placeholders})`);
        Object.assign(replacements, inReplacements);
      } else {
        conditions.push(`${column} ${operator} :${key}`);
        replacements[key] = filter.value;
      }
    }

    const prefix = options?.hasExistingWhere ? ' AND ' : ' WHERE ';
    return {
      whereClause:
        conditions.length > 0 ? `${prefix}${conditions.join(' AND ')}` : '',
      replacements,
    };
  }

  /** `:key_0, :key_1, ...` y sus replacements (para `IN (...)` y `UPDATE ... WHERE ... IN (...)`). */
  static buildInPlaceholders(
    key: string,
    values: readonly unknown[],
  ): { placeholders: string; replacements: Record<string, unknown> } {
    const replacements: Record<string, unknown> = {};
    const placeholders = values
      .map((value, index) => {
        replacements[`${key}_${index}`] = value;
        return `:${key}_${index}`;
      })
      .join(', ');
    return { placeholders, replacements };
  }

  /** `%VALUE%` en mayúsculas y sin espacios laterales, para `LIKE` sobre columnas normalizadas con UPPER(TRIM()). */
  static likeWrap(value: string): string {
    return `%${String(value).toUpperCase().trim()}%`;
  }

  /**
   * `ORDER BY` seguro: la columna sale de una whitelist (`columns`), nunca del input. Formato de
   * entrada `campo:asc|desc`. Un campo desconocido cae al default.
   * @param tieBreaker Columna final para orden determinístico (obligatorio con paginación).
   */
  static buildOrderBy(
    orderBy: string | undefined,
    columns: Readonly<Record<string, string>>,
    defaults: { field: string; direction?: 'ASC' | 'DESC' },
    tieBreaker?: string,
  ): string {
    const [rawField, rawDirection] = (orderBy ?? '').split(':');
    const known = Boolean(rawField) && Object.hasOwn(columns, rawField);
    const field = known ? rawField : defaults.field;
    const direction = known
      ? rawDirection?.toLowerCase() === 'desc'
        ? 'DESC'
        : 'ASC'
      : (defaults.direction ?? 'ASC');
    const parts = [`${columns[field]} ${direction}`];
    if (tieBreaker && tieBreaker !== columns[field]) parts.push(tieBreaker);
    return ` ORDER BY ${parts.join(', ')}`;
  }

  /**
   * Paginación DB2: `OFFSET :offset ROWS FETCH NEXT :pageSize ROWS ONLY`. Exige un `ORDER BY` previo
   * (sin él las páginas no son determinísticas). Los números se fuerzan a `Number`.
   */
  static buildPagination(
    orderByClause: string,
    page: number,
    pageSize: number,
  ): { clause: string; replacements: { offset: number; pageSize: number } } {
    if (!/\bORDER BY\b/i.test(orderByClause)) {
      throw new Error('La paginación OFFSET/FETCH requiere ORDER BY');
    }
    const size = Math.max(1, Number(pageSize) || 10);
    const current = Math.max(1, Number(page) || 1);
    return {
      clause: `${orderByClause} OFFSET :offset ROWS FETCH NEXT :pageSize ROWS ONLY`,
      replacements: { offset: (current - 1) * size, pageSize: size },
    };
  }

  private static isEmpty(value: unknown): boolean {
    return (
      value === undefined ||
      value === null ||
      value === '' ||
      (Array.isArray(value) && value.length === 0)
    );
  }
}

import { BadRequestException } from '@nestjs/common';
import { StorageUploadInput } from '../interfaces/storage.interface';

export class StorageHelper {
  /**
   * Construye un path normalizado: "onboarding/123/documents"
   */
  static buildPath(...segments: string[]): string {
    return segments
      .filter(Boolean)
      .map((s) => s.trim().replace(/^\/+|\/+$/g, ''))
      .join('/');
  }

  /**
   * Valida si un usuario tiene permiso sobre un objeto (Contexto)
   * Regla: La key debe empezar con el ID del usuario o su contexto
   */
  static isOwner(userContextId: string, objectKey: string): boolean {
    return (
      objectKey.startsWith(userContextId) ||
      objectKey.includes(`/${userContextId}/`)
    );
  }

  static normalizeKey(
    value: string | undefined,
    fieldName: 'key' | 'path',
  ): string {
    const normalizedValue = value?.trim().replace(/^\/+|\/+$/g, '');

    if (!normalizedValue) {
      throw new BadRequestException(`A valid ${fieldName} is required`);
    }

    if (
      normalizedValue
        .split('/')
        .some((segment) => segment === '.' || segment === '..' || !segment)
    ) {
      throw new BadRequestException(`The provided ${fieldName} is invalid`);
    }

    return normalizedValue;
  }

  static validateFileInput(fileInput: StorageUploadInput): void {
    if (!fileInput.file) {
      throw new BadRequestException('A valid file is required');
    }

    if (!fileInput.key && !fileInput.path) {
      throw new BadRequestException('A key or path is required');
    }

    if (!fileInput.file.buffer?.length) {
      throw new BadRequestException('The file content is empty');
    }
  }

  static resolvePositiveNumber(value: number, fieldName: string): number {
    if (!Number.isInteger(value) || value < 1) {
      throw new BadRequestException(`${fieldName} must be greater than 0`);
    }

    return value;
  }

  static resolveFileName(fileInput: StorageUploadInput): string {
    const rawFileName = fileInput.fileName ?? fileInput.file.originalname;
    const fileName: string | undefined = rawFileName
      .split(/[/\\]/)
      .pop()
      ?.trim();

    if (!fileName) {
      throw new BadRequestException('A valid file name is required');
    }

    return fileName;
  }

  static resolveUploadKey(fileInput: StorageUploadInput): string {
    if (fileInput.key) {
      return this.normalizeKey(fileInput.key, 'key');
    }

    const path = this.normalizeKey(fileInput.path, 'path');
    const fileName = this.resolveFileName(fileInput);

    return `${path}/${fileName}`;
  }

  static resolvePresignedUrlExpiresIn(value?: number): number {
    const expiresIn: number = value ?? 900;

    if (!Number.isInteger(expiresIn) || expiresIn < 1) {
      throw new BadRequestException('expiresInSeconds must be greater than 0');
    }

    return expiresIn;
  }

  static isRetryable(error: any): boolean {
    const status = error?.$metadata?.httpStatusCode;
    return status === 429 || status >= 500;
  }
}

