const TRANSIENT_CODES: ReadonlySet<string> = new Set([
  // Node / red
  'ECONNREFUSED',
  'ECONNRESET',
  'ETIMEDOUT',
  'EHOSTUNREACH',
  'ENETUNREACH',
  'EPIPE',
  // PostgreSQL: too_many_connections, cannot_connect_now (arrancando/apagando)
  '53300',
  '57P03',
  // Prisma: no se alcanza la DB (P1001), timeout de DB (P1002/P1008),
  // conexión cerrada (P1017), timeout del pool de conexiones (P2024)
  'P1001',
  'P1002',
  'P1008',
  'P1017',
  'P2024',
]);

const TRANSIENT_MESSAGE_PATTERNS: readonly string[] = [
  'timeout exceeded when trying to connect',
  'connection terminated due to connection timeout',
  'connection terminated unexpectedly',
  'timed out fetching a new connection from the connection pool',
  'remaining connection slots are reserved',
];

function readStringProp(source: unknown, prop: string): string | undefined {
  if (typeof source !== 'object' || source === null) return undefined;
  const value = (source as Record<string, unknown>)[prop];
  return typeof value === 'string' ? value : undefined;
}

export class TransientConnectionErrorHelper {
  /**
   * @param error Error de forma desconocida (pg, Prisma, axios, red)
   * @returns `true` si matchea un código/mensaje transitorio conocido (también mira `cause`)
   */
  static isTransient(error: unknown, depth = 0): boolean {
    if (error === null || error === undefined || depth > 2) return false;

    const codes = [
      readStringProp(error, 'code'),
      readStringProp(error, 'errorCode'),
    ];
    if (codes.some((code) => code !== undefined && TRANSIENT_CODES.has(code))) {
      return true;
    }

    const message = (
      error instanceof Error
        ? error.message
        : (readStringProp(error, 'message') ?? '')
    ).toLowerCase();
    if (TRANSIENT_MESSAGE_PATTERNS.some((p) => message.includes(p))) {
      return true;
    }

    const cause =
      typeof error === 'object'
        ? (error as { cause?: unknown }).cause
        : undefined;
    return cause !== undefined && this.isTransient(cause, depth + 1);
  }
}

import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Response } from 'express';
import { TransientConnectionErrorHelper } from '@common/helpers/transient-connection-error.helper';
import { t } from '@common/i18n/i18n.helper';

/**
 * Patrón: decorator de filtros (chain of responsibility). Captura fallas transitorias de
 * conexión no-HTTP y responde 503 + Retry-After; todo lo demás se delega al filtro fallback,
 * así el cliente puede reintentar en vez de ver un 500 genérico.
 */
@Catch()
export class TransientConnectionExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(TransientConnectionExceptionFilter.name);

  constructor(
    private readonly fallback: ExceptionFilter,
    private readonly retryAfterSeconds = 5,
  ) {}

  catch(exception: unknown, host: ArgumentsHost): void {
    if (
      exception instanceof HttpException ||
      !TransientConnectionErrorHelper.isTransient(exception)
    ) {
      this.fallback.catch(exception, host);
      return;
    }

    this.logger.warn(
      `Falla transitoria de conexión: ${exception instanceof Error ? exception.message : String(exception)}`,
    );
    const response = host.switchToHttp().getResponse<Response>();
    response
      .status(HttpStatus.SERVICE_UNAVAILABLE)
      .setHeader('Retry-After', String(this.retryAfterSeconds))
      .json({
        statusCode: HttpStatus.SERVICE_UNAVAILABLE,
        message: t('common.SERVICE_UNAVAILABLE'),
      });
  }
}

